class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        WindowCompat.setDecorFitsSystemWindows(window, false)
        WindowInsetsControllerCompat(window, window.decorView).apply {
            hide(WindowInsetsCompat.Type.systemBars())
            systemBarsBehavior = WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE
        }
        com.zenvex.online.Integrity.check(this)
        Settings.load(this)
        com.zenvex.online.Thermal.init(this)
        com.zenvex.online.Legal.init(this)
        Account.init(this)
        if (Account.loggedIn) runCatching { com.zenvex.online.Notifier.schedule(this) }
        GameSession.init(this)
        // 3B karakter/silah/araç modelleri arka planda yüklenir (oyuna girene dek hazır)
        com.zenvex.online.Model3D.init(this)
        Audio.init(this)
        // otomatik gösterim yalnız hata ayıklama sürümünde (yayın sürümünde çevrimdışı oynamaya kapı açmasın)
        com.zenvex.online.Demo.on = BuildConfig.DEBUG && intent?.getBooleanExtra("demo", false) == true

        setContent {
            // Kısayol (yalnız hata ayıklama sürümü): adb shell am start -n com.zenvex.online/.MainActivity --es screen Lobby
            val start = intent?.getStringExtra("screen")?.takeIf { BuildConfig.DEBUG }
                ?.let { n -> Screen.entries.firstOrNull { it.name == n && it != Screen.Game } } ?: Screen.Splash
            var screen by remember { mutableStateOf(start) }
            var settingsFrom by remember { mutableStateOf(Screen.Lobby) }
            var epoch by remember { mutableIntStateOf(0) }
            val go: (Screen) -> Unit = {
                if (it == Screen.Settings) settingsFrom = screen
                if (it == Screen.Lobby) epoch++
                screen = it
            }
            LaunchedEffect(screen) { Audio.music(if (screen == Screen.Game) "music_game" else "music_lobby") }
            BackHandler(enabled = screen == Screen.Settings) { go(settingsFrom) }
            Box(Modifier.fillMaxSize().background(Pal.Bg)) {
                val reset = {
                    GameSession.resetSave()
                    Toaster.show("Bu sunucudaki ilerleme silindi.", false); go(Screen.Lobby)
                }
                AnimatedContent(screen, transitionSpec = { fadeIn(tween(260)) togetherWith fadeOut(tween(200)) }, label = "screen") { s ->
                    when (s) {
                        // ilk açılış: önce dil (cihaz dili seçili gelir), sonra doğrudan lobi ve giriş
                        Screen.Splash -> SplashScreen { screen = Screen.Lobby }
                        Screen.Lobby -> LobbyScreen(go, epoch)
                        Screen.Settings -> SettingsScreen(back = { go(settingsFrom) }, onReset = reset)
                        Screen.Loading -> LoadingScreen(back = { go(Screen.Lobby) }) { screen = Screen.Game }
                        Screen.Game -> GameScreen(toLobby = { go(Screen.Lobby) })
                    }
                }
                com.zenvex.online.GateHost()
                com.zenvex.online.LegalHost()
                ToastHost()
            }
        }
    }

    /** Sistem belleği azalınca: görünmeyen yaratık sayfaları ve 3B kare önbelleği boşaltılır (1 GB cihazlarda öldürülmeyelim) */
    @Suppress("DEPRECATION")
    override fun onTrimMemory(level: Int) {
        super.onTrimMemory(level)
        if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW) {
            runCatching { com.zenvex.online.Atlas.get(this).trim(if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN) 0L else 10_000L) }
            com.zenvex.online.Model3D.dropCache()
            com.zenvex.online.SpriteCache.clear()
        }
    }

    override fun onPause() {
        super.onPause()
        com.zenvex.online.Notifier.foreground = false
        GameSession.save(cloud = true)
        GameSession.flush()
        Audio.pauseMusic()
    }

    override fun onStop() {
        super.onStop()
        com.zenvex.online.Session.onBackground()
    }

    override fun onStart() {
        super.onStart()
        com.zenvex.online.Session.onForeground()
        com.zenvex.online.Online.onForeground()
    }

    override fun onResume() {
        super.onResume()
        com.zenvex.online.Store.attach(this)
        com.zenvex.online.Notifier.foreground = true
        Audio.resumeMusic()
    }
}

