// com/zenvex/online/game/Notifier.kt
// ====================================================================================================

/**
 * Cihaz bildirimleri: posta/hediye, özel mesaj, etkinlik duyurusu, arkadaşlık isteği, klan daveti.
 * Arka plandaki işçi 15 dakikada bir sunucuya sorar (zx_notify); oyun açıkken bildirim gösterilmez (oyunda rozetler var).
 * Her tür Ayarlar > Bildirimler'den ayrı kapatılır. Etkinlik duyurusu ticari elektronik iletidir (6563): yalnız oyuncu
 * açıkça onay verdiyse gönderilir (varsayılan kapalı) ve her bildirimde tek dokunuşla ret düğmesi bulunur.
 */
object Notifier {
    const val CH_MAIL = "posta"
    const val CH_DM = "mesaj"
    const val CH_EVENT = "etkinlik"
    @Volatile var foreground = false

    /** Bildirim türleri (Ayarlar > Bildirimler): posta/hediye, özel mesaj, arkadaşlık ve klan */
    const val K_MAIL = "n_mail"
    const val K_DM = "n_dm"
    const val K_SOCIAL = "n_social"
    fun enabled(ctx: Context, k: String) = ctx.getSharedPreferences(Legal.PREFS, Context.MODE_PRIVATE).getBoolean(k, true)
    fun setEnabled(ctx: Context, k: String, on: Boolean) = ctx.getSharedPreferences(Legal.PREFS, Context.MODE_PRIVATE).edit().putBoolean(k, on).apply()

    fun channels(ctx: Context) {
        if (Build.VERSION.SDK_INT < 26) return
        val nm = ctx.getSystemService(NotificationManager::class.java) ?: return
        nm.createNotificationChannel(NotificationChannel(CH_MAIL, "Posta Ve Hediyeler", NotificationManager.IMPORTANCE_DEFAULT))
        nm.createNotificationChannel(NotificationChannel(CH_DM, "Özel Mesajlar", NotificationManager.IMPORTANCE_HIGH))
        nm.createNotificationChannel(NotificationChannel(CH_EVENT, "Etkinlik Duyuruları", NotificationManager.IMPORTANCE_DEFAULT))
    }

    /** Giriş yapılıysa düzenli kontrolü kurar (aynı iş tekrar kurulmaz). */
    fun schedule(ctx: Context) {
        channels(ctx)
        val req = PeriodicWorkRequestBuilder<Worker>(15, TimeUnit.MINUTES)
            .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
            .build()
        WorkManager.getInstance(ctx).enqueueUniquePeriodicWork("zx_notify", ExistingPeriodicWorkPolicy.KEEP, req)
    }

    fun cancel(ctx: Context) = WorkManager.getInstance(ctx).cancelUniqueWork("zx_notify")

    /** Bir kez sor ve göster (işçi ve test için). */
    fun poll(ctx: Context) {
        val prefs = ctx.getSharedPreferences("account", Context.MODE_PRIVATE)
        val key = prefs.getString("key", "") ?: ""
        val id = prefs.getLong("id", -1L)
        if (key.isEmpty() || id < 0) return
        val np = ctx.getSharedPreferences("notify", Context.MODE_PRIVATE)
        // ilk çalışmada geçmiş birikmiş postalar için bildirim yağmuru olmasın
        val since = np.getLong("since", System.currentTimeMillis())
        val o = JSONObject(Supa.rpcSync("zx_notify", JSONObject().put("p_id", id).put("p_key", key).put("p_since", since)))
        np.edit().putLong("since", o.optLong("now", System.currentTimeMillis())).apply()
        if (foreground) return
        show(ctx, o)
    }

    fun show(ctx: Context, o: JSONObject) {
        val mails = if (enabled(ctx, K_MAIL)) o.optJSONArray("mails") else null
        for (i in 0 until (mails?.length() ?: 0)) {
            val m = mails!!.getJSONObject(i)
            val gift = m.optInt("gems") > 0 || m.optInt("gold") > 0 || m.optInt("items") > 0
            val title = when (m.optString("kind")) { "event" -> "Etkinlik Ödülü!"; "system" -> "Sistem Mesajı"; else -> if (gift) "Hediye Geldi!" else "Yeni Posta" }
            val parts = buildList {
                if (m.optInt("gems") > 0) add("${m.optInt("gems")} Elmas")
                if (m.optInt("gold") > 0) add("${m.optInt("gold")} Altın")
                if (m.optInt("items") > 0) add("${m.optInt("items")} Eşya")
            }
            post(ctx, CH_MAIL, 1000 + (m.optLong("id") % 100000).toInt(), title,
                m.optString("title") + (if (parts.isNotEmpty()) " · " + parts.joinToString(", ") else "") + " — " + m.optString("sender"))
        }
        val dms = if (enabled(ctx, K_DM)) o.optJSONArray("dms") else null
        for (i in 0 until (dms?.length() ?: 0)) {
            val d = dms!!.getJSONObject(i)
            val n = d.optInt("n")
            post(ctx, CH_DM, 3000 + d.optString("from").hashCode() % 1000, d.optString("from") + if (n > 1) " ($n Mesaj)" else "", d.optString("text"))
        }
        // ticari ileti: yalnız onay varsa; gönderen belli, ret yolu bildirimin içinde
        if (Legal.promoAllowed(ctx)) o.optJSONObject("event")?.let { e ->
            post(ctx, CH_EVENT, 5000, "Yeni Etkinlik: " + e.optString("title"),
                "Zenvex Online'da yeni bir etkinlik başladı; ayrıntılar oyunda. Bu duyuruları almak istemiyorsan \"Bu Duyuruları Kapat\"a dokun.", promo = true)
        }
        if (enabled(ctx, K_SOCIAL) && o.optInt("friends") > 0) post(ctx, CH_DM, 6000, "Arkadaşlık İsteği", "${o.optInt("friends")} yeni arkadaşlık isteğin var.")
        if (enabled(ctx, K_SOCIAL) && o.optInt("invites") > 0) post(ctx, CH_MAIL, 6001, "Klan Daveti", "Bir klan seni aralarına çağırıyor.")
    }

    private fun post(ctx: Context, ch: String, id: Int, title: String, text: String, promo: Boolean = false) {
        if (!NotificationManagerCompat.from(ctx).areNotificationsEnabled()) return
        val pi = PendingIntent.getActivity(ctx, 0, Intent(ctx, MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT)
        val b = NotificationCompat.Builder(ctx, ch)
            .setSmallIcon(R.drawable.ic_notify)
            .setColor(0xFFFFB347.toInt())
            .setContentTitle(title)
            .setContentText(text)
            .setStyle(NotificationCompat.BigTextStyle().bigText(text))
            .setAutoCancel(true)
            .setContentIntent(pi)
        if (promo) {
            val off = PendingIntent.getBroadcast(ctx, 1, Intent(ctx, PromoOptOut::class.java).putExtra("id", id), PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT)
            b.addAction(0, "Bu Duyuruları Kapat", off)
        }
        runCatching { NotificationManagerCompat.from(ctx).notify(id, b.build()) }
    }

    /** Bildirimdeki "Bu Duyuruları Kapat": ticari ileti onayı geri alınır ve sunucuya kaydedilir (6563 m.8: kolay ret). */
    class PromoOptOut : android.content.BroadcastReceiver() {
        override fun onReceive(ctx: Context, intent: Intent) {
            ctx.getSharedPreferences(Legal.PREFS, Context.MODE_PRIVATE).edit().putBoolean(Legal.KEY_PROMO, false).apply()
            Legal.promo.value = false
            runCatching { NotificationManagerCompat.from(ctx).cancel(intent.getIntExtra("id", 5000)) }
            val ap = ctx.getSharedPreferences("account", Context.MODE_PRIVATE)
            val key = ap.getString("key", "").orEmpty(); val acc = ap.getLong("id", -1L)
            if (key.isEmpty() || acc < 0) return
            val pending = goAsync()
            Thread {
                runCatching {
                    Supa.rpcSync("zx_consent", JSONObject().put("p_id", acc).put("p_key", key).put("p_kind", "promo").put("p_version", 0).put("p_granted", false))
                }
                pending.finish()
            }.start()
        }
    }

    class Worker(ctx: Context, params: WorkerParameters) : CoroutineWorker(ctx, params) {
        override suspend fun doWork(): Result = runCatching { poll(applicationContext) }.fold({ Result.success() }, { Result.retry() })
    }
}

// ====================================================================================================
// com/zenvex/online/game/Online.kt
// ====================================================================================================

/**
 * Çevrimiçi dünya: Supabase Realtime, "ev sahibi" modeli. İki kanal: sunucu kanalı (`zx-<sunucu>`: presence, sohbet,
 * fısıltı, takas) ve bulunulan bölgenin kanalı (`zx-<sunucu>-a<bölge>`: konum, zombi, vuruş, PvP).
 *  presence  isim / klan (kim bağlı)
 *  p         konum + görünüm (hareket ederken 3,3 Hz, dururken 2 sn'de bir; yalnız aynı bölge)
 *  z         ev sahibinin zombi anlık görüntüsü (2,5 Hz)
 *  hit       istemcinin zombi vuruşu → ev sahibi uygular
 *  kill      öldürme ödülü → vuran oyuncu
 *  pd        zombi hasarı → hedef oyuncu
 *  c         sohbet (genel / yakın); genel sohbet ayrıca veritabanına yazılır (geçmiş)
 *  treq, tr  takas isteği ve takas teklifleri
 *  pvp       oyuncu vuruşu → hedef (hasarı hedefin cihazı, PvP bölgesindeyse uygular)
 *  pvpk      öldürme bildirimi → öldüren
 * Ev sahibi: bölgedeki oyuncular arasında en küçük kimlik. O ayrılırsa sıradaki devralır.
 */
object Online {
    /** [avatar]/[frame]: gönderenin profil resmi ve çerçevesi (sohbette yanında çizilir; -1: bilinmiyor) */
    /** [uid]: gönderenin oyun kimliği ("a<hesap>"); sohbette adına dokununca oyuncu menüsü açılır */
    data class ChatLine(val channel: String, val name: String, val text: String, val tag: String, val mine: Boolean, val ts: Long,
                        val avatar: Int = -1, val frame: String = "", val uid: String = "")

    private fun myAvatar() = Account.profile.value.optInt("avatar", 1)
    private fun myFrame() = Account.profile.value.optString("frame").takeIf { it != "null" } ?: ""
    data class Near(val uid: String, val name: String, val x: Float, val y: Float, val vehicle: Int, val dist: Float)
    /** Teklifteki eşya: tekil ekipmanda çantadaki yuvası ve dayanıklılığı (binde) da taşınır */
    data class TradeItem(val id: String, val n: Int, val slot: Int = -1, val dur: Int = 1000)
    data class TradeState(
        val sid: String, val other: String, val otherName: String,
        val mine: List<TradeItem>, val theirs: List<TradeItem>, val myOk: Boolean, val theirOk: Boolean, val done: Boolean,
        /** sunucudaki emanetli takas numarası (0 = henüz açılmadı) */
        val tid: Long = 0,
        /** karşı teklifin son değiştiği an (ms): değişince onay tuşu 3 sn kilitlenir */
        val theirsAt: Long = 0,
        /** ben hazırken karşı taraf teklifini değiştirdi: takas tamamlanamaz, iptal edip yeniden başlatılmalı */
        val changedAfterReady: Boolean = false,
    )

    val status = mutableStateOf("Çevrimdışı")
    val online = mutableStateOf(false)
    val playerCount = mutableIntStateOf(1)
    val role = mutableStateOf("Tek oyunculu")
    val chat = mutableStateListOf<ChatLine>()
    val tradeRequest = mutableStateOf<Pair<String, String>?>(null) // (uid, isim)
    val trade = mutableStateOf<TradeState?>(null)
    @Volatile var onChat: ((ChatLine) -> Unit)? = null

    private val main = Handler(Looper.getMainLooper())
    private var channel: com.zenvex.online.Link? = null
    /** kendi oyun sunucumuz kullanılıyorsa (Account.gameServer dolu ve oturum açık): tek bağlantı, oda = bölge */
    private var gameNet: com.zenvex.online.GameNet? = null
    /** oyun sunucusunun bu bölge için seçtiği ev sahibi */
    @Volatile private var hostUid = ""
    /**
     * Bölge kanalı (`zx-<sunucu>-a<bölge>`): konum, zombi ve vuruş yalnız aynı bölgedekilere gider. Ana kanal sohbet,
     * kimlik (presence), takas ve fısıltı için. Supabase her yayını alıcı sayısı kadar sayar; bölgelere bölmek ve
     * seyrek göndermek (duran oyuncu 2 sn'de bir) mesaj sayısını ~10 kat düşürür.
     */
    private var areaCh: com.zenvex.online.Link? = null
    /** konum / zombi / vuruş bağlantısı: oyun sunucusu ya da Supabase bölge kanalı */
    private val areaLink: com.zenvex.online.Link? get() = gameNet ?: areaCh
    private var areaIdx = -1
    private var areaList: List<com.zenvex.online.MapArea>? = null
    private val lastSent = FloatArray(Native.REMOTE_STRIDE)
    private var lastSentAt = 0L
    private var serverId = ""
    @Volatile var uid: String = ""
        private set
    private var name = "Oyuncu"
    private var tag = ""

    private class Remote(var name: String, var clan: String = "", var title: String = "", var titleRank: Int = 0, var skin: String = "") {
        val cur = FloatArray(Native.REMOTE_STRIDE)
        val target = FloatArray(Native.REMOTE_STRIDE)
        var ts = 0L
        /** iki yayın arası hız (px/sn): yayınlar arasında konum ileri tahmin edilir */
        var vx = 0f
        var vy = 0f
        var present = true
    }
    private val remotes = HashMap<String, Remote>()
    private var lastRemotes = 0L
    private val local = FloatArray(Native.REMOTE_STRIDE)
    private var lastPub = 0L
    private var lastSnap = 0L
    @Volatile var myX = 0f
        private set
    @Volatile var myY = 0f
        private set
    private var mode = 0
    private val snapBuf = FloatArray(12 * 80)
    @Volatile private var pendingSnap: FloatArray? = null
    private val hitQ = ConcurrentLinkedQueue<JSONObject>()
    private val cmdQ = ConcurrentLinkedQueue<JSONObject>()
    private val killerIds = ArrayList<String>()
    @Volatile var lastNames: Array<String> = emptyArray()
        private set
    @Volatile var lastClans: Array<String> = emptyArray()
        private set
    /** Görünen oyuncuların seçili unvanı ("Canavar Avcısı #1") ve sırası (isim etiketinin üstünde, ilk 3 efektli) */
    @Volatile var lastTitles: Array<Pair<String, Int>> = emptyArray()
        private set
    /** görünen oyuncuların karakter kaplaması (Elmas Sandığı) */
    @Volatile var lastSkins: Array<String> = emptyArray()
        private set
    @Volatile var lastIds: Array<String> = emptyArray()
        private set

    /** Seçili sunucunun kanalına bağlanır (zaten bağlıysa yalnızca kimliği günceller). */
    fun start(playerName: String, playerTag: String) {
        name = playerName; tag = playerTag
        if (!Integrity.ok) { status.value = Integrity.reason; return }
        val sid = GameSession.server.value.id
        val me = if (Account.loggedIn) "a${Account.id.value}" else guestId()
        if (channel != null && sid == serverId && me == uid) { trackMe(); return }
        stop()
        if (!Supa.configured) { status.value = "Çevrimdışı (sunucu ayarlanmadı)"; return }
        serverId = sid
        uid = me
        chat.clear()
        Account.recentChat(sid) { r ->
            r.onSuccess { arr ->
                for (i in 0 until arr.length()) {
                    val o = arr.getJSONObject(i)
                    chat += ChatLine("global", o.optString("n"), o.optString("m"), (if (o.isNull("g")) "" else o.optString("g")), "a${o.optLong("u")}" == uid, o.optLong("ts"),
                        o.optInt("av", -1), o.optString("fr").takeIf { it != "null" } ?: "", "a${o.optLong("u")}")
                }
            }
        }
        val onStatus = { s: String -> main.post { status.value = s; online.value = s == "Çevrimiçi" }; Unit }
        val gs = Account.gameServer
        channel = if (gs.isNotEmpty() && Account.loggedIn && Session.sid.isNotEmpty()) {
            com.zenvex.online.GameNet(gs, { Session.netHello(sid, myMeta()) }, ::onBroadcast, ::onPresence, onStatus) { h -> hostUid = h }
                .also { gameNet = it; it.open() }
        } else Supa.Channel(
            topic = "realtime:zx-$sid",
            presenceKey = uid,
            onBroadcast = ::onBroadcast,
            onPresence = ::onPresence,
            onStatus = onStatus,
        ).also { it.open() }
        trackMe()
    }

    private fun guestId(): String {
        val p = GameSession.prefs()
        var g = p.getString("guest", null)
        if (g == null) { g = "g" + java.util.UUID.randomUUID().toString().take(8); p.edit().putString("guest", g).apply() }
        return g
    }

    fun stop() {
        channel?.close()
        channel = null
        gameNet = null
        hostUid = ""
        areaCh?.close()
        areaCh = null
        areaIdx = -1
        synchronized(remotes) { remotes.clear() }
        online.value = false
        status.value = "Çevrimdışı"
        playerCount.intValue = 1
        trade.value = null
        tradeRequest.value = null
        mode = 0
    }

    /** Uygulama öne geldi: kopmuş kanal hemen yeniden bağlansın */
    fun onForeground() { channel?.reconnectNow(); areaCh?.reconnectNow() }

    private fun switchArea(a: Int) {
        areaCh?.close()
        areaIdx = a
        // isim/klan (ana kanaldaki presence) kalır; konumu bilinmeyenler yeni bölgeden yayın gelene dek çizilmez
        synchronized(remotes) { remotes.values.forEach { it.ts = 0L; it.vx = 0f; it.vy = 0f } }
        pendingSnap = null
        gameNet?.let { hostUid = ""; it.area(a); areaCh = null; return }
        areaCh = if (a < 0 || channel == null) null else Supa.Channel(
            topic = "realtime:zx-$serverId-a$a",
            presenceKey = uid,
            onBroadcast = ::onBroadcast,
            onPresence = { _, _, _ -> },
            onStatus = { },
        ).also { it.open() }
    }

    fun setIdentity(playerName: String, playerTag: String) { name = playerName; tag = playerTag; trackMe() }
    /** İsim değişti: sonraki konum paketiyle (≤0,2 sn) diğer oyuncularda da yenilenir */
    fun rename(playerName: String) { name = playerName; trackMe() }
    /** Sunucuya gidiş-dönüş süresi (ms); bağlı değilse -1 */
    fun ping(): Int = channel?.takeIf { it.joined }?.pingMs ?: -1

    /** Unvan değişince yayındaki kimliği yenile */
    fun retrack() = trackMe()

    private fun myMeta(): JSONObject {
        val t = Account.profile.value.optJSONObject("title")
        return JSONObject().put("n", name).put("g", Account.clan.value?.name ?: tag)
            .put("tt", t?.optString("name") ?: "").put("tr", t?.optInt("rank") ?: 0).put("sk", Skins.char)
    }

    private fun trackMe() { channel?.track(myMeta()) }

    // =========================================================== gelen
    private fun onPresence(joins: JSONObject, leaves: JSONObject, full: Boolean) {
        synchronized(remotes) {
            if (full) remotes.values.forEach { it.present = false }
            for (k in joins.keys()) {
                if (k == uid) continue
                val meta = joins.optJSONObject(k)?.optJSONArray("metas")?.optJSONObject(0) ?: continue
                val r = remotes.getOrPut(k) { Remote("") }
                r.name = meta.optString("n", "Oyuncu"); r.clan = if (meta.isNull("g")) "" else meta.optString("g"); r.present = true
                r.title = meta.optString("tt"); r.titleRank = meta.optInt("tr"); r.skin = meta.optString("sk")
            }
            for (k in leaves.keys()) remotes.remove(k)
            if (full) remotes.values.removeAll { !it.present }
            val n = remotes.size + 1
            main.post { playerCount.intValue = n }
        }
    }

    private fun onBroadcast(ev: String, p: JSONObject) {
        val me = uid
        when (ev) {
            "p" -> {
                val k = p.optString("u"); if (k.isEmpty() || k == me) return
                val arr = p.optJSONArray("s") ?: return
                synchronized(remotes) {
                    val r = remotes.getOrPut(k) { Remote(p.optString("n", "Oyuncu")) }
                    p.optString("n").takeIf { it.isNotEmpty() }?.let { r.name = it }
                    val now = SystemClock.elapsedRealtime()
                    val ox = r.target[0]; val oy = r.target[1]
                    for (i in 0 until minOf(arr.length(), Native.REMOTE_STRIDE)) r.target[i] = arr.optDouble(i).toFloat()
                    val gap = (now - r.ts) / 1000f
                    if (r.ts > 0L && gap in 0.05f..1f) {
                        r.vx = (r.target[0] - ox) / gap; r.vy = (r.target[1] - oy) / gap
                        if (hypot(r.vx, r.vy) > 1500f) { r.vx = 0f; r.vy = 0f }  // ışınlanma / seyahat
                    } else { r.vx = 0f; r.vy = 0f }
                    if (r.ts == 0L) System.arraycopy(r.target, 0, r.cur, 0, Native.REMOTE_STRIDE)
                    r.ts = now
                }
            }
            "z" -> if (mode == 2 && p.optString("h") != me) {
                val arr = p.optJSONArray("d") ?: return
                pendingSnap = FloatArray(arr.length()) { arr.optDouble(it).toFloat() }
            }
            "hit" -> if (mode == 1) hitQ += p
            "kill" -> if (p.optString("to") == me) {
                cmdQ += JSONObject().put("cmd", "net_kill").put("kind", p.optInt("kind")).put("level", p.optInt("level"))
                    .put("x", p.optDouble("x")).put("y", p.optDouble("y"))
            }
            "pd" -> if (p.optString("to") == me) cmdQ += JSONObject().put("cmd", "net_pdmg").put("v", p.optInt("v")).put("poison", p.optBoolean("p"))
            "pvp" -> if (p.optString("to") == me) {
                lastPvpFrom = p.optString("u"); lastPvpName = p.optString("n", "Oyuncu"); lastPvpAt = SystemClock.elapsedRealtime()
                cmdQ += JSONObject().put("cmd", "pvp_dmg").put("v", p.optDouble("v").coerceIn(0.0, 400.0))
            }
            "pvpk" -> if (p.optString("to") == me) {
                cmdQ += JSONObject().put("cmd", "pvp_kill")
                main.post { system("${p.optString("n", "Oyuncu")} oyuncusunu öldürdün!") }
            }
            "c" -> {
                val ch = p.optString("ch", "global")
                if (ch != "global" && ch != "clan") return
                // klan sohbeti yalnız aynı klanın üyelerine
                if (ch == "clan" && (p.optLong("cid") != (Account.clan.value?.id ?: -1L))) return
                val g = p.optString("g").takeUnless { it == "null" } ?: ""
                addLine(ChatLine(ch, p.optString("n", "?"), p.optString("m").take(140), g, false, System.currentTimeMillis(),
                    p.optInt("av", -1), p.optString("fr"), p.optString("u")))
            }
            // fısıltı: yalnız alıcı görür (Genel sekmesinde [Fısıltı] etiketiyle)
            "w" -> if (p.optString("to") == me) addLine(ChatLine("global", p.optString("n", "?"), p.optString("m").take(140), "Fısıltı", false, System.currentTimeMillis(),
                p.optInt("av", -1), p.optString("fr"), p.optString("u")))
            "treq" -> if (p.optString("to") == me) main.post { tradeRequest.value = p.optString("u") to p.optString("n", "Oyuncu") }
            "tr" -> if (p.optString("to") == me) main.post { onTradeMsg(p) }
        }
    }

    private fun addLine(l: ChatLine) = main.post {
        chat += l
        while (chat.size > 300) chat.removeAt(0)
        onChat?.invoke(l)
    }

    // =========================================================== sohbet
    /** Sohbet 5. seviyede açılır; iki mesaj arasında 3 sn beklenir (sunucu da denetler). */
    const val CHAT_LEVEL = 5
    const val CHAT_COOLDOWN_MS = 3000L
    private var lastSend = 0L

    /** Kalan bekleme (ms); 0 ise yazılabilir. */
    fun chatWait(): Long = (CHAT_COOLDOWN_MS - (SystemClock.elapsedRealtime() - lastSend)).coerceAtLeast(0L)

    /** Özel mesaj gönderildi: aynı 3 sn bekleme */
    fun markSent() { lastSend = SystemClock.elapsedRealtime() }

    fun chatLocked(): Boolean = GameSession.hud()[Native.LEVEL] < CHAT_LEVEL

    /** Gönderir; olmazsa nedenini döner. */
    fun send(channelName: String, text: String): String? {
        val t = text.trim().take(140)
        if (t.isEmpty()) return null
        if (chatLocked()) return "Sohbet $CHAT_LEVEL. Seviyede Açılır"
        if (channelName == "clan") {
            val c = Account.clan.value ?: return "Bir Klanda Değilsin"
            val mu = c.json.optString("muted_until")
            if (mu.isNotEmpty() && mu != "null" && runCatching { java.time.OffsetDateTime.parse(mu).toInstant().toEpochMilli() > System.currentTimeMillis() }.getOrDefault(false))
                return "Klan Sohbetinde Susturuldun"
        }
        val w = chatWait()
        if (w > 0) return "${(w + 999) / 1000} Sn Bekle"
        lastSend = SystemClock.elapsedRealtime()
        val g = Account.clan.value?.name ?: tag
        addLine(ChatLine(channelName, name, t, g, true, System.currentTimeMillis(), myAvatar(), myFrame(), uid))
        val c = channel ?: return null
        val m = JSONObject().put("u", uid).put("n", name).put("g", g).put("m", t).put("ch", channelName).put("av", myAvatar()).put("fr", myFrame())
        if (channelName == "clan") m.put("cid", Account.clan.value?.id ?: 0)
        c.send("c", m)
        if (channelName == "global") Account.postChat(serverId, t)
        else if (channelName == "clan") Account.chatLog("clan:${Account.clan.value?.id ?: 0}", t)
        return null
    }

    /** Fısıltı: yalnız [toUid] oyuncusuna giden kısa mesaj (sohbet kuralları ve bekleme süresi geçerli). */
    fun whisper(toUid: String, toName: String, text: String): String? {
        val t = text.trim().take(140)
        if (t.isEmpty()) return null
        if (chatLocked()) return "Sohbet $CHAT_LEVEL. Seviyede Açılır"
        val w = chatWait()
        if (w > 0) return "${(w + 999) / 1000} Sn Bekle"
        val c = channel ?: return "Çevrimdışısın"
        lastSend = SystemClock.elapsedRealtime()
        addLine(ChatLine("global", "→ $toName", t, "Fısıltı", true, System.currentTimeMillis(), myAvatar(), myFrame(), uid))
        c.send("w", JSONObject().put("to", toUid).put("u", uid).put("n", name).put("m", t).put("av", myAvatar()).put("fr", myFrame()))
        Account.chatLog("$serverId:whisper:$toUid", t)
        return null
    }

    fun system(text: String) = addLine(ChatLine("system", "Sistem", text, "", false, System.currentTimeMillis()))

    // =========================================================== oyun döngüsü (GameSession.lock altında)
    /** Yerel durumu yayınlar, ev sahibini seçer, kuyruktaki ağ olaylarını uygular. */
    fun tick(h: Long) {
        val now = SystemClock.elapsedRealtime()
        if (now - lastPub >= 100) {
            lastPub = now
            Native.localState(h, local)
            myX = local[0]; myY = local[1]
            if (channel != null) {
                val areas = areaList ?: com.zenvex.online.mapAreas(GameSession.world()).also { areaList = it }
                val a = com.zenvex.online.areaIndexAt(areas, myX, myY)
                if (a != areaIdx) switchArea(a)
            }
            // hareket ediyorsan 3,3 kez/sn, duruyorsan 2 sn'de bir (yalnız bölge kanalına)
            var moved = false
            for (i in local.indices) if (kotlin.math.abs(local[i] - lastSent[i]) > (if (i < 2) 4f else 0.01f)) { moved = true; break }
            val ac = areaLink
            if (ac != null && ac.joined && ((moved && now - lastSentAt >= 300) || now - lastSentAt >= 2000)) {
                lastSentAt = now
                System.arraycopy(local, 0, lastSent, 0, local.size)
                val s = JSONArray()
                for (v in local) s.put((v * 10).toInt() / 10.0)
                ac.send("p", JSONObject().put("u", uid).put("n", name).put("s", s))
            }
            elect(h)
        }
        val c = areaLink
        if (c == null) return
        when (mode) {
            1 -> {
                while (true) {
                    val o = hitQ.poll() ?: break
                    Native.command(h, JSONObject().put("cmd", "net_hit").put("id", o.optLong("id")).put("dmg", o.optDouble("dmg"))
                        .put("kx", o.optDouble("kx")).put("ky", o.optDouble("ky")).put("stun", o.optBoolean("st"))
                        .put("killer", killerIndex(o.optString("u"))).toString())
                }
                if (now - lastSnap >= 400) {
                    lastSnap = now
                    val n = Native.netSnapshot(h, snapBuf)
                    val d = JSONArray()
                    for (i in 0 until n * 12) d.put((snapBuf[i] * 10).toInt() / 10.0)
                    c.send("z", JSONObject().put("h", uid).put("d", d))
                }
            }
            2 -> pendingSnap?.let { p -> pendingSnap = null; Native.netApply(h, p, p.size / 12) }
        }
        while (true) {
            val q = cmdQ.poll() ?: break
            Native.command(h, q.toString())
        }
    }

    private fun elect(h: Long) {
        val now = SystemClock.elapsedRealtime()
        val active = synchronized(remotes) { remotes.filter { now - it.value.ts < 8000 }.keys.toList() }
        val newMode = when {
            channel == null || active.isEmpty() -> 0
            // oyun sunucusu ev sahibini kendisi seçer
            gameNet != null -> if (hostUid == uid) 1 else if (hostUid.isNotEmpty()) 2 else 0
            active.all { uid < it } -> 1
            else -> 2
        }
        if (newMode != mode) {
            mode = newMode
            Native.command(h, JSONObject().put("cmd", "net_mode").put("mode", mode).toString())
            val r = when (mode) { 1 -> "Ev sahibi (zombiler senden)"; 2 -> "Katılımcı"; else -> "Tek oyunculu" }
            main.post { role.value = r }
        }
    }

    private fun killerIndex(u: String): Int {
        if (u.isEmpty()) return -1
        val i = killerIds.indexOf(u)
        if (i >= 0) return i
        killerIds += u
        return killerIds.size - 1
    }

    /** Oyun olaylarından ağ ile ilgili olanlar (GameView çağırır). */
    fun onEvent(e: JSONObject) {
        val c = areaLink ?: return
        when (e.optString("t")) {
            "zhit" -> if (mode == 2) c.send("hit", JSONObject().put("u", uid).put("id", e.optLong("id")).put("dmg", e.optDouble("dmg"))
                .put("kx", e.optDouble("kx")).put("ky", e.optDouble("ky")).put("st", e.optBoolean("stun")))
            "rdmg" -> lastIds.getOrNull(e.optInt("i"))?.let { u ->
                c.send("pd", JSONObject().put("to", u).put("v", e.optInt("v")).put("p", e.optBoolean("poison")))
            }
            "nkill" -> killerIds.getOrNull(e.optInt("k"))?.let { u ->
                c.send("kill", JSONObject().put("to", u).put("kind", e.optInt("kind")).put("level", e.optInt("level"))
                    .put("x", e.optDouble("x")).put("y", e.optDouble("y")))
            }
        }
    }

    /** Uzak oyuncuları ara değerleyerek arabelleğe yazar; sayıyı döndürür (çevrimdışıysa null). */
    fun remotes(out: FloatArray): Int? {
        if (channel == null) return null
        val now = SystemClock.elapsedRealtime()
        val dt = ((now - lastRemotes) / 1000f).coerceIn(0f, 0.1f)
        lastRemotes = now
        val kf = 1f - kotlin.math.exp(-14f * dt)
        synchronized(remotes) {
            var n = 0
            val nm = ArrayList<String>()
            val cl = ArrayList<String>()
            val tl = ArrayList<Pair<String, Int>>()
            val sk = ArrayList<String>()
            val ids = ArrayList<String>()
            for ((k, r) in remotes) {
                if (r.ts == 0L || now - r.ts > 10000) continue
                if ((n + 1) * Native.REMOTE_STRIDE > out.size) break
                if (hypot(r.target[0] - myX, r.target[1] - myY) > 3000f) continue
                // son yayından hızla ileri tahmin (en çok 0.35 sn), oraya kare hızından bağımsız yumuşak takip
                val ahead = ((now - r.ts) / 1000f).coerceIn(0f, 0.35f)
                val tx = r.target[0] + r.vx * ahead; val ty = r.target[1] + r.vy * ahead
                if (hypot(tx - r.cur[0], ty - r.cur[1]) > 300f) { r.cur[0] = tx; r.cur[1] = ty }
                r.cur[0] += (tx - r.cur[0]) * kf
                r.cur[1] += (ty - r.cur[1]) * kf
                for (i in 2 until Native.REMOTE_STRIDE) r.cur[i] = r.target[i]
                r.cur[4] += 1f / 60f
                System.arraycopy(r.cur, 0, out, n * Native.REMOTE_STRIDE, Native.REMOTE_STRIDE)
                nm += r.name
                cl += r.clan
                tl += r.title to r.titleRank
                sk += r.skin
                ids += k
                n++
            }
            lastNames = nm.toTypedArray()
            lastClans = cl.toTypedArray()
            lastTitles = tl.toTypedArray()
            lastSkins = sk.toTypedArray()
            lastIds = ids.toTypedArray()
            return n
        }
    }

    /** Bağlı oyuncular (isim, klan) — oyuncu listesi için. */
    fun players(): List<Pair<String, String>> = synchronized(remotes) { remotes.values.map { it.name to it.clan } }

    /** En yakın uzak oyuncu (takas / yolculuk tuşları için). */
    fun nearest(maxD: Float): Near? = synchronized(remotes) {
        remotes.entries.filter { it.value.ts > 0 }
            .map { (k, r) -> Near(k, r.name, r.cur[0], r.cur[1], r.cur[9].toInt(), hypot(r.cur[0] - myX, r.cur[1] - myY)) }
            .filter { it.dist < maxD }.minByOrNull { it.dist }
    }

    /** Uzak oyuncunun son bildirdiği konum (son 10 sn içinde yayın geldiyse; uzaktaysa da) */
    fun position(u: String): FloatArray? = synchronized(remotes) {
        remotes[u]?.takeIf { it.ts > 0L && SystemClock.elapsedRealtime() - it.ts < 10000 }?.target?.copyOf()
    }

    // =========================================================== PvP
    @Volatile private var lastPvpFrom = ""
    @Volatile private var lastPvpName = ""
    @Volatile private var lastPvpAt = 0L

    /** Yerel vuruş uzak oyuncuya (Rust "pvp" olayı, k = uzak oyuncu sırası). */
    fun sendPvp(k: Int, v: Float, crit: Boolean) {
        val to = lastIds.getOrNull(k) ?: return
        areaLink?.send("pvp", JSONObject().put("to", to).put("u", uid).put("n", name).put("v", v.toDouble()).put("c", crit))
    }

    /** Yerel oyuncu öldü: son 8 sn içinde bir oyuncu vurduysa öldürme ona yazılır. */
    fun onLocalDeath() {
        if (lastPvpFrom.isEmpty() || SystemClock.elapsedRealtime() - lastPvpAt > 8000) return
        areaLink?.send("pvpk", JSONObject().put("to", lastPvpFrom).put("u", uid).put("n", name))
        system("$lastPvpName seni öldürdü")
        lastPvpFrom = ""
    }

    /** Uzak oyuncular düşman mı (klan arkadaşı değilse). */
    fun hostileFlags(myClan: String): JSONArray {
        val a = JSONArray()
        for (c in lastClans) a.put(myClan.isEmpty() || c.isEmpty() || c != myClan)
        return a
    }

    /** Ele geçirme halkasında sahip klandan biri var mı (klan savaşı: savunucu varken ele geçirme durur). */
    fun defenderInRing(owner: String, bx: Float, by: Float, r: Float): Boolean = synchronized(remotes) {
        remotes.values.any { it.clan == owner && it.present && hypot(it.cur[0] - bx, it.cur[1] - by) < r && it.cur[9] < 1f }
    }

    // =========================================================== takas
    // Ekrandaki teklifler kanal üzerinden eşlenir; eşyalar yalnız sunucu emanetiyle el değiştirir (Trade.kt).
    private var myItems: List<TradeItem> = emptyList()
    private var myOk = false

    private fun sid(a: String, b: String) = if (a < b) "${a}_$b" else "${b}_$a"

    fun requestTrade(other: String) {
        val c = channel ?: return
        if (Session.state.value != Session.State.Live) { system("Takas için çevrimiçi olmalısın"); return }
        c.send("treq", JSONObject().put("to", other).put("u", uid).put("n", name))
        openTrade(other, synchronized(remotes) { remotes[other]?.name ?: "Oyuncu" })
        system("Takas isteği gönderildi")
    }

    /** Kabul eden taraf takası sunucuda açar ve numarayı karşıya yollar. */
    fun acceptTrade() {
        val (u, n) = tradeRequest.value ?: return
        tradeRequest.value = null
        openTrade(u, n)
        Trade.open(u) { tid ->
            trade.value = trade.value?.copy(tid = tid)
            sendOffer()
        }
    }

    fun declineTrade() { tradeRequest.value = null }

    private fun openTrade(other: String, otherName: String) {
        myItems = emptyList(); myOk = false
        trade.value = TradeState(sid(uid, other), other, otherName, emptyList(), emptyList(), false, false, false)
    }

    private fun sendOffer(cancel: Boolean = false) {
        val t = trade.value ?: return
        val items = JSONArray()
        for (it in myItems) items.put(JSONObject().put("id", it.id).put("n", it.n).put("dur", it.dur))
        channel?.send("tr", JSONObject().put("to", t.other).put("u", uid).put("sid", t.sid).put("tid", t.tid).put("items", items)
            .put("ok", myOk).put("cancel", cancel))
    }

    private fun onTradeMsg(p: JSONObject) {
        val t = trade.value ?: return
        if (p.optString("sid") != t.sid) return
        if (p.optBoolean("cancel")) { Trade.cancel(t.tid); trade.value = null; system("Takas iptal edildi"); return }
        val arr = p.optJSONArray("items") ?: JSONArray()
        val theirs = (0 until arr.length()).map { arr.getJSONObject(it).let { o -> TradeItem(o.optString("id"), o.optInt("n", 1), dur = o.optInt("dur", 1000)) } }
        val tid = if (t.tid == 0L) p.optLong("tid") else t.tid
        val changed = theirs != t.theirs
        trade.value = t.copy(mine = myItems, theirs = theirs, myOk = myOk, theirOk = p.optBoolean("ok"), tid = tid,
            theirsAt = if (changed) System.currentTimeMillis() else t.theirsAt,
            changedAfterReady = t.changedAfterReady || (changed && myOk))
    }

    /** Sunucu takası bitirdi (Trade.apply). */
    fun tradeFinished(tid: Long) {
        val t = trade.value ?: return
        if (t.tid != tid) return
        trade.value = t.copy(done = true)
        system("Takas tamamlandı")
        main.postDelayed({ if (trade.value?.tid == tid) trade.value = null }, 1500)
    }

    fun setTradeItems(items: List<TradeItem>) {
        if (myOk) return // emanete alınan teklif değişmez
        myItems = items
        trade.value = trade.value?.copy(mine = items, myOk = false)
        sendOffer()
    }

    /** "Hazırım": teklif sunucu emanetine girer; geri alınamaz (yalnız iptal). */
    fun setTradeReady(ok: Boolean) {
        val t = trade.value ?: return
        if (!ok || myOk) return
        Trade.ready(t.tid, myItems, t.theirs) { accepted ->
            if (!accepted) return@ready
            myOk = true
            trade.value = trade.value?.copy(myOk = true)
            sendOffer()
        }
    }

    fun cancelTrade() {
        val t = trade.value
        sendOffer(cancel = true)
        if (t != null) Trade.cancel(t.tid)
        trade.value = null
        myOk = false
    }
}

// ====================================================================================================
// com/zenvex/online/game/Pass.kt
// ====================================================================================================

/**
 * Sezon Bileti: sezon bilgisi sunucudan gelir, bilet Mağaza'dan (Google Play) alınır ve [sync] ile oyuna uygulanır,
 * elmaslı kademe ödülleri sunucudan onaylanır (kayıt doğrulayıcısı elmas artışını ancak böyle kabul eder).
 */
object Pass {
    var name by mutableStateOf("Sezon 1")
    var ends by mutableLongStateOf(0L)
    /** sunucu saati − cihaz saati (cihaz saatini oynayarak görev yenileme engellenir) */
    @Volatile private var offset = 0L
    var busy by mutableStateOf(false)
        private set

    fun now(): Long = System.currentTimeMillis() + offset

    /** Oturum başında: sezon değiştiyse bilet sıfırlanır; sunucuda kayıtlı bilet yerelde yoksa uygulanır. */
    fun sync() = Account.passState { r ->
        r.onSuccess { o ->
            offset = o.optLong("now", System.currentTimeMillis()) - System.currentTimeMillis()
            name = o.optString("name").ifEmpty { "Sezon" }
            ends = o.optLong("ends")
            val res = GameSession.cmdNoSave("pass_sync", "season" to o.optInt("season"), "normal" to o.optBoolean("normal"), "elite" to o.optBoolean("elite"))
            if (res.msg.isNotEmpty()) Toaster.show(res.msg)
            GameSession.save(cloud = true)
        }
    }

    /** Kademe ödülü: elmas içeriyorsa sunucu onayı alınır. */
    fun claim(tier: Int, premium: Boolean, gem: Boolean, done: () -> Unit) {
        if (busy) return
        if (!gem) {
            val res = GameSession.cmd("claim_pass", "tier" to tier, "premium" to premium)
            Toaster.show(res.msg, res.ok)
            if (res.ok) GameSession.save(cloud = true)
            done(); return
        }
        busy = true
        GameSession.save(cloud = true) { ok ->
            if (!ok) { busy = false; Toaster.show("Sunucuya Ulaşılamadı", false); return@save }
            Account.passClaim(tier, premium) { r ->
                r.onSuccess {
                    val res = GameSession.cmdNoSave("claim_pass", "tier" to tier, "premium" to premium)
                    GameSession.save(cloud = true)
                    Toaster.show(res.msg, res.ok)
                }.onFailure { Toaster.show(it.message ?: "Hata", false) }
                busy = false
                done()
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/game/RegionMap.kt
// ====================================================================================================

/**
 * V15 gerçek bölge haritası: bulunulan bölge, oyunun kendi zemin dokuları (Rust, küçük ölçekte) ve kendi görselleriyle
 * (ağaç, kaya, bina, süs: atlas sprite'ları) ekran dışı bir resme bir kez çizilir. Mini harita ve büyük harita bunu
 * kullanır; haritada görülen şey bölgenin gerçekten küçültülmüş hâlidir. Bölge değişince yeniden çizilir (~arka planda).
 */
object RegionMap {
    /** en uzun kenar (piksel) */
    private const val MAX_SIDE = 1024
    private const val MAX_STATICS = 30000

    class Snap(val area: Int, val bmp: Bitmap, val x0: Float, val y0: Float, val step: Float) {
        /** dünya pikseli → resim pikseli */
        fun u(x: Float) = (x - x0) / step
        fun v(y: Float) = (y - y0) / step
    }

    @Volatile var snap: Snap? = null
        private set
    @Volatile private var building = -1
    /** başarısız denemeden sonra bekleme (dokular yüklenirken her karede iş parçacığı açılmasın) */
    @Volatile private var retryAt = 0L
    /** zemin şeritler hâlinde çizilir: oyun döngüsü kilidi uzun süre tutulmaz */
    private const val BAND = 48

    /** Bölge [ai] için harita yoksa arka planda çizer. Dokular henüz yüklü değilse sonra yeniden denenir. */
    fun ensure(ai: Int, areas: List<MapArea>, statics: Array<Sprite?>) {
        if (ai < 0 || snap?.area == ai || building >= 0 || System.currentTimeMillis() < retryAt) return
        val a = areas.getOrNull(ai) ?: return
        building = ai
        Thread {
            try {
                val s = build(ai, a, statics)
                if (s != null) snap = s else retryAt = System.currentTimeMillis() + 3000
            } catch (e: Throwable) {
                Log.w("zenvex", "bölge haritası çizilemedi", e)
                // her karede yeni iş parçacığı açılmasın
                retryAt = System.currentTimeMillis() + 5000
            } finally {
                building = -1
            }
        }.apply { name = "region-map"; isDaemon = true }.start()
    }

    /** Testler için: eşzamanlı çizim */
    internal fun buildNow(ai: Int, a: MapArea, statics: Array<Sprite?>): Snap? = build(ai, a, statics)?.also { snap = it }

    private fun build(ai: Int, a: MapArea, statics: Array<Sprite?>): Snap? {
        val x0 = a.rects.minOf { it[0] }; val y0 = a.rects.minOf { it[1] }
        val x1 = a.rects.maxOf { it[2] }; val y1 = a.rects.maxOf { it[3] }
        val step = maxOf(x1 - x0, y1 - y0) / MAX_SIDE
        val w = ((x1 - x0) / step).toInt().coerceAtLeast(1); val h = ((y1 - y0) / step).toInt().coerceAtLeast(1)
        val px = IntArray(w * h)
        val band = IntArray(w * BAND)
        var y = 0
        while (y < h) {
            val bh = minOf(BAND, h - y)
            val ok = synchronized(GameSession.lock) {
                if (GameSession.handle == 0L) 0 else Native.renderRegion(GameSession.handle, x0, y0 + y * step, step, w, bh, band)
            }
            if (ok == 0) return null
            System.arraycopy(band, 0, px, y * w, w * bh)
            y += bh
        }
        val ground = Bitmap.createBitmap(px, w, h, Bitmap.Config.ARGB_8888)
        // nesneler: oyundaki görselleriyle, y'ye göre sıralı (öndeki arkadakini örter)
        val buf = FloatArray(MAX_STATICS * 4)
        val n = synchronized(GameSession.lock) {
            if (GameSession.handle == 0L) 0 else Native.regionStatics(GameSession.handle, x0, y0, x1, y1, buf)
        }
        val order = (0 until n).sortedBy { buf[it * 4 + 2] }
        val atlas = Atlas.peek() ?: return Snap(ai, ground, x0, y0, step)
        val paint = Paint().apply { isFilterBitmap = true }
        // Atlas sayfaları GPU'da (HARDWARE): yazılımsal tuvale çizilemez (eskiden burada hata alınıyor, harita hiç
        // oluşmuyor, mini harita ve büyük harita eski düz renkli dünya haritasında kalıyordu). Android 9+ resim GPU'da
        // kaydedilip donanımla çizilir; olmazsa sayfaların yazılımsal kopyalarıyla.
        if (android.os.Build.VERSION.SDK_INT >= 28) {
            val hw = runCatching {
                val pic = android.graphics.Picture()
                val pc = pic.beginRecording(w, h)
                pc.drawBitmap(ground, 0f, 0f, null)
                for (i in order) {
                    val sp = statics.getOrNull(buf[i * 4].toInt()) ?: continue
                    atlas.draw(pc, sp, (buf[i * 4 + 1] - x0) / step, (buf[i * 4 + 2] - y0) / step, 1f / step, paint)
                }
                pic.endRecording()
                Bitmap.createBitmap(pic, w, h, Bitmap.Config.HARDWARE)
            }.getOrNull()
            if (hw != null) { ground.recycle(); return Snap(ai, hw, x0, y0, step) }
        }
        val bmp = ground.copy(Bitmap.Config.ARGB_8888, true)
        ground.recycle()
        val c = AndroidCanvas(bmp)
        for (i in order) {
            val sp = statics.getOrNull(buf[i * 4].toInt()) ?: continue
            atlas.drawSoft(c, sp, (buf[i * 4 + 1] - x0) / step, (buf[i * 4 + 2] - y0) / step, 1f / step, paint)
        }
        return Snap(ai, bmp, x0, y0, step)
    }

    /** Dünya yeniden oluşturulunca (sunucu/karakter değişimi) eski resim atılır */
    fun clear() { snap = null }
}

// ====================================================================================================
// com/zenvex/online/game/Session.kt
// ====================================================================================================

/**
 * Çevrimiçi oyun oturumu. Oyun yalnız geçerli bir sunucu oturumuyla oynanır:
 *  - Giriş: zx_session_start (bakım, yasak, cihaz yasağı ve güvenlik kontrolü; eski cihazdaki oturum düşer).
 *    Oyun kaydı her zaman sunucudan gelir; cihazdaki dosya yalnız lobide gösterim içindir.
 *  - Nabız (15 sn): bağlantı 30 sn yoksa oyun durur ("Bağlantı Koptu"), 90 sn yoksa lobiye dönülür.
 *  - Kayıt: zx_save3, sıra numarası + HMAC-SHA256 imza (oturum sırrı). Sunucu altın/elmas/seviye sıçramasını reddeder
 *    ve son geçerli kaydı geri yollar; oyun o kayda döner.
 */
object Session {
    enum class State { Off, Starting, Live, Lost }

    val state = mutableStateOf(State.Off)
    /** Lobiye atılma nedeni (başka cihaz, bakım, yasak, bağlantı) — lobi gösterir */
    val kicked = mutableStateOf<String?>(null)
    @Volatile var sid = ""
        private set
    @Volatile private var secret = ""
    @Volatile private var seq = 0L
    /** Oyunda geçen simülasyon süresi (sn): hız hilesi kontrolü için sunucuya gider */
    @Volatile var simTime = 0.0
    @Volatile private var lastOk = 0L
    @Volatile private var fails = 0
    private val main = Handler(Looper.getMainLooper())
    private var beatThread: Thread? = null

    /** Uygulama arka planda mı: arka plandayken nabız gecikse de oturum atılmaz (Android ağı uyutur) */
    @Volatile var background = false
        private set
    @Volatile private var bgSince = 0L
    /**
     * V21: arka planda bu süre kalınırsa bağlantı kopar (sayaç; anında değil). Süre dolmadan dönülürse oyun kaldığı yerden sürer.
     * Kopan oturuma yeniden girince oyuncu başlangıç ormanında (kamp) doğar; kaldığı yere ışınlanmak istismar olurdu.
     */
    const val BG_LIMIT_MS = 30_000L
    private const val PREFS = "zx_session"
    private var appCtx: Context? = null
    private val bgKick = Runnable {
        if (background && sid.isNotEmpty() && state.value != State.Off) {
            markLost(true)
            kick("Uygulama 30 saniyeden uzun arka planda kaldı, bağlantı koptu")
        }
    }

    private fun markLost(v: Boolean) {
        appCtx?.getSharedPreferences(PREFS, Context.MODE_PRIVATE)?.edit()?.putBoolean("lost", v)?.apply()
    }

    /** Bağlantı kopmuştu mu (bir kez okunur): oyuna girince kampa ışınlanmak için */
    fun takeLost(ctx: Context): Boolean {
        val p = ctx.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val lost = p.getBoolean("lost", false)
        if (lost) p.edit().putBoolean("lost", false).apply()
        return lost
    }

    /** Uygulama arka plana geçti (MainActivity.onStop): kayıt zaten onPause'da gider; 30 sn sayacı başlar */
    fun onBackground() {
        background = true
        bgSince = SystemClock.elapsedRealtime()
        if (sid.isNotEmpty()) { main.removeCallbacks(bgKick); main.postDelayed(bgKick, BG_LIMIT_MS) }
    }

    /**
     * Uygulama öne geldi: oturum açıksa hemen nabız atılır (sunucu oturumu tazeler, dünya sessizce devam eder).
     * Çok uzun kalındıysa lobiye dönülür; konum kayıtta olduğu için yeniden girince kaldığın yerden başlarsın.
     */
    fun onForeground() {
        main.removeCallbacks(bgKick)
        if (!background) return
        background = false
        val my = sid
        if (my.isEmpty() || state.value == State.Off) return
        if (SystemClock.elapsedRealtime() - bgSince > BG_LIMIT_MS) { markLost(true); kick("Uzun süre uzaktaydın, bağlantı koptu. Tekrar gir; başlangıç ormanında doğarsın."); return }
        Supa.bg {
            val r = runCatching { Supa.rpcSync("zx_heartbeat", Account.authJson().put("p_sid", my).put("p_game_time", simTime)) }
            main.post { onBeat(my, r) }
        }
    }

    /** Oyun dursun mu (bağlantı yok ya da oturum kapalı) */
    val blocked: Boolean get() = state.value != State.Live

    /** Oturumu açar; başarıda sunucudaki kayıt (boş olabilir) [done]'a gelir, hatada mesaj. */
    fun start(ctx: Context, server: String, done: (data: String?, err: String?) -> Unit) {
        appCtx = ctx.applicationContext
        if (!Account.loggedIn) { done(null, "Önce hesabına gir"); return }
        if (!Legal.noticeSeen.value || Legal.termsNeeded.value) { done(null, "Önce bilgilendirme metnini ve Kullanım Şartları'nı onayla"); return }
        state.value = State.Starting
        kicked.value = null
        Supa.bg {
            val r = runCatching {
                val dev = Guard.report(ctx)
                JSONObject(Supa.rpcSync("zx_session_start", Account.authJson().put("p_server", server).put("p_device", dev)))
            }
            main.post {
                r.onSuccess { o ->
                    sid = o.optString("sid"); secret = o.optString("secret"); seq = 0; simTime = 0.0
                    lastOk = SystemClock.elapsedRealtime(); fails = 0
                    state.value = State.Live
                    startBeat()
                    done(o.optString("data"), null)
                }.onFailure { e ->
                    state.value = State.Off
                    val m = e.message.orEmpty()
                    Account.checkBan(m)
                    if (m.startsWith("BAKIM|")) com.zenvex.online.Gate.poll()
                    done(null, friendly(m))
                }
            }
        }
    }

    private fun friendly(m: String) = when {
        m.startsWith("BAKIM|") -> "Sunucu bakımda"
        m.startsWith("OTURUM|") -> m.substringAfter("OTURUM|")
        m.startsWith("HILE|") -> m.substringAfter("HILE|")
        m.contains("BAN|") -> "Hesabın yasaklı"
        m.contains("ulaşılamadı") -> "İnternet bağlantısı yok"
        else -> m.ifEmpty { "Bağlanılamadı" }
    }

    private fun startBeat() {
        val my = sid
        beatThread?.interrupt()
        beatThread = Thread {
            while (sid == my && !Thread.currentThread().isInterrupted) {
                try { Thread.sleep(15_000) } catch (_: InterruptedException) { break }
                if (sid != my) break
                val r = runCatching {
                    Supa.rpcSync("zx_heartbeat", Account.authJson().put("p_sid", my).put("p_game_time", simTime))
                }
                main.post { onBeat(my, r) }
            }
        }.also { it.isDaemon = true; it.start() }
    }

    private fun onBeat(my: String, r: Result<String>) {
        if (sid != my) return
        r.onSuccess { body ->
            lastOk = SystemClock.elapsedRealtime(); fails = 0
            if (state.value == State.Lost) com.zenvex.online.Toaster.show("Bağlantı Geri Geldi")
            state.value = State.Live
            runCatching { JSONObject(body) }.getOrNull()?.let { o ->
                if (!o.isNull("trade")) Trade.claimPending(o.optLong("trade"))
                // posta rozeti oyundayken de güncellensin
                if (o.has("unread")) Account.unread.intValue = o.optInt("unread")
            }
        }.onFailure { e ->
            val m = e.message.orEmpty()
            when {
                m.startsWith("OTURUM|") || m.contains("BAN|") || m.startsWith("BAKIM|") || m.contains("Bu hesap silindi") -> {
                    if (m.startsWith("BAKIM|")) com.zenvex.online.Gate.poll()
                    kick(friendly(m))
                }
                else -> {
                    fails++
                    if (fails >= 2) state.value = State.Lost
                    if (!background && SystemClock.elapsedRealtime() - lastOk > 90_000) { markLost(true); kick("Bağlantı koptu, tekrar gir") }
                }
            }
        }
    }

    fun kick(reason: String) {
        if (state.value == State.Off) return
        end(send = false)
        kicked.value = reason
    }

    /**
     * Yalnız [my] oturumu hâlâ açıksa kapatır. Oyun ekranı kapanırken gecikmeli çağrılır: o arada yeni bir oturum açıldıysa
     * (lobiden hemen tekrar girildiyse) yeni oturuma dokunmaz. Eskiden yeni oturumu kapatıyor, dünya sessizce donuyordu.
     */
    fun endIf(my: String) {
        if (my.isNotEmpty() && sid == my) end()
    }

    /** Oyundan çıkış: oturum kapanır (son kayıt önce gönderilmeli). */
    fun end(send: Boolean = true) {
        val my = sid
        sid = ""; secret = ""
        beatThread?.interrupt(); beatThread = null
        state.value = State.Off
        if (send && my.isNotEmpty()) Supa.bg { runCatching { Supa.rpcSync("zx_session_end", Account.authJson().put("p_sid", my)) } }
    }

    /**
     * Oyun sunucusu (Server/Main.rs) kimlik mesajı: oturum numarası ve oturum sırrıyla imzalanmış zaman damgası.
     * Sır cihazdan çıkmaz; sunucu aynı sırrı Supabase'den (zx_net_auth) alıp imzayı karşılaştırır.
     */
    fun netHello(server: String, meta: JSONObject?): JSONObject? {
        val my = sid; val sec = secret
        if (my.isEmpty() || sec.isEmpty()) return null
        val acc = Account.id.value
        val ts = Pass.now()
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(sec.toByteArray(), "HmacSHA256"))
        val sig = mac.doFinal("net:$acc:$my:$ts".toByteArray()).joinToString("") { "%02x".format(it) }
        return JSONObject().put("t", "hello").put("acc", acc).put("sid", my).put("ts", ts).put("sig", sig).put("server", server)
            .put("meta", meta ?: JSONObject())
    }

    private fun sign(seq: Long, data: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secret.toByteArray(), "HmacSHA256"))
        return mac.doFinal("$seq:$data".toByteArray()).joinToString("") { "%02x".format(it) }
    }

    /** İmzalı kayıt argümanları (takas da kullanır). */
    @Synchronized
    fun signedSave(level: Int, data: String, kills: Int, xp: Long): JSONObject {
        seq++
        return Account.authJson().put("p_sid", sid).put("p_seq", seq).put("p_sig", sign(seq, data))
            .put("p_level", level).put("p_data", data).put("p_kills", kills).put("p_xp", xp)
    }

    /**
     * Kaydı sunucuya yollar (arka planda). Sunucu reddedip son geçerli kaydı dönerse [rollback] ana iş parçacığında çağrılır.
     */
    fun save(level: Int, data: String, kills: Int, xp: Long, rollback: (String, String) -> Unit, done: ((Boolean) -> Unit)? = null) {
        if (state.value == State.Off || sid.isEmpty()) { done?.invoke(false); return }
        val args = signedSave(level, data, kills, xp)
        Supa.bg {
            val r = runCatching { JSONObject(Supa.rpcSync("zx_save3", args)) }
            val ok = r.getOrNull()?.optBoolean("ok", true) == true
            if (done != null) main.post { done(ok) }
            r.onSuccess { o ->
                if (!o.optBoolean("ok", true) && o.has("rollback")) main.post { rollback(o.optString("rollback"), o.optString("msg")) }
            }.onFailure { e ->
                val m = e.message.orEmpty()
                if (m.startsWith("OTURUM|") || m.contains("BAN|") || m.startsWith("BAKIM|") || m.startsWith("HILE|")) main.post { kick(friendly(m)) }
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/game/Settings.kt
// ====================================================================================================

/** Tüm ayarlar. SharedPreferences'ta saklanır, oyun ekranı her karede okur. */
data class Settings(
    // Grafik
    val preset: Int = 2, // 0 Düşük, 1 Orta, 2 Yüksek, 3 Ultra, 4 Özel
    val fpsLimit: Int = 60,
    val zoom: Int = 1, // 0 Yakın, 1 Normal, 2 Uzak
    val vegetation: Int = 2, // 0 düşük, 1 orta, 2 yüksek
    /** 3B karakter kalitesi: 0 düşük (küçük ölçek), 1 orta, 2 yüksek (kenar yumuşatma) */
    val model3d: Int = 2,
    val wind: Boolean = true,
    val shadows: Boolean = true,
    val particles: Boolean = true,
    /** efekt yoğunluğu: 0 düşük, 1 orta, 2 yüksek, 3 ultra (parçacık sayısı, ışık halesi, aura ayrıntısı) */
    val fx: Int = 2,
    /** çizim çözünürlüğü: 0 %67, 1 %80, 2 %100 (yüzey gerçekten küçülür, GPU dolgu maliyeti düşer) */
    val resolution: Int = 2,
    val treeFade: Boolean = true,
    val screenShake: Float = 0.7f,
    val damageNumbers: Boolean = true,
    val showFps: Boolean = false,
    val showPing: Boolean = true,
    /** oyuncuların (kendin dahil) başındaki unvanları gizle */
    val hideTitles: Boolean = false,
    /** oyun içi tam ekran pencerelerin (çanta, üretim...) arkasında oyun görünsün mü */
    val uiTransparent: Boolean = false,
    val batterySaver: Boolean = false,
    // Kontrol & hassasiyet
    val moveDynamic: Boolean = true,
    val moveSensitivity: Float = 1.0f,
    val moveDeadZone: Float = 0.12f,
    val runThreshold: Float = 0.6f,
    val attackSensitivity: Float = 1.0f,
    val attackDeadZone: Float = 0.2f,
    val joystickSize: Float = 1.0f,
    val joystickOpacity: Float = 0.6f,
    val haptics: Int = 1, // 0 kapalı, 1 hafif, 2 güçlü
    val leftHanded: Boolean = false,
    // Ses
    val master: Float = 0.8f,
    val music: Float = 0.6f,
    val sfx: Float = 0.8f,
    val ambient: Float = 0.6f,
    val uiSound: Float = 0.7f,
    // Oyun
    val language: String = "tr",
    /** ilk girişte gösterilen numaralı kontrol rehberi (gösterilince ya da kapatılınca false) */
    val controlsGuide: Boolean = true,
) {
    val vegetationDensity: Float get() = when (vegetation) { 0 -> 0.3f; 1 -> 0.6f; else -> 1f }
    /** parçacık ve efekt çarpanı (yeni parçacık sayısı, tavan) */
    val fxScale: Float get() = if (!particles) 0f else Thermal.fxK * when (fx) { 0 -> 0.3f; 1 -> 0.6f; 2 -> 1f; else -> 1.35f }
    val renderScale: Float get() = when (resolution) { 0 -> 0.67f; 1 -> 0.8f; else -> 1f }
    val effectiveFps: Int get() = (if (batterySaver) 30 else fpsLimit).let { f -> Thermal.fpsCap.let { c -> if (c > 0) minOf(f, c) else f } }
    /** Sanal ekran yüksekliği (piksel sanat pikseli cinsinden) */
    val virtualHeight: Int get() = when (zoom) { 0 -> 230; 1 -> 290; else -> 360 }

    fun withPreset(p: Int): Settings = when (p) {
        0 -> copy(preset = 0, vegetation = 0, model3d = 0, wind = false, shadows = false, particles = true, fx = 0, resolution = 0, fpsLimit = 30)
        1 -> copy(preset = 1, vegetation = 1, model3d = 1, wind = true, shadows = true, particles = true, fx = 1, resolution = 1, fpsLimit = 60)
        2 -> copy(preset = 2, vegetation = 2, model3d = 2, wind = true, shadows = true, particles = true, fx = 2, resolution = 2, fpsLimit = 60)
        3 -> copy(preset = 3, vegetation = 2, model3d = 2, wind = true, shadows = true, particles = true, fx = 3, resolution = 2, fpsLimit = 120)
        else -> copy(preset = 4)
    }

    companion object {
        @Volatile var current = Settings()
            private set

        /** Testler: ayarı kalıcı depoya yazmadan uygula */
        internal fun preview(s: Settings) { current = s }

        fun load(ctx: Context) {
            val p = ctx.getSharedPreferences("settings", Context.MODE_PRIVATE)
            // ilk kurulumda düşük bellekli cihaz (1-2 GB) "Orta" ön ayarla başlar (2× kenar yumuşatma, %80 çözünürlük): akıcı
            // ve serin kalır; oyuncu Ayarlar'dan yükseltebilir. Kayıtlı ayarı olan ve güçlü cihazlarda değişiklik yok.
            val am = ctx.getSystemService(Context.ACTIVITY_SERVICE) as? android.app.ActivityManager
            val low = am?.isLowRamDevice == true || (am?.memoryClass ?: 256) < 192
            val d = if (!p.contains("preset") && low) Settings().withPreset(1) else Settings()
            current = Settings(
                preset = p.getInt("preset", d.preset),
                fpsLimit = p.getInt("fpsLimit", d.fpsLimit),
                zoom = p.getInt("zoom", d.zoom),
                vegetation = p.getInt("vegetation", d.vegetation),
                model3d = p.getInt("model3d", d.model3d),
                wind = p.getBoolean("wind", d.wind),
                shadows = p.getBoolean("shadows", d.shadows),
                particles = p.getBoolean("particles", d.particles),
                fx = p.getInt("fx", d.fx),
                resolution = p.getInt("resolution", d.resolution),
                treeFade = p.getBoolean("treeFade", d.treeFade),
                screenShake = p.getFloat("screenShake", d.screenShake),
                damageNumbers = p.getBoolean("damageNumbers", d.damageNumbers),
                showFps = p.getBoolean("showFps", d.showFps),
                showPing = p.getBoolean("showPing", d.showPing),
                hideTitles = p.getBoolean("hideTitles", d.hideTitles),
                uiTransparent = p.getBoolean("uiTransparent", d.uiTransparent),
                batterySaver = p.getBoolean("batterySaver", d.batterySaver),
                moveDynamic = p.getBoolean("moveDynamic", d.moveDynamic),
                moveSensitivity = p.getFloat("moveSensitivity", d.moveSensitivity),
                moveDeadZone = p.getFloat("moveDeadZone", d.moveDeadZone),
                runThreshold = p.getFloat("runThreshold", d.runThreshold),
                attackSensitivity = p.getFloat("attackSensitivity", d.attackSensitivity),
                attackDeadZone = p.getFloat("attackDeadZone", d.attackDeadZone),
                joystickSize = p.getFloat("joystickSize", d.joystickSize),
                joystickOpacity = p.getFloat("joystickOpacity", d.joystickOpacity),
                haptics = p.getInt("haptics", d.haptics),
                leftHanded = p.getBoolean("leftHanded", d.leftHanded),
                master = p.getFloat("master", d.master),
                music = p.getFloat("music", d.music),
                sfx = p.getFloat("sfx", d.sfx),
                ambient = p.getFloat("ambient", d.ambient),
                uiSound = p.getFloat("uiSound", d.uiSound),
                // oyuncu Ayarlar'dan dil seçmediyse her açılışta cihaz dili (destekleniyorsa; yoksa İngilizce)
                controlsGuide = p.getBoolean("controlsGuide", d.controlsGuide),
                language = (if (p.getBoolean("langChosen", false)) p.getString("language", null) else null) ?: I18n.deviceDefault(),
            )
            I18n.load(ctx, current.language)
        }

        /** Dil ekranı yok: oyun cihaz dilini kullanır; oyuncu Ayarlar'dan dil değiştirince bu işaretlenir ve o dil kalır */
        fun markLanguageChosen(ctx: Context) {
            ctx.getSharedPreferences("settings", Context.MODE_PRIVATE).edit().putBoolean("langChosen", true).apply()
        }

        fun save(ctx: Context, s: Settings) {
            current = s
            ctx.getSharedPreferences("settings", Context.MODE_PRIVATE).edit()
                .putInt("preset", s.preset).putInt("fpsLimit", s.fpsLimit).putInt("zoom", s.zoom)
                .putInt("vegetation", s.vegetation).putInt("model3d", s.model3d).putBoolean("wind", s.wind)
                .putBoolean("shadows", s.shadows).putBoolean("particles", s.particles).putInt("fx", s.fx).putInt("resolution", s.resolution)
                .putBoolean("treeFade", s.treeFade).putFloat("screenShake", s.screenShake)
                .putBoolean("damageNumbers", s.damageNumbers).putBoolean("showFps", s.showFps).putBoolean("showPing", s.showPing).putBoolean("hideTitles", s.hideTitles).putBoolean("uiTransparent", s.uiTransparent)
                .putBoolean("batterySaver", s.batterySaver).putBoolean("moveDynamic", s.moveDynamic)
                .putFloat("moveSensitivity", s.moveSensitivity).putFloat("moveDeadZone", s.moveDeadZone)
                .putFloat("runThreshold", s.runThreshold).putFloat("attackSensitivity", s.attackSensitivity)
                .putFloat("attackDeadZone", s.attackDeadZone).putFloat("joystickSize", s.joystickSize)
                .putFloat("joystickOpacity", s.joystickOpacity).putInt("haptics", s.haptics)
                .putBoolean("leftHanded", s.leftHanded).putBoolean("controlsGuide", s.controlsGuide).putFloat("master", s.master)
                .putFloat("music", s.music).putFloat("sfx", s.sfx).putFloat("ambient", s.ambient)
                .putFloat("uiSound", s.uiSound).putString("language", s.language)
                .apply()
            Audio.updateVolume()
            if (s.language != I18n.lang) I18n.load(ctx, s.language)
        }
    }
}

// ====================================================================================================
// com/zenvex/online/game/Skins.kt
// ====================================================================================================

/**
 * Elmas Sandığı kaplamaları: karakter ve araç renk/ışık dönüşümü (renk matrisi) + efsanevilerde parçacık izi.
 * Sahiplik sunucuda tutulur (zx_skins); oturum başında eşitlenir. Sandık zarı sunucuda atılır (zx_crate_open).
 */
object Skins {
    /** giyili kaplamalar (GameView her karede okur) */
    @Volatile var char = ""
    @Volatile var vehicle = ""
    /** sırttaki 3B kanat (kozmetik kimliği = model adı) */
    @Volatile var wings = ""
    @Volatile var pity = 50

    /** 4×5 renk matrisi (Android ColorMatrix sırası). Karakter: alfa korunur, renk kaydırılır. */
    fun matrix(id: String): FloatArray? = when (id) {
        "sk_night" -> m(0.45f, 0.55f, 1.15f, -10f, -4f, 18f, 0.15f)
        "sk_blood" -> m(1.35f, 0.45f, 0.45f, 22f, -8f, -8f, 0.1f)
        "sk_frost" -> m(0.75f, 1.05f, 1.35f, 10f, 22f, 36f, 0.2f)
        "sk_gold" -> m(1.35f, 1.1f, 0.4f, 30f, 18f, -10f, 0.35f)
        "sk_toxic" -> m(0.7f, 1.3f, 0.55f, -6f, 16f, -6f, 0.15f)
        "sk_shadow" -> m(0.5f, 0.5f, 0.58f, -14f, -14f, -8f, 0.6f)
        "vs_gold" -> m(1.4f, 1.15f, 0.35f, 34f, 20f, -12f, 0.4f)
        "vs_flame" -> m(1.45f, 0.75f, 0.35f, 26f, 0f, -12f, 0.2f)
        "vs_camo" -> m(0.75f, 0.95f, 0.55f, -6f, 4f, -10f, 0.35f)
        "vs_neon" -> m(0.85f, 0.55f, 1.5f, 10f, -6f, 30f, 0.1f)
        else -> null
    }

    /**
     * Önce `desat` oranında griye çeker (kaplama rengi baskın olsun), sonra kanal çarpanı + kaydırma uygular.
     */
    private fun m(r: Float, g: Float, b: Float, ro: Float, go: Float, bo: Float, desat: Float): FloatArray {
        val lr = 0.299f * desat; val lg = 0.587f * desat; val lb = 0.114f * desat
        val k = 1f - desat
        return floatArrayOf(
            (k + lr) * r, lg * r, lb * r, 0f, ro,
            lr * g, (k + lg) * g, lb * g, 0f, go,
            lr * b, lg * b, (k + lb) * b, 0f, bo,
            0f, 0f, 0f, 1f, 0f,
        )
    }

    /** Efsanevi karakter kaplamasının parçacık rengi (yoksa 0) */
    fun trail(id: String): Int = when (id) {
        "sk_night" -> 0xFF9AB8FF.toInt(); "sk_blood" -> 0xFFFF5A3A.toInt(); "sk_frost" -> 0xFFE0F6FF.toInt(); "sk_gold" -> 0xFFFFD34A.toInt()
        "vs_gold" -> 0xFFFFD34A.toInt(); "vs_flame" -> 0xFFFF8A2A.toInt()
        else -> 0
    }

    /** Oyun açılınca ve kaplama değişince Rust profilinden okunur */
    fun refresh() {
        val p = GameSession.ui("profile")
        char = p.optString("skin_char"); vehicle = p.optString("skin_vehicle"); wings = p.optString("wings")
    }

    /** Oturum başında sunucudaki sahiplik listesi uygulanır */
    fun sync() = Supa.rpc("zx_skins", Account.authJson()) { r ->
        r.onSuccess { body ->
            val o = runCatching { JSONObject(body) }.getOrNull() ?: return@onSuccess
            pity = o.optInt("pity", 50)
            GameSession.cmdNoSave("skins_sync", "owned" to (o.optJSONArray("owned") ?: JSONArray()))
            refresh()
        }
    }

    fun equip(id: String, kind: String): GameSession.Reply {
        val r = GameSession.cmd("skin_equip", "id" to id, "kind" to kind)
        refresh(); Online.retrack()
        return r
    }

    /** Sandık aç: önce son durum kaydedilir, zar sunucuda atılır, sonuç yerelde uygulanıp hemen kaydedilir. */
    fun open(n: Int, price: Int, gems: Int, done: (List<String>?) -> Unit) {
        if (gems < price) { Toaster.show("$price Elmas Gerekli", false); done(null); return }
        GameSession.save(cloud = true) { ok ->
            if (!ok) { Toaster.show("Sunucuya Ulaşılamadı", false); done(null); return@save }
            Supa.rpc("zx_crate_open", Account.authJson().put("p_sid", Session.sid).put("p_n", n)) { r ->
                r.onSuccess { body ->
                    val o = JSONObject(body)
                    val arr = o.optJSONArray("rewards") ?: JSONArray()
                    pity = o.optInt("pity", pity)
                    GameSession.cmdNoSave("crate_apply", "cost" to o.optInt("cost"), "rewards" to arr)
                    GameSession.save(cloud = true)
                    done(List(arr.length()) { arr.optString(it) })
                }.onFailure { Toaster.show(it.message ?: "Hata", false); done(null) }
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/game/Store.kt
// ====================================================================================================

/**
 * Mağaza: ürünler, VIP, seviye paketi teklifleri, kartlar (Supabase zx_store_state) ve Google Play ile ödeme.
 *
 * Satın alma akışı: Play ödeme ekranı → satın alma jetonu → zx-billing edge function'ı jetonu Google'dan doğrular ve
 * içeriği posta olarak yollar → jeton tüketilir (aynı ürün yeniden alınabilir). Uygulama ödeme sırasında kapanırsa
 * bir sonraki açılışta tüketilmemiş satın almalar yeniden doğrulanır (sunucu aynı siparişi iki kez işlemez).
 */
object Store {
    val state = mutableStateOf<JSONObject?>(null)
    /** Play'den gelen yerel fiyatlar (ürün kimliği → "₺99,99"); yoksa veritabanındaki TL fiyatı gösterilir */
    val prices = mutableStateMapOf<String, String>()
    val busy = mutableStateOf<String?>(null)
    private var client: BillingClient? = null
    private val details = HashMap<String, ProductDetails>()
    private var activity: WeakReference<Activity>? = null
    @Volatile private var ready = false

    fun attach(a: Activity) {
        activity = WeakReference(a)
        if (client != null) return
        client = BillingClient.newBuilder(a.applicationContext)
            .setListener { r, list -> onPurchases(r, list) }
            .enablePendingPurchases(PendingPurchasesParams.newBuilder().enableOneTimeProducts().build())
            .enableAutoServiceReconnection()
            .build()
        client?.startConnection(object : BillingClientStateListener {
            override fun onBillingSetupFinished(r: BillingResult) {
                ready = r.responseCode == BillingClient.BillingResponseCode.OK
                if (ready) { loadDetails(); recover() }
            }

            override fun onBillingServiceDisconnected() { ready = false }
        })
    }

    private fun productIds(): List<String> {
        val arr = state.value?.optJSONArray("products") ?: return DEFAULT_IDS
        return (0 until arr.length()).map { arr.getJSONObject(it).optString("id") }
    }

    private fun loadDetails() {
        val c = client ?: return
        val products = productIds().map {
            QueryProductDetailsParams.Product.newBuilder().setProductId(it).setProductType(BillingClient.ProductType.INAPP).build()
        }
        c.queryProductDetailsAsync(QueryProductDetailsParams.newBuilder().setProductList(products).build()) { r, res ->
            if (r.responseCode != BillingClient.BillingResponseCode.OK) return@queryProductDetailsAsync
            for (d in res.productDetailsList) {
                details[d.productId] = d
                d.oneTimePurchaseOfferDetails?.formattedPrice?.let { p -> prices[d.productId] = p }
            }
        }
    }

    /** Ödeme sırasında yarım kalmış (doğrulanmamış / tüketilmemiş) satın almaları tamamla */
    private fun recover() {
        client?.queryPurchasesAsync(QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build()) { r, list ->
            if (r.responseCode == BillingClient.BillingResponseCode.OK) list.forEach { verify(it) }
        }
    }

    /** Mağaza durumunu yeniler (seviye paketi teklifi seviyeye ulaşınca burada açılır) */
    fun refresh(done: (() -> Unit)? = null) {
        if (!Account.loggedIn) { done?.invoke(); return }
        val lv = GameSession.hud()[Native.LEVEL].toInt().coerceAtLeast(1)
        Supa.rpc("zx_store_state", Account.authJson().put("p_server", GameSession.server.value.id).put("p_level", lv)) { r ->
            r.onSuccess { s -> runCatching { JSONObject(s) }.getOrNull()?.let { state.value = it; if (ready && details.isEmpty()) loadDetails() } }
            done?.invoke()
        }
    }

    fun price(id: String, fallbackTry: Double): String = prices[id] ?: "₺" + "%.2f".format(fallbackTry).replace('.', ',')

    /**
     * Satın alma onay penceresinde bekleyen ürün. Mesafeli Sözleşmeler Yönetmeliği m.5: ödeme ekranından önce ürünün
     * içeriği, vergiler dahil fiyatı, tek seferlik olduğu, teslimi ve cayma hakkı istisnası gösterilir ve onaylatılır.
     */
    val confirm = mutableStateOf<String?>(null)

    /** Mağazadaki ürün bilgisi (başlık, içerik, meta) */
    fun product(id: String): JSONObject? {
        val arr = state.value?.optJSONArray("products") ?: return null
        return (0 until arr.length()).map { arr.getJSONObject(it) }.firstOrNull { it.optString("id") == id }
    }

    /** Satın Al düğmesi: önce ön bilgilendirme ve onay penceresi açılır; ödeme ekranı ancak onaydan sonra gelir. */
    fun buy(id: String) {
        if (!Account.loggedIn) { Toaster.show("Satın almak için hesabına gir", false); return }
        if (activity?.get() == null || client == null || !ready || details[id] == null) {
            Toaster.show("Google Play ödeme sistemi şu an kullanılamıyor. Uygulamayı Play Store'dan kurduğundan emin ol.", false)
            return
        }
        confirm.value = id
    }

    /** Onay penceresinde "Siparişi Onayla": Google Play ödeme ekranı açılır. */
    fun launch(id: String) {
        confirm.value = null
        val a = activity?.get()
        val d = details[id]
        val c = client
        if (a == null || c == null || !ready || d == null) {
            Toaster.show("Google Play ödeme sistemi şu an kullanılamıyor. Uygulamayı Play Store'dan kurduğundan emin ol.", false)
            return
        }
        val p = BillingFlowParams.ProductDetailsParams.newBuilder().setProductDetails(d).build()
        busy.value = id
        val r = c.launchBillingFlow(a, BillingFlowParams.newBuilder().setProductDetailsParamsList(listOf(p))
            .setObfuscatedAccountId(Account.id.value.toString()).build())
        if (r.responseCode != BillingClient.BillingResponseCode.OK) { busy.value = null; Toaster.show("Ödeme başlatılamadı", false) }
    }

    private fun onPurchases(r: BillingResult, list: List<Purchase>?) {
        when (r.responseCode) {
            BillingClient.BillingResponseCode.OK -> list?.forEach { verify(it) }
            BillingClient.BillingResponseCode.USER_CANCELED -> busy.value = null
            else -> { busy.value = null; Toaster.show("Ödeme tamamlanamadı (${r.responseCode})", false) }
        }
    }

    private fun verify(p: Purchase) {
        if (p.purchaseState != Purchase.PurchaseState.PURCHASED) {
            if (p.purchaseState == Purchase.PurchaseState.PENDING) Toaster.show("Ödeme bekleniyor; tamamlanınca ürünün postana gelir")
            return
        }
        val product = p.products.firstOrNull() ?: return
        val args = JSONObject().put("id", Account.id.value).put("key", Account.authJson().optString("p_key"))
            .put("server", GameSession.server.value.id).put("product", product).put("token", p.purchaseToken)
        Supa.fn("zx-billing", args) { res ->
            busy.value = null
            res.onSuccess {
                // içerik postada: jeton tüketilir, ürün yeniden alınabilir
                client?.consumeAsync(ConsumeParams.newBuilder().setPurchaseToken(p.purchaseToken).build()) { _, _ -> }
                // bilet postayla değil doğrudan açılır: sunucudaki bilet oyuna uygulanır
                if (product.startsWith("pass_")) { Toaster.show("Satın alma tamam! Sezon Biletin açıldı."); Pass.sync() }
                else { Toaster.show("Satın alma tamam! Ödülün postana geldi."); Account.unread.intValue = Account.unread.intValue + 1 }
                refresh()
            }.onFailure { e ->
                Log.w("zenvex", "satın alma doğrulanamadı", e)
                Toaster.show(e.message ?: "Satın alma doğrulanamadı; bir sonraki açılışta yeniden denenecek", false)
            }
        }
    }

    fun claimCards(done: () -> Unit) = Supa.rpc("zx_card_claim", Account.authJson()) { r ->
        r.onSuccess { Toaster.show("Kart ödülün postana geldi"); Account.unread.intValue = Account.unread.intValue + 1 }
            .onFailure { Toaster.show(it.message ?: "", false) }
        refresh(done)
    }

    /** Yönetici: ödeme olmadan test satın alması  */
    fun adminTest(target: Long, product: String, done: (Result<String>) -> Unit) =
        Supa.rpc("zx_admin_test_purchase", Account.authJson().put("p_target", target).put("p_product", product)
            .put("p_server", GameSession.server.value.id), done)

    private val DEFAULT_IDS = listOf("gems_60", "gems_220", "gems_600", "gems_1300", "gems_2800", "gems_6000", "pack_start", "pack_growth",
        "pack_war", "card_week", "card_month", "pass_vip", "pass_premium", "pass_upgrade")
}

// ====================================================================================================
// com/zenvex/online/game/Support.kt
// ====================================================================================================

/**
 * Destek talebi (R41b): konu + açıklama + en çok 10 fotoğraf (her biri en çok 10 MB). Aynı cihazdan ve hesaptan
 * 15 dakikada bir talep (sunucu denetler). Önce talep açılır, sonra fotoğraflar tek tek zx-support'a yüklenir.
 * Büyük fotoğraflar gönderilmeden önce en uzun kenarı 1920 px olacak şekilde küçültülüp JPEG'e çevrilir.
 */
object Support {
    const val MAX_PHOTOS = 10
    const val MAX_BYTES = 10 * 1024 * 1024
    /** "KVKK": veri sahibi başvurusu (KVKK m.11/13, 30 gün içinde yanıt); "İtiraz": yaptırıma itiraz */
    val TOPICS = listOf("Hata", "Ödeme", "Hesap", "KVKK", "İtiraz", "Öneri", "Diğer")

    /** Arka planda gönderir; [progress] (yüklenen, toplam), [done] hata mesajı ya da null. Ana iş parçacığında çağrılır. */
    fun send(ctx: Context, topic: String, body: String, photos: List<Uri>, progress: (Int, Int) -> Unit, done: (String?) -> Unit) {
        val app = ctx.applicationContext
        val main = android.os.Handler(android.os.Looper.getMainLooper())
        Supa.bg {
            val err = runCatching {
                val dev = Guard.deviceId(app)
                val open = JSONObject(Supa.rpcSync("zx_support_open", Account.authJson().put("p_device", dev).put("p_topic", topic)
                    .put("p_body", body).put("p_photos", photos.size.coerceAtMost(MAX_PHOTOS))))
                val ticket = open.getLong("ticket")
                photos.take(MAX_PHOTOS).forEachIndexed { i, uri ->
                    val (bytes, ext) = prepare(app, uri)
                    if (bytes.size > MAX_BYTES) throw IllegalStateException("${i + 1}. fotoğraf 10 MB'den büyük")
                    val auth = Account.authJson()
                    Supa.fnSync("zx-support", JSONObject().put("op", "photo").put("id", auth.optLong("p_id")).put("key", auth.optString("p_key"))
                        .put("ticket", ticket).put("idx", i).put("ext", ext).put("data", Base64.encodeToString(bytes, Base64.NO_WRAP)))
                    main.post { progress(i + 1, photos.size) }
                }
            }.exceptionOrNull()?.let { it.message ?: "Gönderilemedi" }
            main.post { done(err) }
        }
    }

    /** Fotoğrafı okur; büyükse küçültüp JPEG yapar. (baytlar, uzantı) */
    private fun prepare(ctx: Context, uri: Uri): Pair<ByteArray, String> {
        val raw = ctx.contentResolver.openInputStream(uri)?.use { it.readBytes() } ?: throw IllegalStateException("Fotoğraf okunamadı")
        val o = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(raw, 0, raw.size, o)
        val side = maxOf(o.outWidth, o.outHeight)
        val mime = ctx.contentResolver.getType(uri).orEmpty()
        if (side in 1..1920 && raw.size <= 2 * 1024 * 1024 && (mime == "image/jpeg" || mime == "image/png" || mime == "image/webp")) {
            return raw to when (mime) { "image/png" -> "png"; "image/webp" -> "webp"; else -> "jpg" }
        }
        var sample = 1
        while (side / (sample * 2) >= 1920) sample *= 2
        val bmp = BitmapFactory.decodeByteArray(raw, 0, raw.size, BitmapFactory.Options().apply { inSampleSize = sample })
            ?: throw IllegalStateException("Fotoğraf açılamadı")
        val k = 1920f / maxOf(bmp.width, bmp.height)
        val out = if (k < 1f) Bitmap.createScaledBitmap(bmp, (bmp.width * k).toInt(), (bmp.height * k).toInt(), true) else bmp
        val bos = ByteArrayOutputStream()
        out.compress(Bitmap.CompressFormat.JPEG, 85, bos)
        return bos.toByteArray() to "jpg"
    }

    // ---------------------------------------------------------------- yönetici
    fun adminList(open: Boolean, done: (Result<String>) -> Unit) =
        Supa.rpc("zx_admin_support", Account.authJson().put("p_open", open), done)

    fun adminReply(ticket: Long, text: String, done: (Result<String>) -> Unit) =
        Supa.rpc("zx_admin_support_reply", Account.authJson().put("p_ticket", ticket).put("p_reply", text), done)

    /** Talebin fotoğraflarına 1 saatlik imzalı bağlantılar */
    fun adminPhotos(ticket: Long, done: (Result<List<String>>) -> Unit) {
        val auth = Account.authJson()
        Supa.fn("zx-support", JSONObject().put("op", "sign").put("id", auth.optLong("p_id")).put("key", auth.optString("p_key")).put("ticket", ticket)) { r ->
            done(r.mapCatching { s -> JSONObject(s).optJSONArray("urls").let { a -> if (a == null) emptyList() else List(a.length()) { a.getString(it) } } })
        }
    }

    fun adminReports(open: Boolean, done: (Result<String>) -> Unit) =
        Supa.rpc("zx_admin_reports", Account.authJson().put("p_open", open), done)

    fun adminReportDone(report: Long, action: String, done: (Result<String>) -> Unit) =
        Supa.rpc("zx_admin_report_done", Account.authJson().put("p_report", report).put("p_action", action), done)
}

// ====================================================================================================
// com/zenvex/online/game/Thermal.kt
// ====================================================================================================

/**
 * Isınma koruması: cihaz ısındıkça (Android termal durumu) kare sınırını ve parçacık yoğunluğunu kademeli düşürür. Soğuyunca
 * eski değerlere döner. Sistem kendi kısmadan önce davranıldığı için takılma yerine akıcı ama biraz daha az kare görülür.
 */
object Thermal {
    @Volatile private var status = 0
    /** öngörülen durum (Android 11+ ısınma payı tahmini): sistem kısmadan, cihaz ısınmadan önce hafifçe yavaşla */
    @Volatile private var predicted = 0
    private var pm: PowerManager? = null
    private var lastPoll = 0L

    private val level: Int get() = maxOf(status, predicted)

    /** termal duruma göre kare sınırı (0 = sınır yok) */
    val fpsCap: Int get() = when { level >= 4 -> 30; level >= 3 -> 36; level >= 2 -> 48; level >= 1 -> 55; else -> 0 }

    /** parçacık/efekt çarpanı */
    val fxK: Float get() = when { level >= 4 -> 0.5f; level >= 3 -> 0.65f; level >= 2 -> 0.85f; level >= 1 -> 0.95f; else -> 1f }

    fun init(ctx: Context) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) return
        runCatching {
            val p = ctx.applicationContext.getSystemService(Context.POWER_SERVICE) as PowerManager
            pm = p
            status = p.currentThermalStatus
            p.addThermalStatusListener { s -> status = s }
        }
    }

    /**
     * Oyun döngüsünden çağrılır; 10 sn'de bir sistemin 10 sn sonrası için ısınma payı tahminini okur (1.0 = kısma sınırı).
     * Pay %75'i geçince hafif, %88'i geçince orta, %96'yı geçince güçlü yavaşlama; düşünce kademeli geri döner.
     */
    fun poll(nowMs: Long) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.R || nowMs - lastPoll < 10_000L) return
        lastPoll = nowMs
        val h = runCatching { pm?.getThermalHeadroom(10) ?: Float.NaN }.getOrDefault(Float.NaN)
        if (h.isNaN()) return
        val want = when { h >= 0.96f -> 3; h >= 0.88f -> 2; h >= 0.75f -> 1; else -> 0 }
        // yükselişte hemen, düşüşte bir basamak (kare hızı inip çıkıp titremesin)
        predicted = if (want >= predicted) want else predicted - 1
    }
}

// ====================================================================================================
// com/zenvex/online/game/Trade.kt
// ====================================================================================================

/**
 * Sunucu emanetli takas (Online.kt yalnız ekrandaki teklifleri eşler; eşya hareketi burada ve sunucuda olur).
 *  1) Kabul eden taraf zx_trade_open ile takas açar, numarayı karşıya yollar.
 *  2) "Hazırım": teklif edilen eşyalar çantadan düşülür, imzalı kayıtla zx_trade_ready'ye gider; sunucu eşyaların gerçekten
 *     olduğunu ve düşüldüğünü doğrular, emanete alır. Reddedilirse eşyalar geri konur.
 *  3) İki taraf da hazırsa takas biter; zx_trade_claim karşı tarafın eşyasını bir kez verir. İptalde emanet geri gelir.
 */
object Trade {
    private val main = Handler(Looper.getMainLooper())
    private val claiming = HashSet<Long>()

    /** eşya kimliği → kayıttaki sıra numarası (altın = -1) */
    fun indexOf(id: String): Int {
        if (id == "coin") return -1
        val items = GameSession.world().optJSONArray("items") ?: return -2
        for (i in 0 until items.length()) if (items.optJSONArray(i)?.optString(0) == id) return i
        return -2
    }

    private fun idOf(idx: Int): String =
        if (idx == -1) "coin" else GameSession.world().optJSONArray("items")?.optJSONArray(idx)?.optString(0).orEmpty()

    fun accountOf(uid: String): Long = uid.removePrefix("a").toLongOrNull() ?: -1

    fun open(otherUid: String, done: (Long) -> Unit) {
        val other = accountOf(otherUid)
        if (other < 0) { Toaster.show("Bu oyuncuyla takas yapılamaz", false); return }
        Supa.rpc("zx_trade_open", Account.authJson().put("p_sid", Session.sid).put("p_other", other)) { r ->
            r.onSuccess { done(it.trim().toLongOrNull() ?: 0L) }.onFailure { Toaster.show(it.message ?: "Takas açılamadı", false) }
        }
    }

    /** Sunucu kaydındaki biçim (iki istemci aynı sırayla aynı diziyi üretir: karşılaştırma bunun üstünden) */
    private fun wire(list: List<Online.TradeItem>): JSONArray {
        val arr = JSONArray()
        for (it in list) {
            val idx = indexOf(it.id)
            if (idx < -1 || it.n <= 0) continue
            arr.put(JSONObject().put("item", idx).put("n", it.n).put("dur", it.dur))
        }
        return arr
    }

    /**
     * Teklifi kilitler (emanet). [theirs]: o an ekranda görülen karşı teklif — sunucu, karşı taraf hazır olurken teklifi
     * bundan farklıysa takası bitirmez (son anda teklif değiştirme). [done] true → sunucu kabul etti.
     */
    fun ready(tid: Long, items: List<Online.TradeItem>, theirs: List<Online.TradeItem>, done: (Boolean) -> Unit) {
        if (tid <= 0) { Toaster.show("Takas henüz açılmadı, bekle", false); done(false); return }
        val taken = ArrayList<Online.TradeItem>()
        for (it in items) {
            val idx = indexOf(it.id)
            if (idx < -1 || it.n <= 0) continue
            val r = if (it.slot >= 0) GameSession.cmdNoSave("trade_take", "id" to it.id, "n" to 1, "slot" to it.slot)
                else GameSession.cmdNoSave("trade_take", "id" to it.id, "n" to it.n)
            if (!r.ok) {
                for (b in taken) GameSession.cmdNoSave("trade_give", "id" to b.id, "n" to b.n, "dur" to b.dur)
                Toaster.show(r.msg, false); done(false); return
            }
            // gerçek dayanıklılık çekirdekten (ekranda gösterilenle aynı olmalı)
            taken += it.copy(dur = r.msg.toIntOrNull() ?: it.dur)
        }
        val arr = wire(taken)
        val snap = GameSession.snapshot()
        val base = Session.signedSave(snap.level, snap.data, snap.kills, snap.xp).put("p_trade", tid).put("p_items", arr)
        fun fail(e: Throwable) {
            for (b in taken) GameSession.cmdNoSave("trade_give", "id" to b.id, "n" to b.n, "dur" to b.dur)
            GameSession.save(cloud = true)
            Toaster.show(e.message ?: "Takas onaylanamadı", false)
            done(false)
        }
        Supa.rpc("zx_trade_ready", JSONObject(base.toString()).put("p_expect", wire(theirs))) { r ->
            r.onSuccess { done(true); poll(tid) }
                .onFailure { e ->
                    // eski sunucu (p_expect yok): aynı teklifle bir kez daha, beklentisiz
                    if ((e.message ?: "").contains("p_expect") || (e.message ?: "").contains("PGRST202"))
                        Supa.rpc("zx_trade_ready", base) { r2 -> r2.onSuccess { done(true); poll(tid) }.onFailure { fail(it) } }
                    else fail(e)
                }
        }
    }

    /** Hazır olduktan sonra sonucu bekler (2 sn aralıkla). */
    private fun poll(tid: Long) {
        main.postDelayed({
            if (Session.state.value == Session.State.Off) return@postDelayed
            Supa.rpc("zx_trade_claim", Account.authJson().put("p_trade", tid)) { r ->
                r.onSuccess { body ->
                    val o = runCatching { JSONObject(body) }.getOrNull() ?: return@onSuccess
                    if (o.optString("state") == "open") { if (Online.trade.value?.tid == tid) poll(tid); return@onSuccess }
                    apply(tid, o)
                }.onFailure { if (Online.trade.value?.tid == tid) poll(tid) }
            }
        }, 2000)
    }

    fun cancel(tid: Long) {
        if (tid <= 0) return
        Supa.rpc("zx_trade_cancel", Account.authJson().put("p_trade", tid)) { claimPending(tid) }
    }

    /** Nabızda bildirilen ya da iptal sonrası alınmamış takas sonucu. */
    fun claimPending(tid: Long) {
        if (tid <= 0 || !claiming.add(tid)) return
        Supa.rpc("zx_trade_claim", Account.authJson().put("p_trade", tid)) { r ->
            claiming.remove(tid)
            r.onSuccess { body -> runCatching { JSONObject(body) }.getOrNull()?.let { if (it.optString("state") != "open") apply(tid, it) } }
        }
    }

    private fun apply(tid: Long, o: JSONObject) {
        val items = o.optJSONArray("items") ?: JSONArray()
        val got = ArrayList<String>()
        for (i in 0 until items.length()) {
            val it = items.getJSONObject(i)
            val id = idOf(it.optInt("item", -2))
            if (id.isEmpty()) continue
            val r = GameSession.cmdNoSave("trade_give", "id" to id, "n" to it.optInt("n"), "dur" to it.optInt("dur", 1000))
            if (r.ok) got += r.msg
        }
        GameSession.save(cloud = true)
        if (o.optString("state") == "done") {
            Online.tradeFinished(tid)
            Toaster.show(if (got.isEmpty()) "Takas Tamamlandı" else "Takas Tamamlandı: " + got.joinToString(", "))
        } else if (got.isNotEmpty()) Toaster.show("Takas İptal: Eşyaların Geri Geldi", false)
    }
}

// ====================================================================================================
// com/zenvex/online/net/GameNet.kt
// ====================================================================================================

/**
 * Kendi oyun sunucumuza (Server/Main.rs) tek WebSocket bağlantısı. Supabase kanalıyla aynı olay adlarını taşır,
 * böylece [com.zenvex.online.Online] iki bağlantıyı da aynı şekilde kullanır. Farklar: bölge değişince [area]
 * çağrılır (oda değişir), konumlar sunucudan "P" paketiyle toplu gelir, ev sahibini sunucu seçer ([onHost]).
 *
 * [hello]: her bağlanışta kimlik mesajı (oturum numarası + oturum sırrıyla imza); null ise bağlanılmaz.
 */
class GameNet(
    private val url: String,
    private val hello: () -> JSONObject?,
    private val onBroadcast: (event: String, payload: JSONObject) -> Unit,
    private val onPresence: (joins: JSONObject, leaves: JSONObject, full: Boolean) -> Unit,
    private val onStatus: (String) -> Unit,
    private val onHost: (String) -> Unit,
) : Link {
    private var ws: WebSocket? = null
    @Volatile override var joined = false
        private set
    @Volatile override var pingMs = -1
        private set
    @Volatile private var closed = false
    private var meta: JSONObject? = null
    @Volatile private var areaIdx = -1
    private var backoff = 1000L
    private val timer = Executors.newSingleThreadScheduledExecutor()
    private var beat: ScheduledFuture<*>? = null
    @Volatile private var pingId = 0L
    @Volatile private var pingAt = 0L

    fun open() {
        closed = false
        connect()
    }

    private fun connect() {
        if (closed) return
        val h = hello() ?: run { onStatus("Oturum yok"); return }
        onStatus("Bağlanıyor…")
        ws = Supa.http.newWebSocket(Request.Builder().url(url).build(), object : WebSocketListener() {
            override fun onOpen(webSocket: WebSocket, response: Response) {
                webSocket.send(h.toString())
            }

            override fun onMessage(webSocket: WebSocket, text: String) = handle(webSocket, text)

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                Log.w("zenvex", "oyun sunucusu: ${t.message}")
                drop()
            }

            override fun onClosed(webSocket: WebSocket, code: Int, reason: String) = drop()
        })
    }

    private fun handle(socket: WebSocket, text: String) {
        val m = runCatching { JSONObject(text) }.getOrNull() ?: return
        when (val t = m.optString("t")) {
            "welcome" -> {
                joined = true
                backoff = 1000L
                onStatus("Çevrimiçi")
                meta?.let { socket.send(JSONObject().put("t", "track").put("meta", it).toString()) }
                if (areaIdx >= 0) socket.send(JSONObject().put("t", "area").put("a", areaIdx).toString())
                beat?.cancel(false)
                beat = timer.scheduleWithFixedDelay({
                    pingId++; pingAt = SystemClock.elapsedRealtime()
                    ws?.send(JSONObject().put("t", "ping").put("i", pingId).toString())
                }, 1, 3, TimeUnit.SECONDS)
            }
            "pong" -> if (m.optLong("i") == pingId) pingMs = (SystemClock.elapsedRealtime() - pingAt).toInt()
            "err" -> { onStatus(m.optString("msg").take(60)); closed = true; socket.close(1000, null) }
            "pres" -> onPresence(m.optJSONObject("joins") ?: JSONObject(), m.optJSONObject("leaves") ?: JSONObject(), m.optBoolean("full"))
            "host" -> onHost(m.optString("h"))
            // konum paketi: [[uid, s0, s1, ...], ...] → her biri bir "p" olayı
            "P" -> {
                val l = m.optJSONArray("l") ?: return
                for (i in 0 until l.length()) {
                    val e = l.optJSONArray(i) ?: continue
                    val s = org.json.JSONArray()
                    for (k in 1 until e.length()) s.put(e.optDouble(k))
                    onBroadcast("p", JSONObject().put("u", e.optString(0)).put("s", s))
                }
            }
            else -> onBroadcast(t, m)
        }
    }

    private fun drop() {
        joined = false
        pingMs = -1
        beat?.cancel(false)
        if (closed) return
        onStatus("Bağlantı koptu, yeniden deneniyor…")
        val wait = backoff
        backoff = (backoff * 2).coerceAtMost(15000L)
        timer.schedule({ connect() }, wait, TimeUnit.MILLISECONDS)
    }

    /** Bölge değişti: sunucu oyuncuyu o bölgenin odasına alır */
    fun area(a: Int) {
        areaIdx = a
        if (joined) ws?.send(JSONObject().put("t", "area").put("a", a).toString())
    }

    override fun send(event: String, payload: JSONObject) {
        if (!joined) return
        val o = JSONObject(payload.toString()).put("t", event)
        ws?.send(o.toString())
    }

    override fun track(meta: JSONObject) {
        this.meta = meta
        if (joined) ws?.send(JSONObject().put("t", "track").put("meta", meta).toString())
    }

    override fun close() {
        closed = true
        joined = false
        beat?.cancel(false)
        ws?.close(1000, null)
        ws = null
        timer.shutdown()
    }

    override fun reconnectNow() {
        if (closed || joined) return
        backoff = 200L
        ws?.cancel()
    }
}

// ====================================================================================================
// com/zenvex/online/net/GoogleSignIn.kt
// ====================================================================================================

/**
 * "Google ile giriş": Android Credential Manager ile Google hesabı seçilir, ID jetonu alınır ve
 * Account.google ile sunucuya (zx-google) gönderilir. İstemci kimliği BuildConfig.GOOGLE_WEB_CLIENT_ID
 * (Google Cloud → OAuth istemcisi, tür "Web application"); boşsa düğme kurulum mesajı gösterir.
 */
object GoogleSignIn {
    private val scope = MainScope()

    val available: Boolean get() = BuildConfig.GOOGLE_WEB_CLIENT_ID.isNotEmpty()

    /** done(null) başarı; done("") kullanıcı vazgeçti; diğer metinler hata. */
    fun start(activity: Activity, link: Boolean, done: (String?) -> Unit) {
        if (!available) { done("Google girişi henüz ayarlanmadı"); return }
        val option = GetSignInWithGoogleOption.Builder(BuildConfig.GOOGLE_WEB_CLIENT_ID).build()
        val req = GetCredentialRequest.Builder().addCredentialOption(option).build()
        scope.launch {
            try {
                val cred = CredentialManager.create(activity).getCredential(activity, req).credential
                if (cred is CustomCredential && cred.type == GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL) {
                    Account.google(GoogleIdTokenCredential.createFrom(cred.data).idToken, link, done)
                } else done("Google hesabı alınamadı")
            } catch (e: GetCredentialCancellationException) {
                done("")
            } catch (e: Exception) {
                done(e.message ?: "Google girişi başarısız")
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/net/Link.kt
// ====================================================================================================

/** Canlı oyun bağlantısı: Supabase Realtime kanalı ([Supa.Channel]) ya da kendi oyun sunucumuz ([GameNet]). */
interface Link {
    val joined: Boolean
    /** gidiş-dönüş süresi (ms); ölçülmediyse -1 */
    val pingMs: Int
    /** olay gönder (Supabase'de kanaldaki herkese, oyun sunucusunda olaya göre yönlendirilir) */
    fun send(event: String, payload: JSONObject)
    /** kimlik bilgisi (ad, klan, unvan, kaplama) */
    fun track(meta: JSONObject)
    fun close()
    /** bağlı değilse beklemeden yeniden bağlan */
    fun reconnectNow()
}

// ====================================================================================================
// com/zenvex/online/net/Supa.kt
// ====================================================================================================

/**
 * Supabase'e çok ince bir istemci:
 *  - [rpc]: PostgREST üzerinden `zx_*` veritabanı fonksiyonları (hesap, kayıt, sohbet geçmişi, posta, klan)
 *  - [Channel]: Realtime WebSocket (Phoenix protokolü 1.0.0) — yayın (broadcast) ve kimler bağlı (presence)
 */
object Supa {
    /** ilk ağ isteğinde kurulur (ekran görüntüsü testlerinde ağ hiç kullanılmaz; OkHttp 5 Android TLS katmanını kurarken arar) */
    val http: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(15, TimeUnit.SECONDS)
            .pingInterval(20, TimeUnit.SECONDS)
            .build()
    }
    private val io = Executors.newFixedThreadPool(3)
    private val main = Handler(Looper.getMainLooper())
    private val json = "application/json".toMediaType()

    val configured: Boolean get() = BuildConfig.SB_URL.isNotEmpty() && BuildConfig.SB_KEY.isNotEmpty()

    class RpcError(msg: String) : Exception(msg)

    /** Eşzamanlı çağrı (arka plan iş parçacığında kullan). Dönen gövde ham JSON metnidir. */
    fun rpcSync(fn: String, args: JSONObject = JSONObject()): String {
        if (!configured) throw RpcError("Sunucu ayarlanmadı")
        if (!com.zenvex.online.Integrity.ok) throw RpcError(com.zenvex.online.Integrity.reason)
        val req = Request.Builder()
            .url("${BuildConfig.SB_URL}/rest/v1/rpc/$fn")
            .header("apikey", BuildConfig.SB_KEY)
            .header("Authorization", "Bearer ${BuildConfig.SB_KEY}")
            .post(args.toString().toRequestBody(json))
            .build()
        val body: String
        val code: Int
        try {
            http.newCall(req).execute().use { r: Response -> code = r.code; body = r.body.string() }
        } catch (e: Exception) {
            throw RpcError("Sunucuya ulaşılamadı")
        }
        if (code !in 200..299) {
            val m = runCatching { JSONObject(body).optString("message") }.getOrNull()
            Log.w("zenvex", "rpc $fn $code $body")
            // oyun sırasında yasaklanan / silinen hesap: hangi çağrıda olursa olsun hemen yasak ekranına düşer
            if (m != null && (m.contains("BAN|") || m.contains("Bu hesap silindi"))) main.post { com.zenvex.online.Account.checkBan(m) }
            throw RpcError(
                when {
                    code == 404 -> "Sunucu kurulumu eksik (veritabanı)"
                    !m.isNullOrBlank() -> m
                    else -> "Sunucu hatası ($code)"
                },
            )
        }
        return body
    }

    /** Edge function çağrısı (ör. zx-google). Hata gövdesindeki "error" mesajı istisnaya taşınır. */
    fun fnSync(name: String, args: JSONObject): String {
        if (!configured) throw RpcError("Sunucu ayarlanmadı")
        val req = Request.Builder()
            .url("${BuildConfig.SB_URL}/functions/v1/$name")
            .header("apikey", BuildConfig.SB_KEY)
            .header("Authorization", "Bearer ${BuildConfig.SB_KEY}")
            .post(args.toString().toRequestBody(json))
            .build()
        val body: String
        val code: Int
        try {
            http.newCall(req).execute().use { r: Response -> code = r.code; body = r.body.string() }
        } catch (e: Exception) {
            throw RpcError("Sunucuya ulaşılamadı")
        }
        if (code !in 200..299) {
            val m = runCatching { JSONObject(body).optString("error") }.getOrNull()
            Log.w("zenvex", "fn $name $code $body")
            throw RpcError(if (!m.isNullOrBlank()) m else "Sunucu hatası ($code)")
        }
        return body
    }

    fun fn(name: String, args: JSONObject, done: (Result<String>) -> Unit) {
        io.execute {
            val r = runCatching { fnSync(name, args) }
            main.post { done(r) }
        }
    }

    /** Arka planda çağırır, sonucu ana iş parçacığında verir. */
    fun rpc(fn: String, args: JSONObject = JSONObject(), done: (Result<String>) -> Unit) {
        io.execute {
            val r = runCatching { rpcSync(fn, args) }
            main.post { done(r) }
        }
    }

    fun bg(block: () -> Unit) = io.execute { runCatching(block).onFailure { Log.w("zenvex", "bg", it) } }

    // ======================================================================== Realtime
    /**
     * Tek bir Realtime kanalı (kendi soketiyle). Bağlantı koparsa kendiliğinden yeniden bağlanır.
     * Olaylar OkHttp iş parçacığında gelir; dinleyiciler kendi senkronizasyonunu yapmalı.
     */
    class Channel(
        private val topic: String,
        private val presenceKey: String,
        private val onBroadcast: (event: String, payload: JSONObject) -> Unit,
        private val onPresence: (joins: JSONObject, leaves: JSONObject, full: Boolean) -> Unit,
        private val onStatus: (String) -> Unit,
    ) : Link {
        private var ws: WebSocket? = null
        @Volatile override var joined = false
            private set
        @Volatile private var closed = false
        private var ref = 0
        private var joinRef = "0"
        private var beat: ScheduledFuture<*>? = null
        private var trackMeta: JSONObject? = null
        /** gidiş-dönüş süresi (ms): 5 sn'de bir kalp atışı yanıtından; -1 = ölçülmedi */
        @Volatile override var pingMs = -1
            private set
        @Volatile private var pingRef = ""
        @Volatile private var pingAt = 0L
        private var backoff = 1000L
        private val timer = Executors.newSingleThreadScheduledExecutor()

        fun open() {
            closed = false
            connect()
        }

        /** Uygulama öne gelince: bağlı değilse beklemeden yeniden bağlan */
        override fun reconnectNow() {
            if (closed || joined) return
            backoff = 200L
            ws?.cancel()
        }

        private fun connect() {
            if (closed) return
            onStatus("Bağlanıyor…")
            val url = BuildConfig.SB_URL.replaceFirst("https://", "wss://").replaceFirst("http://", "ws://") +
                "/realtime/v1/websocket?apikey=${BuildConfig.SB_KEY}&vsn=1.0.0"
            ws = http.newWebSocket(Request.Builder().url(url).build(), object : WebSocketListener() {
                override fun onOpen(webSocket: WebSocket, response: Response) {
                    backoff = 1000L
                    join()
                    beat?.cancel(false)
                    // kalp atışı aynı zamanda ping ölçer (sunucu aynı ref ile yanıtlar)
                    beat = timer.scheduleWithFixedDelay({
                        pingRef = (++ref).toString(); pingAt = android.os.SystemClock.elapsedRealtime()
                        push("phoenix", "heartbeat", JSONObject(), null, pingRef)
                    }, 1, 5, TimeUnit.SECONDS)
                }

                override fun onMessage(webSocket: WebSocket, text: String) = handle(text)

                override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                    Log.w("zenvex", "realtime: ${t.message}")
                    drop()
                }

                override fun onClosed(webSocket: WebSocket, code: Int, reason: String) = drop()
            })
        }

        private fun drop() {
            joined = false
            pingMs = -1
            beat?.cancel(false)
            if (closed) return
            onStatus("Bağlantı koptu, yeniden deneniyor…")
            val wait = backoff
            backoff = (backoff * 2).coerceAtMost(15000L)
            timer.schedule({ connect() }, wait, TimeUnit.MILLISECONDS)
        }

        private fun join() {
            joinRef = (++ref).toString()
            val cfg = JSONObject()
                .put("broadcast", JSONObject().put("self", false).put("ack", false))
                .put("presence", JSONObject().put("enabled", true).put("key", presenceKey))
                .put("private", false)
            // katılım mesajının kendi ref'i join_ref ile aynı olmalı: sunucu cevabı mesaj ref'iyle döner (join_ref göndermez)
            push(topic, "phx_join", JSONObject().put("config", cfg), joinRef, joinRef)
        }

        private fun handle(text: String) {
            val m = runCatching { JSONObject(text) }.getOrNull() ?: return
            val ev = m.optString("event")
            val p = m.optJSONObject("payload") ?: JSONObject()
            when (ev) {
                "phx_reply" -> if (m.optString("topic") == "phoenix") {
                    if (m.optString("ref") == pingRef) pingMs = (android.os.SystemClock.elapsedRealtime() - pingAt).toInt()
                } else if (m.optString("ref") == joinRef && m.optString("topic") == topic) {
                    if (p.optString("status") == "ok") {
                        joined = true
                        onStatus("Çevrimiçi")
                        trackMeta?.let { track(it) }
                    } else {
                        onStatus("Katılamadı: " + p.optJSONObject("response")?.optString("reason").orEmpty().take(60))
                    }
                }
                "broadcast" -> onBroadcast(p.optString("event"), p.optJSONObject("payload") ?: JSONObject())
                "presence_state" -> onPresence(p, JSONObject(), true)
                "presence_diff" -> onPresence(p.optJSONObject("joins") ?: JSONObject(), p.optJSONObject("leaves") ?: JSONObject(), false)
                "phx_error", "phx_close" -> if (m.optString("topic") == topic && !closed) {
                    joined = false
                    timer.schedule({ if (!closed) join() }, 2000, TimeUnit.MILLISECONDS)
                }
                "system" -> if (p.optString("status") == "error") onStatus(p.optString("message").take(60))
            }
        }

        private fun push(t: String, event: String, payload: JSONObject, jr: String?, msgRef: String? = null) {
            val m = JSONObject().put("topic", t).put("event", event).put("payload", payload).put("ref", msgRef ?: (++ref).toString())
            if (jr != null) m.put("join_ref", jr)
            ws?.send(m.toString())
        }

        /** Herkese yayın (gönderen hariç). */
        override fun send(event: String, payload: JSONObject) {
            if (!joined) return
            push(topic, "broadcast", JSONObject().put("type", "broadcast").put("event", event).put("payload", payload), joinRef)
        }

        /** Kimlik bilgisini (isim, klan…) tüm kanala bildirir. */
        override fun track(meta: JSONObject) {
            trackMeta = meta
            if (!joined) return
            push(topic, "presence", JSONObject().put("type", "presence").put("event", "track").put("payload", meta), joinRef)
        }

        override fun close() {
            closed = true
            joined = false
            beat?.cancel(false)
            runCatching { push(topic, "phx_leave", JSONObject(), joinRef) }
            ws?.close(1000, "bye")
            ws = null
            timer.shutdown()
        }
    }
}

// ====================================================================================================
// com/zenvex/online/ui/Admin.kt
// ====================================================================================================

private val tsFmt = SimpleDateFormat("dd.MM HH:mm", Locale.forLanguageTag("tr"))
internal fun ts(ms: Long) = if (ms <= 0) "" else tsFmt.format(Date(ms))

/** Oyundaki eşyalar: [kimlik, ad, tür, nadirlik] (sıra = kayıttaki eşya numarası) */
internal fun allItems(): JSONArray = GameSession.world().optJSONArray("items") ?: JSONArray()

/**
 * Yönetici: oyuncu dosyası. Özet (yasak, mesaj, oyundan at, altın/elmas, yanına ışınlan), envanter (adetli silme + onay),
 * güvenlik (hile kayıtları, cihazlar, cihaz yasağı), son işlemler, sohbetler, özel mesajlar, hesap (sil / geri getir / anahtar).
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
fun AdminPlayerFile(target: Long, close: () -> Unit) {
    var data by remember { mutableStateOf<JSONObject?>(null) }
    var sec by remember { mutableStateOf<JSONObject?>(null) }
    var err by remember { mutableStateOf("") }
    var tick by remember { mutableIntStateOf(0) }
    var tab by remember { mutableIntStateOf(0) }
    var removing by remember { mutableStateOf<Pair<Int, Int>?>(null) } // (eşya no, sahip olunan adet)
    LaunchedEffect(tick) {
        Account.adminPlayer(target) { r -> r.onSuccess { data = it }.onFailure { err = it.message ?: "Hata" } }
        Account.adminFlags(target) { r -> r.onSuccess { sec = it } }
    }
    val res: (Result<String>) -> Unit = { r -> r.onSuccess { Toaster.show(it) }.onFailure { Toaster.show(it.message ?: "", false) }; tick++ }
    val items = remember { allItems() }
    fun itemName(i: Int) = items.optJSONArray(i)?.optString(1) ?: "#$i"
    fun itemId(i: Int) = items.optJSONArray(i)?.optString(0) ?: ""
    PxDialog("Oyuncu Dosyası", close, width = 920.dp) {
        val d = data
        if (d == null) { PT(err.ifEmpty { "Yükleniyor…" }, 14.sp, Px.Sub); return@PxDialog }
        Row(verticalAlignment = Alignment.CenterVertically) {
            ProfileAvatar(d.optInt("avatar"), d.optString("frame"), 56.dp, photo = d.optString("photo"))
            Spacer(Modifier.width(10.dp))
            Column(Modifier.weight(1f)) {
                PT("${d.optString("name")} · ID ${fmtId(d.optLong("id"))}", 18.sp, Px.Name)
                val online = sec?.optBoolean("online") == true
                PT((if (online) "● Çevrimiçi (${sec?.optString("server")}) · " else "○ Çevrimdışı · ") +
                    "Sv ${d.optInt("level")} · ${fmt(d.optInt("kills"))} Öldürme · Klan: ${d.optJSONObject("clan")?.optString("name") ?: "—"}" +
                    (if (d.optBoolean("google")) " · Google" else ""), 12.sp, if (online) Px.Name else Px.Sub)
                if (d.optBoolean("deleted")) PT("HESAP SİLİNDİ · ${d.optString("deleted_reason")}", 12.sp, Color(0xFFFF6A5A))
                else if (d.optBoolean("delete_req")) PT("Oyuncu Hesabının Silinmesini İstedi", 12.sp, Px.Orange)
                if (!d.isNull("banned_until")) PT("YASAKLI: ${d.optString("banned_until").take(16)} · ${d.optString("ban_reason")}", 12.sp, Color(0xFFFF6A5A))
                val flags = sec?.optJSONArray("flags")?.length() ?: 0
                if (flags > 0) PT("Hile Şüphesi: $flags Kayıt (Güvenlik Sekmesi)", 12.sp, Px.Orange)
            }
            TagRow(d.optJSONArray("tags"))
        }
        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            listOf("Özet", "Envanter", "Güvenlik", "Son İşlemler", "Sohbetler", "Özel Mesajlar", "Hesap").forEachIndexed { i, n ->
                Box(Modifier.background(if (i == tab) Px.Panel else Px.PanelDark).clickable { tab = i }.padding(horizontal = 10.dp, vertical = 6.dp)) {
                    PT(n, 13.sp, if (i == tab) Px.Text else Px.Sub)
                }
            }
            Spacer(Modifier.weight(1f))
            if (d.optInt("pending") > 0) PT("Bekleyen İşlem: ${d.optInt("pending")}", 12.sp, Px.Orange)
        }
        Column(Modifier.fillMaxWidth().height(320.dp).pxPanel(Px.PanelDark).padding(10.dp).verticalScroll(rememberScrollState())) {
            when (tab) {
                0 -> AdminSummary(target, d, sec, res)
                1 -> {
                    val saves = d.optJSONArray("saves") ?: JSONArray()
                    if (saves.length() == 0) PT("Kayıt Yok", 13.sp, Px.Sub)
                    for (k in 0 until saves.length()) {
                        val s = saves.getJSONObject(k)
                        PT("Sunucu ${s.optString("server")} · Sv ${s.optInt("level")} · ${s.optString("gold")} Altın · ${s.optString("gems")} Elmas · ${s.optString("updated").take(16)}",
                            13.sp, Px.Clan)
                        PT("Eşyaya dokun: kaç adet silineceğini seç ve onayla.", 11.sp, Px.Sub)
                        Spacer(Modifier.height(4.dp))
                        // aynı eşyanın yığınları toplanır
                        val slots = s.optJSONArray("slots") ?: JSONArray()
                        val totals = LinkedHashMap<Int, Int>()
                        for (i in 0 until slots.length()) slots.optJSONObject(i)?.let { totals[it.optInt("item")] = (totals[it.optInt("item")] ?: 0) + it.optInt("count") }
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(5.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                            for ((idx, n) in totals) {
                                Column(Modifier.width(72.dp).clickable { removing = idx to n }, horizontalAlignment = Alignment.CenterHorizontally) {
                                    PxSlot(JSONObject().put("id", itemId(idx)).put("count", n).put("rarity", items.optJSONArray(idx)?.optInt(3) ?: 0), 52.dp)
                                    PT(itemName(idx), 9.sp, Px.Sub, maxLines = 2)
                                }
                            }
                        }
                        Spacer(Modifier.height(8.dp))
                    }
                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        var ask by remember { mutableStateOf(false) }
                        PxButton(if (ask) "Emin Misin? Çanta Tamamen Boşalır" else "Çantayı Boşalt", color = Px.Red, height = 36.dp, size = 12.sp) {
                            if (!ask) ask = true else { ask = false; Account.adminAction(target, JSONObject().put("t", "clear_bag"), res) }
                        }
                    }
                }
                2 -> AdminSecurity(sec, res)
                3 -> LogList(d.optJSONArray("activity")) { o -> "[${ts(o.optLong("ts"))}] ${o.optString("t")}" }
                4 -> LogList(d.optJSONArray("chat")) { o -> "[${ts(o.optLong("ts"))}] (${o.optString("ch")}) ${o.optString("t")}" }
                5 -> LogList(d.optJSONArray("dm")) { o -> "[${ts(o.optLong("ts"))}] ${if (o.optBoolean("out")) "→" else "←"} ${o.optString("to")}: ${o.optString("t")}" }
                else -> AdminAccountTab(target, d, res)
            }
        }
    }
    removing?.let { (idx, have) ->
        RemoveItemDialog(itemName(idx), itemId(idx), have, close = { removing = null }) { n ->
            removing = null
            Account.adminAction(target, JSONObject().put("t", "remove_item").put("item", idx).put("n", n), res)
        }
    }
}

/** Adetli eşya silme: kaydırıcı + hızlı tuşlar + onay. */
@Composable
private fun RemoveItemDialog(name: String, id: String, have: Int, close: () -> Unit, confirm: (Int) -> Unit) {
    var n by remember { mutableIntStateOf(1) }
    var ask by remember { mutableStateOf(false) }
    PxDialog("Eşya Sil", close, width = 460.dp) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            PxSlot(JSONObject().put("id", id).put("count", have), 56.dp)
            Spacer(Modifier.width(10.dp))
            Column { PT(name, 17.sp, Px.Name); PT("Oyuncuda: $have Adet", 13.sp, Px.Sub) }
        }
        Spacer(Modifier.height(10.dp))
        AmountPicker(n, have) { n = it; ask = false }
        Spacer(Modifier.height(10.dp))
        PxButton(if (ask) "Emin Misiniz? $n Adet $name Silinecek" else "$n Adet Sil", Modifier.fillMaxWidth(), Px.Red, height = 44.dp, size = 15.sp) {
            if (!ask) ask = true else confirm(n)
        }
    }
}

/** Adet seçici: −/+ , kaydırıcı ve 1 / Yarısı / Tümü. */
@Composable
fun AmountPicker(value: Int, max: Int, onChange: (Int) -> Unit) {
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        PxButton("−", color = Px.Dark, height = 38.dp, size = 18.sp) { onChange((value - 1).coerceAtLeast(1)) }
        PT("$value", 20.sp, Px.Name, Modifier.width(70.dp))
        PxButton("+", color = Px.Dark, height = 38.dp, size = 18.sp) { onChange((value + 1).coerceAtMost(max)) }
        Spacer(Modifier.width(6.dp))
        PxButton("1", color = Px.Dark, height = 34.dp, size = 13.sp) { onChange(1) }
        PxButton("Yarısı", color = Px.Dark, height = 34.dp, size = 13.sp) { onChange((max / 2).coerceAtLeast(1)) }
        PxButton("Tümü", color = Px.Dark, height = 34.dp, size = 13.sp) { onChange(max) }
    }
    if (max > 1) androidx.compose.material3.Slider(value.toFloat(), { onChange(it.toInt().coerceIn(1, max)) }, valueRange = 1f..max.toFloat())
}

/** Özet: yasak (süre + neden), mesaj, oyundan at, altın/elmas ayarla, yanına ışınlan. */
@Composable
private fun AdminSummary(target: Long, d: JSONObject, sec: JSONObject?, res: (Result<String>) -> Unit) {
    var reason by remember { mutableStateOf("") }
    var amount by remember { mutableStateOf("1") }
    var unit by remember { mutableIntStateOf(1) } // 0 saat, 1 gün
    var msg by remember { mutableStateOf("") }
    var gold by remember { mutableStateOf("") }
    var gems by remember { mutableStateOf("") }
    var lvl by remember { mutableStateOf("") }
    var clvl by remember { mutableStateOf("") }
    val st = d.optJSONObject("stats") ?: JSONObject()
    PT("Hesap Açılışı: ${d.optString("created_at").take(10)} · Son Görülme: ${d.optString("last_seen").take(16).replace('T', ' ')}", 12.sp, Px.Sub)
    if (st.length() > 0) PT("Oynama Süresi: ${st.optLong("time") / 3600} Saat", 12.sp, Px.Sub)
    Spacer(Modifier.height(8.dp))
    PT("Yasakla", 15.sp, Px.Clan)
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        Field(amount, { amount = it.filter(Char::isDigit).take(5) }, "Süre", Modifier.width(90.dp))
        PxButton("Saat", color = if (unit == 0) Px.Blue else Px.Dark, height = 36.dp, size = 12.sp) { unit = 0 }
        PxButton("Gün", color = if (unit == 1) Px.Blue else Px.Dark, height = 36.dp, size = 12.sp) { unit = 1 }
        Field(reason, { reason = it.take(120) }, "Neden (Oyuncu Görür)", Modifier.weight(1f))
    }
    Spacer(Modifier.height(6.dp))
    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        val h = (amount.toIntOrNull() ?: 0) * (if (unit == 0) 1 else 24)
        PxButton("Yasakla", color = Px.Red, height = 38.dp, size = 13.sp, enabled = h > 0) { Account.adminBan(target, h, reason, res) }
        PxButton("Kalıcı Yasakla", color = Px.Red, height = 38.dp, size = 13.sp) { Account.adminBan(target, 87600, reason, res) }
        if (!d.isNull("banned_until")) PxButton("Yasağı Kaldır", color = Px.Green, height = 38.dp, size = 13.sp) { Account.adminBan(target, 0, "", res) }
    }
    Spacer(Modifier.height(10.dp))
    PT("Mesaj / Oyundan At", 15.sp, Px.Clan)
    Field(msg, { msg = it.take(200) }, "Mesaj (Oyuncunun Ekranına Düşer)", Modifier.fillMaxWidth())
    Spacer(Modifier.height(6.dp))
    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        PxButton("Mesaj Gönder", color = Px.Blue, height = 36.dp, size = 13.sp, enabled = msg.isNotBlank()) { Account.adminAction(target, JSONObject().put("t", "msg").put("msg", msg), res) }
        PxButton("Oyundan At", color = Px.Red, height = 36.dp, size = 13.sp) { Account.adminAction(target, JSONObject().put("t", "kick").put("msg", msg), res) }
        PxButton("Fotoğrafı Kaldır", color = Px.Dark, height = 36.dp, size = 13.sp, icon = "trash") { Account.adminAction(target, JSONObject().put("t", "clear_photo"), res) }
        // yanına ışınlan: oyuncu aynı sunucuda çevrimiçiyse anlık konumu
        PxButton("Yanına Işınlan", color = Px.Green, height = 36.dp, size = 13.sp, icon = "map") {
            val pos = Online.position("a$target")
            when {
                pos != null -> {
                    val r = GameSession.cmd("cheat", "text" to "tp ${(pos[0] / 64f).toInt()} ${(pos[1] / 64f).toInt()}")
                    Toaster.show(if (r.ok) "${d.optString("name")} Yanına Işınlandın" else r.msg, r.ok)
                }
                sec?.optBoolean("online") == true -> Toaster.show("Oyuncu ${sec.optString("server")} sunucusunda; o sunucuya geç", false)
                else -> Toaster.show("Oyuncu şu an çevrimiçi değil", false)
            }
        }
    }
    Spacer(Modifier.height(10.dp))
    PT("Altın / Elmas", 15.sp, Px.Clan)
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        Field(gold, { gold = it.filter(Char::isDigit).take(9) }, "Altın", Modifier.width(130.dp))
        PxButton("Altını Ayarla", color = Px.Dark, height = 38.dp, size = 12.sp, enabled = gold.isNotEmpty()) {
            Account.adminAction(target, JSONObject().put("t", "set_gold").put("v", gold.toLongOrNull() ?: 0), res)
        }
        Field(gems, { gems = it.filter(Char::isDigit).take(7) }, "Elmas", Modifier.width(110.dp))
        PxButton("Elması Ayarla", color = Px.Dark, height = 38.dp, size = 12.sp, enabled = gems.isNotEmpty()) {
            Account.adminAction(target, JSONObject().put("t", "set_gems").put("v", gems.toLongOrNull() ?: 0), res)
        }
    }
    Spacer(Modifier.height(6.dp))
    // V20: oyuncu seviyesi (1-50) ve şu an seçili karakterin seviyesi; oyuncu çevrimdışıysa ilk girişte uygulanır
    PT("Seviye", 15.sp, Px.Clan)
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        Field(lvl, { lvl = it.filter(Char::isDigit).take(2) }, "Oyuncu Sv", Modifier.width(110.dp))
        PxButton("Seviyeyi Ayarla", color = Px.Dark, height = 38.dp, size = 12.sp, enabled = lvl.isNotEmpty()) {
            Account.adminAction(target, JSONObject().put("t", "set_level").put("v", lvl.toIntOrNull() ?: 1), res)
        }
        Field(clvl, { clvl = it.filter(Char::isDigit).take(2) }, "Karakter Sv", Modifier.width(120.dp))
        PxButton("Karakter Seviyesi", color = Px.Dark, height = 38.dp, size = 12.sp, enabled = clvl.isNotEmpty()) {
            Account.adminAction(target, JSONObject().put("t", "set_char_level").put("v", clvl.toIntOrNull() ?: 1), res)
        }
    }
    Spacer(Modifier.height(6.dp))
    PT("Kanat (yalnız yönetici takar)", 15.sp, Px.Clan)
    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
        for ((id, name) in listOf("wings_ash" to "Kor", "wings_dragon" to "Ejder", "wings_titan" to "Titan", "wings_s1" to "Sezon 1"))
            PxButton(name, color = Color(0xFF3A4A8A), height = 38.dp, size = 12.sp) {
                Account.adminAction(target, JSONObject().put("t", "set_wings").put("id", id), res)
            }
        PxButton("Kanadı Çıkar", color = Px.Dark, height = 38.dp, size = 12.sp) { Account.adminAction(target, JSONObject().put("t", "set_wings").put("id", ""), res) }
    }
}

/** Güvenlik: hile kayıtları, cihazlar (aynı cihazdaki diğer hesap sayısı), cihaz yasağı. */
@Composable
private fun AdminSecurity(sec: JSONObject?, res: (Result<String>) -> Unit) {
    if (sec == null) { PT("Yükleniyor…", 13.sp, Px.Sub); return }
    PT("Cihazlar", 15.sp, Px.Clan)
    val devs = sec.optJSONArray("devices") ?: JSONArray()
    if (devs.length() == 0) PT("Kayıt Yok", 13.sp, Px.Sub)
    for (i in 0 until devs.length()) {
        val o = devs.getJSONObject(i)
        val info = o.optJSONObject("info") ?: JSONObject()
        Row(Modifier.fillMaxWidth().padding(vertical = 3.dp), verticalAlignment = Alignment.CenterVertically) {
            Column(Modifier.weight(1f)) {
                PT("${o.optString("model")} · Android ${info.optInt("sdk")} · ${ts(o.optLong("last"))}", 13.sp, Px.Text)
                val warn = listOfNotNull("Root".takeIf { info.optBoolean("root") }, "Emülatör".takeIf { info.optBoolean("emu") },
                    "Kanca".takeIf { info.optBoolean("hook") }, "İmza".takeIf { !info.optBoolean("sig", true) })
                PT("Kimlik ${o.optString("id").take(10)}… · Aynı Cihazda ${o.optInt("others")} Başka Hesap" +
                    (if (warn.isNotEmpty()) " · ⚠ " + warn.joinToString(", ") else ""), 11.sp, if (warn.isEmpty()) Px.Sub else Px.Orange, maxLines = 2)
            }
            val banned = o.optBoolean("banned")
            PxButton(if (banned) "Cihaz Yasağını Kaldır" else "Cihazı Yasakla", color = if (banned) Px.Green else Px.Red, height = 34.dp, size = 11.sp) {
                Account.adminBanDevice(o.optString("id"), !banned, "Yönetici kararı", res)
            }
        }
    }
    Spacer(Modifier.height(10.dp))
    PT("Hile Şüphesi Kayıtları", 15.sp, Px.Clan)
    LogList(sec.optJSONArray("flags")) { o ->
        val k = when (o.optString("k")) { "save" -> "Kayıt Reddi"; "sig" -> "İmza"; "speed" -> "Hız"; "trade" -> "Takas"; "device" -> "Cihaz"; "client" -> "Uygulama"; else -> o.optString("k") }
        "[${ts(o.optLong("ts"))}] $k: ${o.optString("t")}"
    }
}

@Composable
private fun LogList(a: JSONArray?, line: (JSONObject) -> String) {
    if (a == null || a.length() == 0) { PT("Kayıt Yok", 13.sp, Px.Sub); return }
    for (i in 0 until a.length()) PT(line(a.getJSONObject(i)), 12.sp, Px.Text, maxLines = 3)
}

/** Hesap işlemleri: silme (onaylı, geri alınabilir), geri getirme, anahtar sıfırlama (yeni anahtar kopyalanır). */
@Composable
private fun AdminAccountTab(target: Long, d: JSONObject, res: (Result<String>) -> Unit) {
    val ctx = androidx.compose.ui.platform.LocalContext.current
    var reason by remember { mutableStateOf("") }
    var confirm by remember { mutableStateOf(false) }
    var newKey by remember { mutableStateOf("") }
    if (d.optBoolean("admin")) { PT("Yönetici Hesabı: Silinemez Ve Anahtarı Buradan Değişmez.", 14.sp, Px.Sub); return }
    if (d.optBoolean("deleted")) {
        PT("Bu Hesap Silinmiş. Oyuncu Giriş Yapamaz; Kayıtları Duruyor.", 14.sp, Px.Sub, maxLines = 2)
        Spacer(Modifier.height(8.dp))
        PxButton("Hesabı Geri Getir", color = Px.Green, height = 40.dp, size = 14.sp) { Account.adminRestore(target, res) }
        return
    }
    PT("Hesabı Sil", 15.sp, Px.Clan)
    PT("Oyuncu bir daha giriş yapamaz, klandan çıkar ve Google bağı kalkar. Kayıtlar silinmez; gerekirse geri getirilebilir.", 12.sp, Px.Sub, maxLines = 3)
    Spacer(Modifier.height(6.dp))
    Field(reason, { reason = it.take(120) }, "Silme Nedeni", Modifier.fillMaxWidth())
    Spacer(Modifier.height(6.dp))
    PxButton(if (confirm) "Emin Misin? Tekrar Bas" else "Hesabı Sil", color = Px.Red, height = 40.dp, size = 14.sp) {
        if (!confirm) confirm = true else { confirm = false; Account.adminDelete(target, reason, res) }
    }
    Spacer(Modifier.height(14.dp))
    PT("Anahtarı Sıfırla", 15.sp, Px.Clan)
    PT("Anahtarını kaybeden oyuncuya yeni anahtar üretir; eski anahtar hemen geçersiz olur.", 12.sp, Px.Sub, maxLines = 2)
    Spacer(Modifier.height(6.dp))
    Row(verticalAlignment = Alignment.CenterVertically) {
        PxButton("Yeni Anahtar Üret", color = Px.Blue, height = 40.dp, size = 14.sp) {
            Account.adminResetKey(target) { r -> r.onSuccess { newKey = it }.onFailure { Toaster.show(it.message ?: "", false) } }
        }
        if (newKey.isNotEmpty()) {
            Spacer(Modifier.width(10.dp))
            PT(newKey, 18.sp, Px.Name)
            Spacer(Modifier.width(8.dp))
            PxButton("Kopyala", color = Px.Dark, height = 34.dp, size = 12.sp) {
                copy(ctx, "Zenvex ID: ${fmtId(target)}  Anahtar: $newKey"); Toaster.show("Kopyalandı")
            }
        }
    }
}

/** Silme talepleri listesi (Ayarlar → Hesabımı Sil ile gelenler); dokununca oyuncu dosyası açılır. */
@Composable
fun AdminDeleteRequests(open: (Long) -> Unit) {
    var list by remember { mutableStateOf<JSONArray?>(null) }
    LaunchedEffect(Unit) { Account.adminDeleteRequests { r -> list = r.getOrNull() ?: JSONArray() } }
    val l = list ?: run { PT("Yükleniyor…", 13.sp, Px.Sub); return }
    if (l.length() == 0) { PT("Silme Talebi Yok.", 13.sp, Px.Sub); return }
    for (i in 0 until l.length()) {
        val o = l.getJSONObject(i)
        Row(Modifier.fillMaxWidth().clickable { open(o.optLong("id")) }.padding(vertical = 4.dp), verticalAlignment = Alignment.CenterVertically) {
            PT("${o.optString("name")} · ${fmtId(o.optLong("id"))} · Sv ${o.optInt("level")}", 14.sp, Px.Text, modifier = Modifier.weight(1f))
            PT(ts(o.optLong("at")), 12.sp, Px.Sub)
        }
    }
}

/**
 * Eşya seçici (posta eki, hile): arama + nadirliğe göre renkli ızgara; seçilen eşya için adet girilir.
 * [pick] (kimlik, adet) ile döner.
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
fun ItemPickerDialog(title: String, close: () -> Unit, maxAmount: Int = 9999, pick: (String, Int) -> Unit) {
    val items = remember { GameSession.ui("cheat").optJSONArray("items") ?: allItems() }
    var q by remember { mutableStateOf("") }
    var sel by remember { mutableStateOf<JSONArray?>(null) }
    var n by remember { mutableStateOf("1") }
    // V19: türe göre süzme (yalnız oyunda olan eşyalar gelir; kalkmış eşyalar listede yok)
    var kind by remember { mutableStateOf("") }
    val kinds = remember(items) { (0 until items.length()).mapNotNull { items.optJSONArray(it)?.optString(2) }.distinct() }
    PxDialog(title, close, width = 760.dp) {
        Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            for (k in listOf("") + kinds) PxButton(ITEM_KIND_TR[k] ?: k, color = if (kind == k) Px.Green else Px.Dark, height = 30.dp, size = 11.sp) { kind = k }
        }
        Spacer(Modifier.height(6.dp))
        Row(verticalAlignment = Alignment.CenterVertically) {
            Field(q, { q = it.take(24) }, "Eşya Ara (Ad)", Modifier.weight(1f))
            Spacer(Modifier.width(8.dp))
            val s = sel
            if (s != null) {
                PxSlot(JSONObject().put("id", s.optString(0)).put("rarity", s.optInt(3)), 44.dp)
                Spacer(Modifier.width(6.dp))
                Field(n, { n = it.filter(Char::isDigit).take(5) }, "Adet", Modifier.width(90.dp))
                Spacer(Modifier.width(6.dp))
                PxButton("Ekle", color = Px.Green, height = 42.dp, size = 14.sp) {
                    pick(s.optString(0), (n.toIntOrNull() ?: 1).coerceIn(1, maxAmount)); close()
                }
            }
        }
        Spacer(Modifier.height(6.dp))
        sel?.let { PT("${it.optString(1)} Seçildi · Adet Yaz Ve Ekle", 13.sp, Px.Name) }
        Column(Modifier.height(300.dp).verticalScroll(rememberScrollState())) {
            FlowRow(horizontalArrangement = Arrangement.spacedBy(5.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                for (i in 0 until items.length()) {
                    val a = items.optJSONArray(i) ?: continue
                    if (q.isNotBlank() && !a.optString(1).contains(q.trim(), ignoreCase = true)) continue
                    if (kind.isNotEmpty() && a.optString(2) != kind) continue
                    val chosen = sel?.optString(0) == a.optString(0)
                    Column(Modifier.width(72.dp).clickable { sel = a }, horizontalAlignment = Alignment.CenterHorizontally) {
                        PxSlot(JSONObject().put("id", a.optString(0)).put("rarity", a.optInt(3)), 50.dp, selected = chosen)
                        PT(a.optString(1), 9.sp, if (chosen) Px.Name else Px.Sub, maxLines = 2)
                    }
                }
            }
        }
    }
}

private val ITEM_KIND_TR = mapOf("" to "Hepsi", "Weapon" to "Silah", "Tool" to "Alet", "Helmet" to "Kask", "Jacket" to "Ceket", "Pants" to "Pantolon",
    "Boots" to "Bot", "Bag" to "Çanta", "Ring" to "Yüzük", "Necklace" to "Kolye", "Consumable" to "Tüketim", "Material" to "Malzeme",
    "Chest" to "Sandık", "Bench" to "Tezgâh", "Vehicle" to "Araç", "Part" to "Parça")

