/**
 * Bakım ve yasak kapıları: uygulama açıkken dakikada bir sunucuya sorulur.
 * Bakım açıkken yönetici hesabı ve yönetici cihazı (yönetici hesabının girdiği telefon) dışında herkes bakım ekranında kalır.
 */
object Gate {
    val maintenance = androidx.compose.runtime.mutableStateOf<JSONObject?>(null)

    /** Sunucuya ulaşılamıyor: oyun tamamen çevrimiçi olduğu için hiçbir ekran açılmaz (bakım ekranı da atlanamaz). */
    val offline = androidx.compose.runtime.mutableStateOf(false)

    fun poll() = Account.status { r ->
        r.onSuccess { m -> offline.value = false; maintenance.value = if (m.optBoolean("on")) m else null }
            .onFailure { e -> if (e.message.orEmpty().contains("ulaşılamadı")) offline.value = true }
    }
}

@Composable
fun GateHost() {
    LaunchedEffect(Unit) { while (true) { Gate.poll(); delay(if (Gate.offline.value) 6_000 else 45_000) } }
    val ban = Account.banned.value
    val m = Gate.maintenance.value
    when {
        ban != null -> BanScreen(ban)
        Gate.offline.value && !Demo.on -> NoConnectionScreen()
        m != null && !Account.admin.value && !Account.adminDevice.value -> MaintenanceScreen(MaintMsg.pick(m.optString("msg"), com.zenvex.online.I18n.lang))
    }
}

/**
 * Bakım mesajı çok dillidir: yönetici her dil için ayrı metin yazar, sunucuda {"tr": "...", "en": "..."} JSON'u olarak durur
 * (eski düz metin de çalışır). Oyuncu kendi dilini görür; yoksa İngilizce, o da yoksa Türkçe, o da yoksa ilk dolu metin.
 */
object MaintMsg {
    fun parse(raw: String): Map<String, String> {
        if (raw.isBlank()) return emptyMap()
        if (!raw.trimStart().startsWith("{")) return mapOf("tr" to raw)
        return runCatching {
            val o = JSONObject(raw)
            o.keys().asSequence().associateWith { o.optString(it) }.filterValues { it.isNotBlank() }
        }.getOrDefault(mapOf("tr" to raw))
    }

    fun pick(raw: String, lang: String): String {
        val m = parse(raw)
        return m[lang] ?: m["en"] ?: m["tr"] ?: m.values.firstOrNull() ?: ""
    }

    fun encode(m: Map<String, String>): String {
        val o = JSONObject()
        for ((k, v) in m) if (v.isNotBlank()) o.put(k, v.trim())
        return if (o.length() == 0) "" else o.toString()
    }
}

/** İnternet yok: oyun çevrimiçi olduğu için her şeyin üstünde kalır; bağlantı gelince kendiliğinden kapanır. */
