            }
            drawPath(heart, Brush.verticalGradient(listOf(Color(0xFFFF8A8A), Color(0xFFD02030)), 0.3f * w, 0.75f * w))
            drawPath(heart, Color(0xFF3A0810), style = Stroke(w * 0.035f, join = StrokeJoin.Round))
