            drawCircle(Color.Black.copy(alpha = 0.7f), w * 0.09f, p(0.38f, 0.44f)); drawCircle(Color.Black.copy(alpha = 0.7f), w * 0.09f, p(0.62f, 0.44f))
        }
        "clock" -> {
