            drawLine(c, p(0.5f, 0.5f), p(0.5f, 0.28f), w * 0.08f, StrokeCap.Round)
            drawLine(c, p(0.5f, 0.5f), p(0.66f, 0.58f), w * 0.08f, StrokeCap.Round)
        }
        "calendar" -> {
