// com/zenvex/online/ui/Px.kt
// ====================================================================================================

// =========================================================================== piksel arayüz (lobi + oyun içi)
val PixelFont = FontFamily(Font(R.font.pixel))

object Px {
    val Panel = Color(0xF02B2B26)
    val PanelDark = Color(0xF0201F1C)
    val Row = Color(0xFF34342E)
    val RowHi = Color(0xFF3E3E36)
    val Edge = Color(0xFF15140F)
    val Text = Color(0xFFE8E4D4)
    val Sub = Color(0xFFA8A48E)
    val Green = Color(0xFF6E8C3A)
    val GreenHi = Color(0xFF86A74A)
    val Blue = Color(0xFF4A6FB5)
    val Red = Color(0xFF8A4A44)
    val Dark = Color(0xFF3A3A33)
    val Name = Color(0xFF45E04F)
    val Level = Color(0xFF9F92FF)
    val Clan = Color(0xFFF6E05A)
    val Orange = Color(0xFFFFB347)
    val Hard = Color(0xFFE8A060)
}

private val TR = java.util.Locale.forLanguageTag("tr-TR")

/**
 * Türkçe "Her Kelimenin İlk Harfi Büyük": yalnız küçük harfle başlayan kelimelerin ilk harfi büyütülür
 * (i → İ doğru çevrilir; XP, Sv, rakamlar ve simgeler olduğu gibi kalır).
 */
fun String.titleTr(): String {
    val sb = StringBuilder(length)
    var start = true
    for (ch in this) {
        if (start && ch.isLetter() && ch.isLowerCase()) sb.append(ch.toString().uppercase(TR)) else sb.append(ch)
        start = ch.isWhitespace() || ch == '(' || ch == '/' || ch == '"' || ch == '·' || ch == '-' || ch == '→'
    }
    return sb.toString()
}

/** Piksel yazı: sert (bulanıksız) gölge. Tek satırlık yazılar (başlık, tuş, etiket) Her Kelime Büyük yazılır. */
@Composable
fun PT(
    text: String,
    size: TextUnit = 16.sp,
    color: Color = Px.Text,
    modifier: Modifier = Modifier,
    align: TextAlign? = null,
    maxLines: Int = 1,
    outline: Boolean = false,
) {
    Text(
        I18n.show(text, maxLines == 1), modifier, color = color, textAlign = align, maxLines = maxLines, overflow = TextOverflow.Ellipsis,
        style = TextStyle(
            fontFamily = PixelFont, fontSize = size,
            shadow = Shadow(Color(0xE6000000), Offset(if (outline) 3f else 2f, if (outline) 3f else 2f), 0f),
        ),
    )
}

/** Koyu panel (piksel kenarlı): üstten hafif ışık, kenar içinde ince ışık çizgisi ve alt gölge (kabartma). */
fun Modifier.pxPanel(color: Color = Px.Panel): Modifier = this
    .clip(RoundedCornerShape(3.dp))
    .background(color)
    .pxBevel()
    .border(2.dp, Px.Edge, RoundedCornerShape(3.dp))

/**
 * Kabartma ışığı: üstten aşağı sönen parlaklık, kenarın hemen içinde 1 dp ışık (üst) ve gölge (alt) çizgisi.
 * [raised] false: gömük (ışık altta, gölge üstte) — ray, yuva gibi içe basık yüzeyler için.
 */
fun Modifier.pxBevel(raised: Boolean = true, light: Float = 0.06f): Modifier = drawBehind {
    val e = 2.dp.toPx(); val l = 1.dp.toPx()
    val w = size.width; val h = size.height
    if (raised) {
        drawRect(Brush.verticalGradient(listOf(Color.White.copy(alpha = light), Color.Transparent), 0f, h * 0.55f), Offset.Zero, Size(w, h * 0.55f))
        drawRect(Color.White.copy(alpha = light * 1.4f), Offset(e, e), Size(w - e * 2, l))
        drawRect(Color.Black.copy(alpha = 0.28f), Offset(e, h - e - l), Size(w - e * 2, l))
    } else {
        drawRect(Brush.verticalGradient(listOf(Color.Black.copy(alpha = 0.30f), Color.Transparent), 0f, h * 0.5f), Offset.Zero, Size(w, h * 0.5f))
        drawRect(Color.White.copy(alpha = light), Offset(e, h - e - l), Size(w - e * 2, l))
    }
}

@Composable
fun PxPanel(modifier: Modifier = Modifier, color: Color = Px.Panel, pad: Dp = 10.dp, content: @Composable ColumnScope.() -> Unit) {
    Column(modifier.pxPanel(color).padding(pad), content = content)
}

/**
 * Piksel buton: perçinli metal plaka. Üstte ışık şeridi, altta kalın gölge şeridi (kabartma), köşelerde perçin;
 * basılınca plaka gölge kadar aşağı iner (gömülme), devre dışıyken çapraz çizgili.
 */
@Composable
fun PxButton(
    text: String,
    modifier: Modifier = Modifier,
    color: Color = Px.Green,
    icon: String? = null,
    size: TextUnit = 18.sp,
    height: Dp = 44.dp,
    enabled: Boolean = true,
    textColor: Color = Color.White,
    onClick: () -> Unit,
) {
    val src = remember { MutableInteractionSource() }
    val pressed by src.collectIsPressedAsState()
    val sink by animateFloatAsState(if (pressed && enabled) 1f else 0f, spring(0.6f, 1400f), label = "px")
    val c = if (enabled) color else Px.Dark
    // V10 metal tuş görselleri: kızıl (normal / basılı) ve kapalı; diğer renkler kodla çizilir
    val ctx = LocalContext.current
    val art = when {
        !enabled -> remember { UiArt.image(ctx, "btn_off") }
        color == Px.Red -> if (pressed) remember { UiArt.image(ctx, "btn_red_down") } else remember { UiArt.image(ctx, "btn_red") }
        else -> null
    }
    Box(
        modifier.height(height).clip(RoundedCornerShape(3.dp))
            .drawBehind {
                val e = 4.dp.toPx(); val down = e * sink
                val w = this.size.width; val h = this.size.height
                if (art != null) { drawSlice3(art, 0f, 0f, w, h, 32); return@drawBehind }
                // gövde gölgesi (kabartma alt kenarı)
                drawRect(Px.Edge, Offset(0f, 0f), Size(w, h))
                drawRect(Color(c.red * 0.55f, c.green * 0.55f, c.blue * 0.55f, 1f), Offset(2f, down + 2f), Size(w - 4f, h - 4f - down))
                // yüz
                drawRect(c, Offset(2f, down + 2f), Size(w - 4f, h - 4f - e))
                drawRect(Brush.verticalGradient(listOf(Color.White.copy(alpha = 0.18f), Color.Transparent), down, down + h * 0.6f),
                    Offset(2f, down + 2f), Size(w - 4f, (h - 4f - e) * 0.6f))
                drawRect(Color.White.copy(alpha = 0.3f), Offset(2f, down + 2f), Size(w - 4f, 2.dp.toPx()))
                if (!enabled) {
                    val st = 8.dp.toPx(); var x = -h
                    while (x < w) { drawLine(Color.Black.copy(alpha = 0.18f), Offset(x, h), Offset(x + h, 0f), 2.dp.toPx()); x += st }
                }
                // perçinler
                val rv = 1.6.dp.toPx(); val ins = 5.dp.toPx()
                for ((rx, ry) in listOf(ins to ins + down, w - ins to ins + down, ins to h - e - ins + down, w - ins to h - e - ins + down)) {
                    drawCircle(Color.Black.copy(alpha = 0.45f), rv, Offset(rx + 0.6f, ry + 0.6f))
                    drawCircle(Color.White.copy(alpha = 0.45f), rv, Offset(rx, ry))
                }
            }
            .clickable(interactionSource = src, indication = null) {
                Audio.play("click", bus = Audio.Bus.Ui, pitch = if (enabled) 1f else 0.7f)
                if (enabled) onClick()
            }
            .padding(start = 14.dp, end = 14.dp, top = (2 + 4 * sink).dp, bottom = (6 - 4 * sink).dp),
        contentAlignment = Alignment.Center,
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            if (icon != null) {
                Icon(icon, (height.value * 0.45f).dp, textColor)
                if (text.isNotEmpty()) Spacer(Modifier.width(10.dp))
            }
            if (text.isNotEmpty()) PT(text, size, if (enabled) textColor else Px.Sub)
        }
    }
}

/** Oyun içi kare ikon tuşu (rozetli). */
@Composable
fun PxIcon(icon: String, modifier: Modifier = Modifier, size: Dp = 48.dp, badge: Int = 0, tint: Color = Px.Text, color: Color = Color(0xCC2B2B26),
           art: String? = null, onClick: () -> Unit) {
    // [art]: assets/ui/<art>.png varsa simge yerine o çizilir (görsel gelince kod değişmeden kullanılır)
    val hasArt = art != null && UiArt.has(androidx.compose.ui.platform.LocalContext.current, art)
    val src = remember { MutableInteractionSource() }
    val pressed by src.collectIsPressedAsState()
    val sc by animateFloatAsState(if (pressed) 0.9f else 1f, spring(0.5f, 900f), label = "pxi")
    Box(modifier.scale(sc)) {
        Box(
            Modifier.size(size).clip(RoundedCornerShape(6.dp)).background(color).border(2.dp, Px.Edge, RoundedCornerShape(6.dp))
                .clickable(interactionSource = src, indication = null) { Audio.play("click", bus = Audio.Bus.Ui); onClick() },
            contentAlignment = Alignment.Center,
        ) { if (hasArt) ArtImage(art, Modifier.size(size * 0.86f)) else Icon(icon, size * (if (icon in PIXEL_ICONS) 0.72f else 0.56f), tint) }
        // posta: kırmızı mühürlü zarf rozeti (V13), sayı üstünde
        if (badge > 0 && icon == "mail") Box(Modifier.align(Alignment.TopEnd).offset(8.dp, (-8).dp).size(24.dp), contentAlignment = Alignment.Center) {
            ArtImage("mail_badge", Modifier.fillMaxSize())
            PT(if (badge > 9) "9+" else "$badge", 10.sp, outline = true, modifier = Modifier.offset(7.dp, 7.dp))
        } else if (badge > 0) Box(
            Modifier.align(Alignment.TopEnd).offset(6.dp, (-6).dp).size(20.dp).clip(CircleShape).background(Color(0xFFE02828))
                .border(1.5.dp, Color.White, CircleShape),
            contentAlignment = Alignment.Center,
        ) { PT(if (badge > 9) "9+" else "$badge", 11.sp) }
    }
}

/** Zombix tarzı iki sekme (Sunucular / Karakter). */
@Composable
fun PxTabs(items: List<String>, selected: Int, modifier: Modifier = Modifier, onSelect: (Int) -> Unit) {
    Row(modifier, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
        items.forEachIndexed { i, s ->
            val on = i == selected
            Box(
                Modifier.weight(1f).height(48.dp)
                    .artBehind(if (on) "tab_on" else "tab_off", slice = 28,
                        fallback = Modifier.clip(RoundedCornerShape(topStart = 3.dp, topEnd = 3.dp)).background(if (on) Px.Panel else Px.PanelDark))
                    .clickable { Audio.play("click", bus = Audio.Bus.Ui); onSelect(i) },
                contentAlignment = Alignment.Center,
            ) { PT(s, 22.sp, if (on) Px.Text else Px.Sub) }
        }
    }
}

/** Seviye rozeti (yuvarlak, rakamlı). */
@Composable
fun LevelBadge(level: Int, modifier: Modifier = Modifier, size: Dp = 26.dp) {
    Box(modifier.size(size).clip(CircleShape).background(Color(0xFF26262A)).border(2.dp, Color(0xFFB8B8C8), CircleShape), contentAlignment = Alignment.Center) {
        PT("$level", (size.value * 0.48f).sp)
    }
}

/** Basit piksel çubuk. */
@Composable
fun PxBar(value: Float, color: Color, modifier: Modifier = Modifier, height: Dp = 10.dp) {
    Box(modifier.height(height).background(Color(0xFF15140F)).padding(2.dp)) {
        Box(Modifier.fillMaxWidth(value.coerceIn(0f, 1f)).height(height - 4.dp).background(color)
            .drawBehind { drawRect(Color.White.copy(alpha = 0.25f), Offset.Zero, Size(size.width, size.height * 0.35f)) })
    }
}

// =========================================================================== dünya haritası arka planı
object WorldMapImage {
    /** Harita çözünürlüğü: 1 piksel ≈ 30 dünya pikseli (V8: harita 720 kare; binalar, ağaçlar seçilir) */
    const val SIZE = 1536
    @Volatile private var bmp: Bitmap? = null
    @Volatile private var img: ImageBitmap? = null

    /** Dünyanın piksel haritası (ilk çağrıda Rust'tan üretilir, önbelleklenir; mini harita da bunu kullanır). */
    fun bitmap(): Bitmap? {
        bmp?.let { return it }
        if (GameSession.handle == 0L) return null
        val px = IntArray(SIZE * SIZE)
        synchronized(GameSession.lock) { Native.minimap(GameSession.handle, SIZE, px) }
        val b = Bitmap.createBitmap(px, SIZE, SIZE, Bitmap.Config.ARGB_8888)
        bmp = b
        return b
    }

    fun get(): ImageBitmap? {
        img?.let { return it }
        val b = bitmap()?.asImageBitmap() ?: return null
        img = b
        return b
    }
}

/** Lobi arka planı: yavaşça kayan piksel dünya haritası. */
@Composable
fun MapBackground(t: Float, modifier: Modifier = Modifier.fillMaxSize(), dim: Float = 0.25f, content: @Composable BoxScope.() -> Unit = {}) {
    val img = remember { WorldMapImage.get() }
    Box(modifier.background(Color(0xFF3A5A2A))) {
        if (img != null) Canvas(Modifier.fillMaxSize()) {
            // ekranı kaplayacak ölçek + yavaş gezinme
            val k = maxOf(size.width / img.width, size.height / img.height) * 1.55f
            val dw = img.width * k; val dh = img.height * k
            val ox = (size.width - dw) * (0.5f + 0.42f * sin(t * 0.021f))
            val oy = (size.height - dh) * (0.5f + 0.42f * sin(t * 0.017f + 1.3f))
            drawImage(img, IntOffset.Zero, IntSize(img.width, img.height), IntOffset(ox.toInt(), oy.toInt()), IntSize(dw.toInt(), dh.toInt()),
                filterQuality = FilterQuality.None)
            drawRect(Color.Black.copy(alpha = dim))
        }
        content()
    }
}

// ====================================================================================================
// com/zenvex/online/ui/SceneShaders.kt
// ====================================================================================================

/**
 * Canlı sahnenin GPU gölgelendiricileri (AGSL, Android 13+): gerçekçi gökyüzü (saçılma, hacimli bulut, ışık huzmeleri),
 * gürültüyle akan alev (kara cisim renk rampası), kıvrılarak yükselen duman ve sürüklenen sis. Daha eski cihazlarda ve
 * gölgelendirici derlenemezse sahne eski yol çizimine döner (bkz. [SceneShaders.create]).
 */
@RequiresApi(Build.VERSION_CODES.TIRAMISU)
class SceneShaders private constructor() {
    private val sky = RuntimeShader(NOISE + SKY)
    private val fires = List(8) { RuntimeShader(NOISE + FIRE) }
    private val smokes = List(8) { RuntimeShader(NOISE + SMOKE) }
    private val fogs = List(4) { RuntimeShader(NOISE + FOG) }
    private val skyBrush = ShaderBrush(sky)
    private val fireBrushes = fires.map { ShaderBrush(it) }
    private val smokeBrushes = smokes.map { ShaderBrush(it) }
    private val fogBrushes = fogs.map { ShaderBrush(it) }

    fun sky(
        w: Float, h: Float, t: Float, horizon: Float, sunX: Float, sunY: Float, sunR: Float, breath: Float, flash: Float, rays: Boolean,
        top: Color, mid: Color, hor: Color, sun: Color,
    ): Brush {
        sky.setFloatUniform("iRes", w, h)
        sky.setFloatUniform("iTime", t)
        sky.setFloatUniform("horizon", horizon)
        sky.setFloatUniform("sun", sunX, sunY)
        sky.setFloatUniform("sunR", sunR)
        sky.setFloatUniform("breath", breath)
        sky.setFloatUniform("flash", flash)
        sky.setFloatUniform("rays", if (rays) 1f else 0f)
        sky.setColorUniform("cTop", top.toArgb())
        sky.setColorUniform("cMid", mid.toArgb())
        sky.setColorUniform("cHor", hor.toArgb())
        sky.setColorUniform("cSun", sun.toArgb())
        return skyBrush
    }

    /** alev: (x, y) taban ortası, hw yarı genişlik, hh yükseklik (piksel) */
    fun fire(i: Int, x: Float, y: Float, hw: Float, hh: Float, t: Float, seed: Float, tint: Color): Brush {
        val s = fires[i % fires.size]
        s.setFloatUniform("origin", x, y)
        s.setFloatUniform("dim", hw, hh)
        s.setFloatUniform("iTime", t)
        s.setFloatUniform("seed", seed)
        s.setColorUniform("tint", tint.toArgb())
        return fireBrushes[i % fires.size]
    }

    /** duman sütunu: (x, y) taban, u genişlik birimi, hh yükseklik, drift sağa kayma (u cinsinden) */
    fun smoke(i: Int, x: Float, y: Float, u: Float, hh: Float, drift: Float, t: Float, seed: Float, smoke: Color, glow: Color): Brush {
        val s = smokes[i % smokes.size]
        s.setFloatUniform("origin", x, y)
        s.setFloatUniform("dim", u, hh)
        s.setFloatUniform("drift", drift)
        s.setFloatUniform("iTime", t)
        s.setFloatUniform("seed", seed)
        s.setColorUniform("smokeCol", smoke.toArgb())
        s.setColorUniform("glowCol", glow.toArgb())
        return smokeBrushes[i % smokes.size]
    }

    /** yatay sis bandı: y0..y1 arası, strength yoğunluk */
    fun fog(i: Int, y0: Float, y1: Float, h: Float, t: Float, seed: Float, strength: Float, col: Color): Brush {
        val s = fogs[i % fogs.size]
        s.setFloatUniform("band", y0, y1)
        s.setFloatUniform("iH", h)
        s.setFloatUniform("iTime", t)
        s.setFloatUniform("seed", seed)
        s.setFloatUniform("strength", strength)
        s.setColorUniform("fogCol", col.toArgb())
        return fogBrushes[i % fogs.size]
    }

    companion object {
        private var failed = false
        private var shared: Any? = null

        /** Android 13+ ve derleme başarılıysa tek ortak örnek; aksi halde null (yol çizimine dönülür). */
        fun create(): SceneShaders? {
            if (failed || Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return null
            (shared as? SceneShaders)?.let { return it }
            return runCatching { SceneShaders() }.onFailure { failed = true }.getOrNull()?.also { shared = it }
        }

        private const val NOISE = """
float hash(float2 p) {
    p = fract(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
float noise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + float2(1.0, 0.0)), u.x), mix(hash(i + float2(0.0, 1.0)), hash(i + float2(1.0, 1.0)), u.x), u.y);
}
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p = p * 2.03 + float2(17.1, 9.2);
        a *= 0.5;
    }
    return v;
}
"""

        private const val SKY = """
uniform float2 iRes;
uniform float iTime;
uniform float horizon;
uniform float2 sun;
uniform float sunR;
uniform float breath;
uniform float flash;
uniform float rays;
layout(color) uniform half4 cTop;
layout(color) uniform half4 cMid;
layout(color) uniform half4 cHor;
layout(color) uniform half4 cSun;

half4 main(float2 fc) {
    float H = iRes.y;
    float y = fc.y / horizon;
    float3 top = float3(cTop.rgb);
    float3 mid = float3(cMid.rgb);
    float3 hor = float3(cHor.rgb);
    float3 sc = float3(cSun.rgb);
    // atmosfer: zenit koyu, ufka doğru sıcak saçılma
    float3 col = mix(top, mix(mid, hor, 0.08 * breath), smoothstep(0.0, 0.55, y));
    col = mix(col, mix(mid, hor, 0.55 + 0.1 * breath), smoothstep(0.45, 0.86, y));
    col = mix(col, mix(hor, sc, 0.25), smoothstep(0.82, 1.1, y));
    float2 d = (fc - sun) / H;
    float r = length(d);
    // Mie saçılması: güneşin etrafında geniş + dar hale
    col += sc * (exp(-r * 4.5) * 0.42 + exp(-r * 16.0) * 0.45);
    // ufuk bandı güneşin altında daha parlak
    col += sc * exp(-abs(fc.x - sun.x) / iRes.x * 2.6) * smoothstep(0.6, 1.0, y) * 0.22;
    // yıldızlar (yalnız üst gök)
    float2 sg = fc / (H * 0.011);
    float2 si = floor(sg);
    float sh = hash(si);
    if (sh > 0.968) {
        float2 sp = fract(sg) - 0.5 - (float2(hash(si + 3.1), hash(si + 7.7)) - 0.5) * 0.6;
        float tw = 0.45 + 0.55 * sin(iTime * (1.0 + sh * 3.0) + sh * 40.0);
        col += smoothstep(0.13, 0.0, length(sp)) * tw * (1.0 - smoothstep(0.08, 0.6, y)) * 0.75;
    }
    // bulutlar: alan bükümlü fbm, gün batımında yassı katmanlar; güneşe bakan kenarlar aydınlanır
    float2 p = fc / H;
    float2 cp = p * float2(1.25, 4.6) + float2(iTime * 0.008, 0.0);
    float2 warp = float2(fbm(cp * 0.6 + float2(iTime * 0.012, 0.0)), fbm(cp * 0.6 + float2(5.2, 1.3)));
    float2 q = cp + warp * 1.1;
    float n = fbm(q);
    float band = smoothstep(0.04, 0.32, y) * (1.0 - smoothstep(0.78, 1.0, y));
    float dens = smoothstep(0.40, 0.74, n) * band;
    float2 toSun = normalize(sun - fc + float2(0.001, 0.001)) * 0.05;
    float n2 = fbm(q + toSun * float2(1.25, 4.6));
    float lit = clamp((n - n2) * 5.0 + 0.45, 0.0, 1.0);
    float near = exp(-r * 2.0);
    float3 cDark = mix(top, mid, 0.55) * 0.72;
    float3 cLit = mix(mid, sc, 0.5 + 0.45 * near);
    float3 cc = mix(cDark, cLit, lit * (0.3 + 0.7 * near));
    cc += sc * pow(lit, 3.0) * near * 0.55;
    col = mix(col, cc, dens * 0.88);
    // ışık huzmeleri: bulut boşluklarından aşağı yelpaze
    if (rays > 0.5) {
        float ang = atan(d.y, d.x);
        float rr = fbm(float2(ang * 7.0, iTime * 0.04));
        rr = smoothstep(0.48, 0.78, rr) * exp(-r * 1.5) * smoothstep(-0.05, 0.12, d.y);
        col += sc * rr * 0.24 * (1.0 - dens * 0.7);
    }
    // güneş diski ince bulutların ardında
    float disc = 1.0 - smoothstep(sunR * 0.92, sunR, length(fc - sun));
    col = mix(col, mix(sc, float3(1.0, 0.98, 0.92), 0.4), disc * (1.0 - dens * 0.75));
    col += flash * 0.2 * (1.0 - y * 0.5);
    col += (hash(fc + iTime) - 0.5) * (2.0 / 255.0);
    return half4(half3(col), 1.0);
}
"""

        private const val FIRE = """
uniform float2 origin;
uniform float2 dim;
uniform float iTime;
uniform float seed;
layout(color) uniform half4 tint;

half4 main(float2 fc) {
    float2 q = float2((fc.x - origin.x) / dim.x, (origin.y - fc.y) / dim.y);
    if (q.y < -0.2 || q.y > 1.1 || abs(q.x) > 1.3) return half4(0.0);
    float y = max(q.y, 0.0);
    float n = fbm(float2(q.x * 2.0 + seed, q.y * 2.4 - iTime * 2.3));
    float n2 = noise(float2(q.x * 5.5 - seed, q.y * 6.5 - iTime * 4.6));
    float sway = (n - 0.5) * 0.85 * y + sin(iTime * 1.7 + seed + y * 3.0) * 0.07 * y;
    float w = mix(0.95, 0.10, pow(y, 0.75));
    float d = abs(q.x - sway) / w;
    float heat = (1.0 - d) * 1.35 - y * 0.9 + (n2 - 0.5) * 0.7 * y + (n - 0.5) * 0.55;
    // üst kısım ayrık dillere kopar
    heat -= smoothstep(0.35, 1.0, y) * (1.0 - n2) * 0.55;
    heat *= smoothstep(-0.2, 0.06, q.y);
    heat = clamp(heat, 0.0, 1.0);
    float3 tc = float3(tint.rgb);
    // kara cisim rampası: koyu kızıl → tema rengi → beyaza yakın sarı çekirdek
    float3 c = tc * tc * 0.75 * smoothstep(0.0, 0.25, heat);
    c = mix(c, tc, smoothstep(0.2, 0.55, heat));
    c = mix(c, mix(tc, float3(1.0, 0.96, 0.82), 0.85), smoothstep(0.55, 0.92, heat));
    float a = smoothstep(0.02, 0.3, heat);
    return half4(half3(c * a), a);
}
"""

        private const val SMOKE = """
uniform float2 origin;
uniform float2 dim;
uniform float drift;
uniform float iTime;
uniform float seed;
layout(color) uniform half4 smokeCol;
layout(color) uniform half4 glowCol;

half4 main(float2 fc) {
    float2 q = float2((fc.x - origin.x) / dim.x, (origin.y - fc.y) / dim.y);
    if (q.y < 0.0 || q.y > 1.0) return half4(0.0);
    float y = q.y;
    float cx = drift * pow(y, 1.5) + sin(y * 4.0 + iTime * 0.3 + seed) * 0.12 * y;
    float w = 0.22 + y * 1.1;
    float dx = (q.x - cx) / w;
    float prof = exp(-dx * dx * 2.4);
    float n = fbm(float2(q.x * 0.9 + seed - iTime * 0.03, y * 2.6 - iTime * 0.2));
    float n2 = fbm(float2(q.x * 2.2 - seed, y * 5.5 - iTime * 0.34) + n * 1.5);
    float dens = prof * smoothstep(0.28, 0.72, n * 0.55 + n2 * 0.55);
    dens *= smoothstep(0.0, 0.07, y) * (1.0 - smoothstep(0.5, 1.0, y));
    dens = clamp(dens * 1.6, 0.0, 0.92);
    float3 c = mix(float3(glowCol.rgb), float3(smokeCol.rgb), smoothstep(0.0, 0.28, y));
    c *= 0.7 + 0.6 * n2;
    return half4(half3(c * dens), dens);
}
"""

        private const val FOG = """
uniform float2 band;
uniform float iH;
uniform float iTime;
uniform float seed;
uniform float strength;
layout(color) uniform half4 fogCol;

half4 main(float2 fc) {
    float v = (fc.y - band.x) / (band.y - band.x);
    if (v < 0.0 || v > 1.0) return half4(0.0);
    float prof = smoothstep(0.0, 0.55, v) * (1.0 - smoothstep(0.7, 1.0, v));
    float2 p = fc / iH;
    float n = fbm(float2(p.x * 1.6 + iTime * 0.025 + seed, p.y * 7.0 + seed));
    float n2 = fbm(float2(p.x * 3.4 - iTime * 0.04, p.y * 11.0 - seed));
    float a = prof * clamp(0.25 + n * 0.9 + (n2 - 0.5) * 0.5, 0.0, 1.0) * strength;
    return half4(half3(float3(fogCol.rgb) * a), a);
}
"""
    }
}

// ====================================================================================================
// com/zenvex/online/ui/Screens.kt
// ====================================================================================================

enum class Screen { Splash, Lobby, Settings, Loading, Game }

private val CRAFT_TAB_ICONS = listOf("tab_heal", "tab_potion", "tab_weapon", "tab_gear", "tab_jewel", "tab_material", "tab_vehicle", "tab_base")

fun JSONArray?.objs(): List<JSONObject> = if (this == null) emptyList() else List(length()) { optJSONObject(it) ?: JSONObject() }

// =========================================================================== açılış
@Composable
fun SplashScreen(done: () -> Unit) {
    val ctx = LocalContext.current
    val t = rememberTime()
    var progress by remember { mutableStateOf(0f) }
    LaunchedEffect(Unit) {
        // lobi görsellerini ve eşya simgelerini önceden çöz
        val keys = HERO_IDS.map { "l/$it/0_0" } + listOf("i/wood")
        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
            keys.forEachIndexed { i, k -> runCatching { SpriteCache.get(ctx, k) }; progress = (i + 1f) / keys.size }
        }
        delay(400)
        done()
    }
    EventBackdrop(dim = 0.12f) {
        Column(Modifier.align(Alignment.Center), horizontalAlignment = Alignment.CenterHorizontally) {
            CodeLogo(120.dp)
            Spacer(Modifier.height(18.dp))
            PxBar(progress, Px.Green, Modifier.width(320.dp), 14.dp)
            Spacer(Modifier.height(8.dp))
            PT("Dünya hazırlanıyor… %${(progress * 100).toInt()}", 15.sp, Px.Sub)
        }
    }
}

@Composable
fun Field(value: String, onChange: (String) -> Unit, hint: String, modifier: Modifier = Modifier, multiline: Boolean = false, onDone: (() -> Unit)? = null) {
    // siyah yarı saydam zemin, beyaz yazı, piksel kenar; çok satırlıda yükseklik çağıranda
    Box((if (multiline) modifier else modifier.height(44.dp)).clip(RoundedCornerShape(3.dp)).background(Color(0x99000000)).border(2.dp, Color(0xFF15140F), RoundedCornerShape(3.dp))
        .padding(2.dp).border(1.dp, Color(0x33FFFFFF), RoundedCornerShape(2.dp)).padding(horizontal = 10.dp, vertical = if (multiline) 6.dp else 0.dp),
        contentAlignment = if (multiline) Alignment.TopStart else Alignment.CenterStart) {
        if (value.isEmpty()) PT(hint, 14.sp, Color(0x99FFFFFF), maxLines = if (multiline) 3 else 1)
        BasicTextField(value, onChange, singleLine = !multiline, textStyle = TextStyle(color = Color.White, fontSize = 15.sp, fontFamily = PixelFont),
            cursorBrush = SolidColor(Color.White), modifier = Modifier.fillMaxWidth(),
            keyboardOptions = KeyboardOptions(imeAction = if (multiline) ImeAction.Default else ImeAction.Done), keyboardActions = KeyboardActions(onDone = { onDone?.invoke() }))
    }
}

val TIPS = listOf(
    "İpucu: Saldırı joystiğini çevirdiğin yöne vurursun; bırakınca durursun.",
    "İpucu: Seviye 10'da şehir kapısı açılır. Şehirdeki güvenli bölgede keskin nişancılar seni korur.",
    "İpucu: Toksik zombiler öldüklerinde zehir bulutu bırakır. Panzehir taşı!",
    "İpucu: Karanlık zombiler geceleri daha sık çıkar ve ışınlanır.",
    "İpucu: Çalışma tezgâhında kask, yelek, bot ve çanta üretebilirsin.",
    "İpucu: Araçlar yakıt harcar; çantadaki benzin otomatik kullanılır.",
)

@Composable
fun LoadingScreen(back: () -> Unit = {}, done: () -> Unit) {
    val ctx = LocalContext.current
    val t = rememberTime()
    var p by remember { mutableStateOf(0f) }
    var err by remember { mutableStateOf<String?>(null) }
    var attempt by remember { mutableIntStateOf(0) }
    val tip = remember { TIPS.random() }
    LaunchedEffect(attempt) {
        err = null; p = 0f
        // 1) sunucu oturumu: kayıt sunucudan gelir; bağlantı / bakım / yasak varsa oyuna girilmez
        // otomatik gösterim (yalnız hata ayıklama sürümü): oturumsuz, cihazdaki kayıtla
        val data = if (Demo.on) null else kotlinx.coroutines.suspendCancellableCoroutine<String?> { c ->
            com.zenvex.online.Session.start(ctx, GameSession.server.value.id) { d, e ->
                if (e != null) err = e
                if (c.isActive) c.resumeWith(Result.success(if (e == null) d.orEmpty() else null))
            }
        }
        if (!Demo.on) {
            if (data == null) return@LaunchedEffect
            GameSession.openFromServer(data)
            // V21: bağlantı kopmuşsa oyuncu kaldığı yerde değil başlangıç ormanında (kamp) doğar
            if (com.zenvex.online.Session.takeLost(ctx)) GameSession.cmd("to_camp")
        }
        p = 0.15f
        val ch = GameSession.ui("profile").optInt("character")
        val groups = listOf("world", "items", "gear", "vehicles", "npcs", "hero_${HERO_IDS[ch]}", "zombie_walker", "zombie_runner", "zombie_dog",
            "zombie_toxic", "zombie_dark", "zombie_tank", "zombie_mystery")
        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
            groups.forEachIndexed { i, g -> runCatching { Atlas.get(ctx).preload(g) }; p = 0.15f + 0.85f * (i + 1f) / groups.size }
        }
        Online.start(Account.name.value.ifEmpty { GameSession.ui("profile").optString("name") }, GameSession.ui("profile").optString("tag_name"))
        if (!Demo.on) com.zenvex.online.Events.onSessionStart()
        delay(200)
        done()
    }
    EventBackdrop(dim = 0.1f) {
        CodeLogo(100.dp, Modifier.align(Alignment.TopCenter).padding(top = 24.dp))
        Column(Modifier.align(Alignment.BottomCenter).padding(bottom = 40.dp), horizontalAlignment = Alignment.CenterHorizontally) {
            PT(GameSession.server.value.title, 26.sp, Px.Clan, outline = true)
            Spacer(Modifier.height(10.dp))
            val e = err
            if (e != null) {
                PT(e, 17.sp, Color(0xFFFF7A6A), maxLines = 2, align = TextAlign.Center)
                Spacer(Modifier.height(10.dp))
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    PxButton("Tekrar Dene", height = 44.dp, size = 16.sp, icon = "refresh") { attempt++ }
                    PxButton("Lobiye Dön", color = Px.Dark, height = 44.dp, size = 16.sp) { back() }
                }
            } else {
                PT(if (p < 0.15f) "Sunucuya Bağlanılıyor…" else "Dünya Yükleniyor…", 15.sp, Px.Sub)
                Spacer(Modifier.height(6.dp))
                PxBar(p, Px.Green, Modifier.width(420.dp), 14.dp)
            }
            Spacer(Modifier.height(10.dp))
            PT(tip, 14.sp, Px.Text, align = TextAlign.Center, maxLines = 2)
        }
    }
}


@Composable
fun ItemDetail(item: JSONObject) {
    val r = item.optInt("rarity")
    Row(verticalAlignment = Alignment.CenterVertically) {
        ItemSlot(item.optString("id"), 0, r, 74.dp)
        Spacer(Modifier.width(10.dp))
        Column {
            T(item.optString("name"), 16.sp, Pal.rarity(r), bold = true)
            T("${RARITY_NAMES.getOrElse(r) { "" }} · ${KIND_NAMES[item.optString("kind")] ?: ""}", 11.sp, Pal.Sub)
            if (item.optInt("count") > 1) T("Adet: ${item.optInt("count")}", 11.sp, Pal.Sub)
        }
    }
    Spacer(Modifier.height(8.dp))
    T(item.optString("desc"), 12.sp, Pal.Text)
    if (item.optDouble("armor", 0.0) > 0) T("Zırh +${item.optDouble("armor").toInt()}", 12.sp, Pal.Blue, bold = true)
    T("Değer: ${item.optInt("value")} altın", 11.sp, Pal.Gold)
}


// =========================================================================== üretim
/**
 * Üretim: üstte sekmeler (Şifa, İksir, Silah Ve Alet, Ekipman, Takı, Malzeme, Araç, Üs), solda sekmenin tarifleri
 * (aynı eşyanın farklı tarifleri tek satırda), sağda seçili eşya: Üret tuşları en üstte (kaydırmadan görünür),
 * altında malzemeler ve her malzemenin nereden çıktığı.
 *
 * V12.1: iki ayrı ekran. [bench] false → El Üretimi (çanta ve HUD'dan; yalnız elle yapılan tarifler), true → Tezgâh
 * (tezgâha dokununca; yalnız tezgâh tarifleri). Bir ekrandaki tarif diğerinde görünmez; boş sekmeler gizlenir.
 */
@Composable
fun CraftScreen(back: () -> Unit, bench: Boolean = false) {
    var tick by remember { mutableIntStateOf(0) }
    // V21: görev malzeme verince (ya da dışarıdan değişince) ekran kapanıp açılmadan güncellensin: 700 ms'de bir yenilenir
    var qtick by remember { mutableIntStateOf(0) }
    LaunchedEffect(Unit) { while (true) { delay(700); qtick++ } }
    val data = remember(tick, qtick) { GameSession.ui(if (bench) "craft_bench" else "craft") }
    val all = data.optJSONArray("recipes").objs()
    val tabNames = data.optJSONArray("tabs")?.let { a -> List(a.length()) { a.optString(it) } } ?: emptyList()
    // yalnız tarif olan sekmeler (sekme numarası korunur)
    val tabs = tabNames.withIndex().filter { (i, _) -> all.any { it.optInt("tab") == i } }
    var tab by remember { mutableIntStateOf(tabs.firstOrNull()?.index ?: 0) }
    var onlyCan by remember { mutableStateOf(false) }
    var selId by remember { mutableStateOf<String?>(null) }
    var variant by remember { mutableIntStateOf(0) }
    val list = all.filter { it.optInt("tab") == tab && (!onlyCan || it.optBoolean("can")) }
    val r = list.firstOrNull { it.optJSONObject("out")?.optString("id") == selId } ?: list.firstOrNull()
    val near = data.optBoolean("near_bench")

    // öğretici: hangi sekme, hangi tarif, hangi düğme (adıma göre)
    val tutR = remember { androidx.compose.runtime.mutableStateMapOf<String, androidx.compose.ui.geometry.Rect>() }
    // V19: rehber ve ana görevlerin bütün üretim adımları (Silas'ın motosiklet parçaları dahil): sekme tarifin kendisinden
    // görev değişince (teslim, yeni görev) ekran kapanıp açılmadan güncellensin
    val craftWant = remember(tick, qtick) { Tut.craftWant() }
    val tutWant: Pair<Int, String>? = craftWant?.let { (id, _) ->
        all.firstOrNull { it.optJSONObject("out")?.optString("id") == id }?.let { it.optInt("tab") to id }
    }
    // istenen tarif bu ekranda değil (el ↔ tezgâh): nereye gidileceği söylenir
    val wrongPlace = craftWant != null && tutWant == null

    fun craft(v: JSONObject, n: Int) {
        val res = GameSession.cmd("craft", "i" to v.optInt("i"), "n" to n)
        Toaster.show(res.msg, res.ok); tick++
        if (res.ok) com.zenvex.online.Audio.play("craft")
    }

    Box(Modifier.fillMaxSize()) {
    PxFrame(if (bench) "Tezgâh" else "El Üretimi", "craft", back, right = {
        PxButton(if (onlyCan) "Yapılabilenler" else "Hepsi", height = 36.dp, size = 12.sp, color = if (onlyCan) Px.Green else Px.Dark, icon = "check") {
            onlyCan = !onlyCan
        }
        Spacer(Modifier.width(8.dp))
        if (bench) {
            val left = data.optDouble("temp_left", -1.0)
            when {
                // üsteki kalıcı tezgâh çantaya geri alınabilir
                data.optBoolean("own_bench") -> PxButton("Tezgâhı Kaldır", height = 36.dp, size = 12.sp, color = Px.Red, icon = "hammer") {
                    val res = GameSession.cmd("pickup_bench"); Toaster.show(res.msg, res.ok); if (res.ok) back()
                }
                left > 0 -> PT("Tezgâh ${(left / 60).toInt()}:${"%02d".format((left % 60).toInt())} Daha Durur", 13.sp, Px.Clan)
                !near -> PT("Tezgâhtan Uzaklaştın", 13.sp, Px.Hard)
            }
        } else PT("Gelişmiş Tarifler Tezgâhta", 13.sp, Px.Sub)
    }, bg = "bg_craft") {
        // sekmeler (her sekmede yapılabilir tarif sayısı)
        Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            tabs.forEach { (i, name) ->
                val ready = all.count { it.optInt("tab") == i && it.optBoolean("can") }
                val on = i == tab
                Row(Modifier.tutRect(tutR, "tab$i").height(36.dp).clip(RoundedCornerShape(3.dp)).background(if (on) Color(0xE6524428) else Color(0xCC23221D))
                    .border(2.dp, if (on) Px.Clan else Px.Edge, RoundedCornerShape(3.dp))
                    .clickable { com.zenvex.online.Audio.play("click", bus = com.zenvex.online.Audio.Bus.Ui); tab = i; selId = null; variant = 0 }
                    .padding(horizontal = 10.dp), verticalAlignment = Alignment.CenterVertically) {
                    // V13 sekme simgeleri (Rust sekme sırası: şifa, iksir, silah, ekipman, takı, malzeme, araç, üs)
                    CRAFT_TAB_ICONS.getOrNull(i)?.let {
                        ArtImage(it, Modifier.size(24.dp).alpha(if (on) 1f else 0.6f)); Spacer(Modifier.width(6.dp))
                    }
                    PT(name, 13.sp, if (on) Px.Text else Px.Sub)
                    if (ready > 0) { Spacer(Modifier.width(6.dp)); PT("$ready", 11.sp, Px.Green) }
                }
            }
        }
        Spacer(Modifier.height(6.dp))
        Row(Modifier.fillMaxSize(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            PxPanel(Modifier.weight(1f).fillMaxHeight(), color = Color(0xB4201F1C), pad = 6.dp) {
                if (list.isEmpty()) PT(if (onlyCan) "Bu Sekmede Şu An Yapabileceğin Bir Şey Yok" else "Tarif Yok", 13.sp, Px.Sub)
                val listState = androidx.compose.foundation.lazy.rememberLazyListState()
                // öğretici: istenen tarif listede görünmüyorsa oraya kaydır (görünmeyen satır işaretlenemez)
                val wantIdx = tutWant?.takeIf { it.first == tab }?.let { w -> list.indexOfFirst { it.optJSONObject("out")?.optString("id") == w.second } } ?: -1
                LaunchedEffect(wantIdx, tab) { if (wantIdx >= 0) listState.animateScrollToItem(wantIdx) }
                LazyColumn(Modifier.fillMaxSize(), listState, verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    items(list.size) { k ->
                        val g = list[k]
                        val out = g.optJSONObject("out") ?: JSONObject()
                        val on = g === r
                        Row(Modifier.tutRect(tutR, "rec:" + out.optString("id")).fillMaxWidth().clip(RoundedCornerShape(3.dp)).background(if (on) Color(0x80524428) else Color(0x40000000))
                            .clickable { selId = out.optString("id"); variant = 0 }.padding(5.dp), verticalAlignment = Alignment.CenterVertically) {
                            PxSlot(out, 42.dp)
                            Spacer(Modifier.width(8.dp))
                            Column(Modifier.weight(1f)) {
                                PT(out.optString("name"), 14.sp, Pal.rarity(out.optInt("rarity")))
                                val vs = g.optJSONArray("variants").objs()
                                PT(when {
                                    vs.size > 1 -> "${vs.size} Farklı Tarif"
                                    bench -> "Tezgâhta"
                                    else -> "Her Yerde"
                                } + if (g.optInt("have") > 0) " · Çantada ${g.optInt("have")}" else "", 11.sp, Px.Sub)
                            }
                            if (g.optBoolean("can")) Icon("check", 20.dp, Px.Green)
                        }
                    }
                }
            }
            PxPanel(Modifier.width(340.dp).fillMaxHeight(), color = Color(0xC0201F1C), pad = 8.dp) {
                if (r != null) {
                    val out = r.optJSONObject("out") ?: JSONObject()
                    val vs = r.optJSONArray("variants").objs()
                    val v = vs.getOrNull(variant) ?: vs.firstOrNull() ?: JSONObject()
                    val can = v.optBoolean("can")
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        PxSlot(out, 52.dp)
                        Spacer(Modifier.width(8.dp))
                        Column(Modifier.weight(1f)) {
                            PT(out.optString("name"), 15.sp, Pal.rarity(out.optInt("rarity")))
                            PT("${RARITY_NAMES.getOrElse(out.optInt("rarity")) { "" }} · ×${v.optInt("count", 1)} · Çantada ${r.optInt("have")}", 11.sp, Px.Sub)
                        }
                    }
                    Spacer(Modifier.height(6.dp))
                    // tuşlar her zaman görünür (malzeme listesi uzasa da kaydırma gerekmez)
                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        PxButton("Üret", Modifier.weight(1f).tutRect(tutR, "make"), color = Px.Green, icon = "craft", height = 40.dp, size = 14.sp, enabled = can) { craft(v, 1) }
                        // çoklu üretim: her biri ayrı sayılır (görev, sezon bileti, sıralama); malzeme yetmeyen tuş kapalı
                        val max = v.optInt("max", if (can) 1 else 0)
                        for (n in listOf(5, 10, 25, 50)) {
                            PxButton("×$n", Modifier.width(46.dp), color = Px.Blue, height = 40.dp, size = 12.sp, enabled = can && max >= n) { craft(v, n) }
                        }
                    }
                    if (!can) {
                        Spacer(Modifier.height(4.dp))
                        PT(if (v.optBoolean("bench") && !near) "Tezgâhın Yanına Dön" else "Malzemeler Eksik", 12.sp, Px.Hard)
                    }
                    if (vs.size > 1) {
                        Spacer(Modifier.height(6.dp))
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            vs.forEachIndexed { i, o ->
                                val on = i == variant
                                Box(Modifier.height(28.dp).clip(RoundedCornerShape(3.dp)).background(if (on) Color(0xE6524428) else Color(0xCC23221D))
                                    .border(1.dp, if (o.optBoolean("can")) Px.Green else Px.Edge, RoundedCornerShape(3.dp))
                                    .clickable { variant = i }.padding(horizontal = 10.dp), contentAlignment = Alignment.Center) {
                                    PT("Tarif ${i + 1}", 12.sp, if (on) Px.Text else Px.Sub)
                                }
                            }
                        }
                    }
                    Spacer(Modifier.height(6.dp))
                    PT("Malzemeler", 13.sp, Px.Clan)
                    Column(Modifier.weight(1f).verticalScroll(rememberScrollState())) {
                        for (inp in v.optJSONArray("inputs").objs()) {
                            val ok = inp.optInt("have") >= inp.optInt("need")
                            Row(Modifier.fillMaxWidth().padding(vertical = 3.dp), verticalAlignment = Alignment.CenterVertically) {
                                ItemSlot(inp.optString("id"), 0, 0, 34.dp)
                                Spacer(Modifier.width(6.dp))
                                Column(Modifier.weight(1f)) {
                                    PT(inp.optString("name"), 13.sp)
                                    PT(inp.optString("src"), 10.sp, Px.Sub, maxLines = 2)
                                }
                                PT("${inp.optInt("have")}/${inp.optInt("need")}", 13.sp, if (ok) Px.Green else Px.Hard)
                            }
                        }
                        Spacer(Modifier.height(6.dp))
                        PT(out.optString("desc"), 11.sp, Px.Sub, maxLines = 5)
                    }
                }
            }
        }
    }
    if (wrongPlace) TutLayer(emptyList(), if (craftWant.second) "Görevin istediği eşya tezgâhta yapılır: bu ekranı kapat, haritada işaretli tezgâha git ve ona dokun."
        else "Görevin istediği eşya el üretiminde: bu ekranı kapat, çantadaki Üret düğmesine bas.", cardStart = 200, cardEnd = 280)
    // öğretici: sekme → tarif → Üret düğmesi sırasıyla parlar
    if (tutWant != null) {
        val (wantTab, wantId) = tutWant
        val tg = ArrayList<TutTarget>()
        val text: String
        val shown = r?.optJSONObject("out")?.optString("id")
        when {
            tab != wantTab -> {
                tg += TutTarget(tutR["tab$wantTab"], "Önce Bu Sekme", below = true)
                text = when (wantTab) {
                    0 -> "Üstteki parlayan Şifa sekmesine dokun: tarifler sekmelere ayrılmıştır, bandaj Şifa'dadır."
                    2 -> "Üstteki parlayan Silah Ve Alet sekmesine dokun: tarifler sekmelere ayrılmıştır, alet ve silahlar burada."
                    else -> "Üstteki parlayan sekmeye dokun: tarifler sekmelere ayrılmıştır, görevin istediği tarif o sekmede."
                }
            }
            shown != wantId -> {
                tg += TutTarget(tutR["rec:$wantId"], "Bunu Seç")
                text = "Soldaki listeden parlayan tarife dokun: sağda malzemeler ve Üret düğmesi açılır."
            }
            else -> {
                tg += TutTarget(tutR["make"], "Üret'e Bas", below = true)
                text = "Malzemeler yeşilse Üret'e bas. Altta her malzemenin nereden çıktığı yazar. ×5, ×10 çoklu üretimdir."
            }
        }
        TutLayer(tg, text, cardStart = 200, cardEnd = 280)
    }
    }
}

// =========================================================================== gezgin tüccar
/**
 * Gezgin Tüccar Marco: Satın Al (bu gelişin malları), Sat (miktar seçerek), Olasılıklar (tüm mallar tek ekranda).
 * V15: tüccarda elmas yok; gerçek para ürünleri Mağaza'da ([openStore]).
 */
@Composable
fun MerchantScreen(back: () -> Unit, openStore: () -> Unit) {
    var tick by remember { mutableIntStateOf(0) }
    var tab by remember { mutableIntStateOf(0) }
    var ask by remember { mutableStateOf<AmountAsk?>(null) }
    val data = remember(tick) { GameSession.ui("merchant") }
    // öğretici "Eşya Sat": Sat sekmesi ve satış düğmesi işaretlenir (görev değişince ekran da güncellensin)
    var qtick by remember { mutableIntStateOf(0) }
    LaunchedEffect(Unit) { while (true) { delay(700); qtick++ } }
    val tutSell = remember(tick, qtick) { Tut.step() == "g6s" }
    MerchantView(data, tab, { tab = it }, back, openStore, tutSell = tutSell,
        buy = { o -> val r = GameSession.cmd("buy", "i" to o.optInt("i"), "n" to 1); Toaster.show(r.msg, r.ok); tick++; if (r.ok) com.zenvex.online.Audio.play("coin") },
        sell = { o ->
            val n = o.optInt("count")
            val name = o.optJSONObject("item")?.optString("name") ?: ""
            if (n > 1) ask = AmountAsk("sell", o.optInt("slot"), n, n, "$name Sat · Tanesi ${o.optInt("price")} Altın")
            else { val r = GameSession.cmd("sell", "slot" to o.optInt("slot"), "n" to 1); Toaster.show(r.msg, r.ok); tick++ }
        })
    ask?.let { a ->
        AmountDialog(a, { ask = null }) { k ->
            val r = GameSession.cmd("sell", "slot" to a.slot, "n" to k); Toaster.show(r.msg, r.ok)
            if (r.ok) com.zenvex.online.Audio.play("coin")
            ask = null; tick++
        }
    }
}

@Composable
internal fun MerchantView(data: JSONObject, tab: Int, setTab: (Int) -> Unit, back: () -> Unit, openStore: () -> Unit,
                          buy: (JSONObject) -> Unit, sell: (JSONObject) -> Unit, tutSell: Boolean = false) {
    val tutR = remember { androidx.compose.runtime.mutableStateMapOf<String, androidx.compose.ui.geometry.Rect>() }
    // satış öğreticisinde işaretlenecek eşya: önce kumaş (görev çantaya koyar), yoksa ilk satılabilir eşya
    val sellList = data.optJSONArray("sell").objs()
    val tutItem = if (!tutSell) null else (sellList.firstOrNull { it.optJSONObject("item")?.optString("id") == "cloth" } ?: sellList.firstOrNull())
    Box(Modifier.fillMaxSize()) {
    ScreenFrame("GEZGİN TÜCCAR MARCO", "shop", back, right = {
        Chip("coin", fmt(data.optInt("gold")), Pal.Gold); Spacer(Modifier.width(8.dp))
        GButton("Mağaza", tone = Tone.Blue, icon = "crate", height = 34.dp, size = 12.sp) { openStore() }
    }) {
        Tabs(listOf("shop" to "Satın Al", "coin" to "Sat", "star" to "Olasılıklar"), tab, rects = tutR) { setTab(it) }
        Spacer(Modifier.height(10.dp))
        val next = data.optDouble("next").toInt()
        when (tab) {
            0 -> Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState())) {
                // V12.2 gezgin tüccar: bu gelişin malları (gelme olasılığı, stok), süre
                T("Marco her gelişinde başka mallar getirir; herkes aynı malları görür. " +
                    "${next / 60}:${"%02d".format(next % 60)} sonra kamyonetiyle başka bir karakola gider.", 13.sp, Pal.Sub)
                Spacer(Modifier.height(8.dp))
                @OptIn(ExperimentalLayoutApi::class)
                FlowRow(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    for (o in data.optJSONArray("buy").objs()) {
                        val it = o.optJSONObject("item") ?: JSONObject()
                        val locked = o.optBoolean("locked")
                        val left = o.optInt("left")
                        Column(Modifier.width(150.dp).glass(16.dp, Pal.rarity(it.optInt("rarity"))).padding(10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                            ItemSlot(it.optString("id"), 0, it.optInt("rarity"), 70.dp)
                            T(it.optString("name"), 13.sp, Pal.rarity(it.optInt("rarity")), bold = true, maxLines = 1)
                            T("Gelme Olasılığı %${o.optInt("chance")}", 11.sp, Pal.Sub, maxLines = 1)
                            T("Stok $left", 11.sp, if (left > 0) Pal.Gold else Pal.Sub, maxLines = 1)
                            Spacer(Modifier.height(6.dp))
                            if (locked) GButton("Sv ${o.optInt("req")}", Modifier.fillMaxWidth(), Tone.Dark, icon = "lock", height = 34.dp, size = 12.sp) {}
                            else if (left == 0) GButton("Tükendi", Modifier.fillMaxWidth(), Tone.Dark, height = 34.dp, size = 12.sp) {}
                            else GButton("${o.optInt("price")}", Modifier.fillMaxWidth(), if (o.optBoolean("afford")) Tone.Gold else Tone.Dark, icon = "coin", height = 34.dp, size = 13.sp) {
                                buy(o)
                            }
                        }
                    }
                }
            }
            1 -> Column(Modifier.fillMaxSize()) {
                T("Dokun, kaç tane satacağını seç. Satış fiyatı eşyanın değerinin %${(35 + data.optDouble("bonus") * 100).toInt()}'i.", 12.sp, Pal.Sub)
                Spacer(Modifier.height(6.dp))
                @OptIn(ExperimentalLayoutApi::class)
                FlowRow(Modifier.fillMaxSize().verticalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    val list = data.optJSONArray("sell").objs()
                    if (list.isEmpty()) T("Satacak eşyan yok.", 14.sp, Pal.Sub)
                    for (o in list) {
                        val it = o.optJSONObject("item") ?: JSONObject()
                        val n = o.optInt("count")
                        Column(Modifier.width(150.dp).glass(16.dp).padding(10.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                            ItemSlot(it.optString("id"), n, it.optInt("rarity"), 70.dp)
                            T(it.optString("name"), 13.sp, bold = true, maxLines = 1)
                            T(if (n > 1) "Hepsi: ${fmt(o.optInt("price") * n)}" else " ", 11.sp, Pal.Sub, maxLines = 1)
                            Spacer(Modifier.height(4.dp))
                            GButton("+${o.optInt("price")}", Modifier.fillMaxWidth().then(if (o === tutItem) Modifier.tutRect(tutR, "sell") else Modifier),
                                Tone.Green, icon = "coin", height = 34.dp, size = 13.sp, sub = "tanesi") { sell(o) }
                        }
                    }
                }
            }
            // tüm mallar tek ekranda: getirdikleri yeşil çerçeveli, olasılığa göre sıralı
            else -> Column(Modifier.fillMaxSize()) {
                T("Marco'nun her gelişte getirebileceği mallar ve gelme olasılıkları. Yeşil olanlar şu an tezgâhında.", 12.sp, Pal.Sub)
                Spacer(Modifier.height(6.dp))
                val here = data.optJSONArray("buy").objs().map { it to true }
                val away = data.optJSONArray("missing").objs().map { it to false }
                val all = (here + away).sortedByDescending { it.first.optInt("chance") }
                // sütun sayısı mal sayısına göre: en çok 7 sıra, kaydırma yok
                val cols = ((all.size + 6) / 7).coerceIn(4, 6)
                @OptIn(ExperimentalLayoutApi::class)
                FlowRow(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(5.dp), verticalArrangement = Arrangement.spacedBy(4.dp), maxItemsInEachRow = cols) {
                    for ((o, on) in all) {
                        val it = o.optJSONObject("item") ?: JSONObject()
                        Row(Modifier.weight(1f).height(29.dp).glass(8.dp, if (on) Pal.Green else null).padding(horizontal = 5.dp),
                            verticalAlignment = Alignment.CenterVertically) {
                            ItemSlot(it.optString("id"), 0, it.optInt("rarity"), 22.dp)
                            Spacer(Modifier.width(5.dp))
                            T(it.optString("name"), 11.sp, Pal.rarity(it.optInt("rarity")), maxLines = 1, modifier = Modifier.weight(1f))
                            T("%${o.optInt("chance")}", 12.sp, if (on) Pal.Green else Pal.Gold, bold = true)
                        }
                    }
                    // son sıra boş hücrelerle tamamlanır (tek kalan mal tüm satıra yayılmaz)
                    repeat((cols - all.size % cols) % cols) { Spacer(Modifier.weight(1f)) }
                }
            }
        }
    }
    if (tutSell) {
        when {
            tab != 1 -> TutLayer(listOf(TutTarget(tutR["tab1"], "Sat'a Dokun", below = true)),
                "Üstteki parlayan Sat sekmesine dokun: çantandaki satılabilir eşyalar orada.", cardStart = 380, cardEnd = 200)
            tutItem == null -> TutLayer(emptyList(), "Satacak eşyan yok. Biraz malzeme topla ya da görevin verdiği kumaşı bekle.", cardStart = 380, cardEnd = 200)
            else -> TutLayer(listOf(TutTarget(tutR["sell"], "Sat'a Bas", below = true)),
                "Parlayan eşyanın altın düğmesine bas; birden fazlaysa kaç tane satacağını seçersin.", cardStart = 380, cardEnd = 200)
        }
    }
    }
}

// =========================================================================== görevler
@Composable
fun QuestsScreen(back: () -> Unit) {
    val q = remember { GameSession.ui("quests") }
    QuestsView(q, back)
}

@Composable
internal fun QuestsView(q: JSONObject, back: () -> Unit) {
    // yenilenme sayacı sunucu saatiyle (Türkiye gece yarısı / Pazartesi)
    var now by remember { mutableLongStateOf(com.zenvex.online.Pass.now()) }
    LaunchedEffect(Unit) { while (true) { delay(1000); now = com.zenvex.online.Pass.now() } }
    PxFrame("Görevler", "quest", back) {
        Row(Modifier.fillMaxSize(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            PxPanel(Modifier.weight(1.2f).fillMaxHeight(), pad = 10.dp) {
                PT("Hikâye", 16.sp, Px.Clan)
                Spacer(Modifier.height(6.dp))
                val st = q.optJSONArray("story").objs()
                if (st.isEmpty()) PT("Tüm Görevleri Tamamladın. Efsanesin!", 15.sp, Px.Name)
                for (m in st) {
                    val on = m.optBoolean("on"); val ready = m.optBoolean("ready")
                    Column(Modifier.fillMaxWidth().padding(bottom = 8.dp).pxPanel(Px.PanelDark).padding(10.dp)) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Box(Modifier.size(18.dp).background(if (m.optBoolean("guide")) Px.Blue else Color(0xFFB08A2A)), contentAlignment = Alignment.Center) {
                                PT(if (ready) "?" else "!", 13.sp)
                            }
                            Spacer(Modifier.width(8.dp))
                            PT(m.optString("title"), 17.sp, if (ready) Px.Clan else Px.Text, Modifier.weight(1f))
                            PT(if (m.optBoolean("guide")) "Rehber" else "Görevci", 12.sp, Px.Sub)
                        }
                        Spacer(Modifier.height(4.dp))
                        val txt = when {
                            ready -> "Tamamlandı! ${m.optString("giver")} İle Konuşup Teslim Et."
                            on -> m.optString("hint")
                            m.has("x") -> "${m.optString("giver")} İle Konuşarak Görevi Al."
                            else -> "${m.optInt("min_level")}. Seviyede Açılır."
                        }
                        PT(txt, 13.sp, if (ready) Px.Name else Px.Sub, maxLines = 2)
                        if (on) {
                            Spacer(Modifier.height(5.dp))
                            PxBar(m.optInt("n") / m.optInt("goal", 1).toFloat(), if (ready) Px.GreenHi else Px.Orange, Modifier.fillMaxWidth(), 12.dp)
                            PT("${m.optInt("n")} / ${m.optInt("goal")}", 12.sp, Px.Sub)
                        }
                    }
                }
            }
            PxPanel(Modifier.weight(1f).fillMaxHeight(), pad = 10.dp) {
                Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState())) {
                    for ((key, title, reset) in listOf(Triple("daily", "Günlük Görevler", nextDay(now)), Triple("weekly", "Haftalık Görevler", nextWeek(now)))) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            PT(title, 16.sp, Px.Clan, Modifier.weight(1f))
                            Icon("calendar", 14.dp, Px.Orange)
                            Spacer(Modifier.width(4.dp))
                            PT("Yenilenmeye ${fmtLeft(reset - now)}", 12.sp, Px.Orange)
                        }
                        PT("Sezon Bileti XP'si Verir", 11.sp, Px.Sub)
                        Spacer(Modifier.height(6.dp))
                        for (d in q.optJSONArray(key).objs()) {
                            val done = d.optBoolean("done")
                            Column(Modifier.fillMaxWidth().padding(bottom = 6.dp).pxPanel(if (done) Color(0xF0243A20) else Px.PanelDark).padding(8.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    PT(d.optString("title"), 14.sp, if (done) Px.Name else Px.Text, Modifier.weight(1f))
                                    if (done) Icon("check", 18.dp, Px.Name)
                                }
                                PxBar(d.optInt("progress") / d.optInt("goal", 1).toFloat(), if (done) Px.GreenHi else Px.Blue, Modifier.fillMaxWidth().padding(vertical = 3.dp), 9.dp)
                                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                    PT("${fmt(d.optInt("progress"))}/${fmt(d.optInt("goal"))}", 11.sp, Px.Sub)
                                    PT("+${fmt(d.optInt("gold"))} Altın", 11.sp, Px.Clan)
                                    PT("+${fmt(d.optInt("xp"))} XP", 11.sp, Px.Level)
                                    PT("+${fmt(d.optInt("pass_xp"))} Bilet XP", 11.sp, Px.Orange)
                                }
                            }
                        }
                        Spacer(Modifier.height(6.dp))
                    }
                }
            }
        }
    }
}

// =========================================================================== sohbet
@Composable
fun ChatPanel(modifier: Modifier = Modifier, onClose: () -> Unit, onPlayer: ((uid: String, name: String) -> Unit)? = null) {
    var tab by remember { mutableIntStateOf(0) }
    var msg by remember { mutableStateOf("") }
    // oyuncu menüsü yoksa (lobi) adına dokununca doğrudan profil açılır
    var profileOf by remember { mutableStateOf<String?>(null) }
    val channels = listOf("global", "clan", "dm", "system")
    val lines = Online.chat.filter { it.channel == channels[tab] }
    val state = rememberLazyListState()
    LaunchedEffect(lines.size) { if (lines.isNotEmpty()) state.animateScrollToItem(lines.size - 1) }
    Column(modifier.pxPanel(Color(0x9C141310)).padding(10.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            listOf("Genel", "Klan", "Özel", "Sistem").forEachIndexed { i, n ->
                Box(Modifier.background(if (i == tab) Px.Panel else Px.PanelDark).clickable { tab = i }.padding(horizontal = 9.dp, vertical = 6.dp)) {
                    PT(n, 14.sp, if (i == tab) Px.Text else Px.Sub)
                }
            }
            Spacer(Modifier.weight(1f))
            Box(Modifier.size(9.dp).clip(CircleShape).background(if (Online.online.value) Px.Name else Px.Sub))
            Spacer(Modifier.width(8.dp))
            PxIcon("close", size = 34.dp) { onClose() }
        }
        Spacer(Modifier.height(8.dp))
        if (channels[tab] == "dm") { FriendsPanel(Modifier.weight(1f).fillMaxWidth()); return@Column }
        LazyColumn(Modifier.weight(1f).fillMaxWidth(), state) {
            items(lines) { l ->
                val who = l.uid.takeIf { !l.mine && l.channel != "system" && it.isNotEmpty() }
                Row(Modifier.padding(vertical = 2.dp).then(if (who != null) Modifier.clickable {
                    if (onPlayer != null) onPlayer(who, l.name) else profileOf = l.name
                } else Modifier), verticalAlignment = Alignment.CenterVertically) {
                    // gönderenin resmi ve çerçevesi (animasyonlu); sistem satırlarında yok
                    if (l.channel != "system" && l.avatar >= 0) { ProfileAvatar(l.avatar, l.frame, 30.dp, account = if (l.mine) Account.id.value else l.uid.removePrefix("a").toLongOrNull() ?: -1); Spacer(Modifier.width(5.dp)) }
                    if (l.tag.isNotEmpty() && l.channel != "clan") PT("[${l.tag}] ", 13.sp, Px.Clan)
                    PT(l.name + ": ", 13.sp, if (l.mine) Px.Name else if (l.channel == "system") Px.Orange else Color(0xFF8CC8FF))
                    PT(l.text, 14.sp, maxLines = 6, outline = true)
                }
            }
        }
        val needClan = channels[tab] == "clan" && Account.clan.value == null
        if (tab != 3 && (Online.chatLocked() || needClan)) {
            Row(Modifier.fillMaxWidth().pxPanel(Px.PanelDark).padding(10.dp), verticalAlignment = Alignment.CenterVertically) {
                Icon("lock", 18.dp, Px.Sub)
                Spacer(Modifier.width(8.dp))
                PT(if (needClan) "Klan Sohbeti İçin Bir Klana Katıl" else "Sohbet ${Online.CHAT_LEVEL}. Seviyede Açılır", 14.sp, Px.Sub)
            }
        } else if (tab != 3) Row(verticalAlignment = Alignment.CenterVertically) {
            var wait by remember { mutableLongStateOf(0L) }
            LaunchedEffect(wait) { if (wait > 0) { delay(200); wait = Online.chatWait() } }
            fun go() {
                val err = Online.send(channels[tab], msg)
                if (err == null) { msg = ""; Tut.ping("chat") } else Toaster.show(err, false)
                wait = Online.chatWait()
            }
            Field(msg, { if (it.length <= 140) msg = it }, if (tab == 0) "Herkese Yaz…" else "Klanına Yaz…", Modifier.weight(1f)) { go() }
            Spacer(Modifier.width(8.dp))
            if (wait > 0) Box(Modifier.size(44.dp).pxPanel(Px.PanelDark), contentAlignment = Alignment.Center) { PT("${(wait + 999) / 1000}", 16.sp, Px.Sub) }
            else PxButton("", height = 44.dp, icon = "play", color = Px.Blue) { go() }
        }
    }
    profileOf?.let { PlayerProfileDialog(it) { profileOf = null } }
}


// =========================================================================== takas
/**
 * Takas: solda çanta (dokun → teklife ekle), sağda iki teklif. Tekil ekipman dayanıklılığıyla gider (çubuk görünür).
 * Güvenlik: karşı teklif değişince Onayla 3 sn kilitlenir; sen hazırken karşı taraf teklifini değiştirirse sunucu takası
 * bitirmez, ekranda uyarı çıkar (iptal edip yeniden başlat).
 */
@Composable
fun TradeScreen(close: () -> Unit) {
    val st = Online.trade.value
    var tick by remember { mutableIntStateOf(0) }
    val inv = remember(tick) { GameSession.ui("inventory") }
    val offer = remember { androidx.compose.runtime.mutableStateListOf<Online.TradeItem>() }
    var gold by remember { mutableStateOf("") }
    var now by remember { mutableLongStateOf(System.currentTimeMillis()) }
    LaunchedEffect(Unit) { while (true) { now = System.currentTimeMillis(); delay(250) } }
    fun push() {
        val g = gold.toIntOrNull() ?: 0
        Online.setTradeItems(offer.toList() + if (g > 0) listOf(Online.TradeItem("coin", g)) else emptyList())
    }
    ScreenFrame("TAKAS", "trade", { Online.cancelTrade(); close() }) {
        if (st == null) {
            T("Karşı tarafın kabul etmesi bekleniyor…", 15.sp, Pal.Sub)
            return@ScreenFrame
        }
        if (st.done) { T("Takas tamamlandı!", 18.sp, Pal.Green, bold = true); LaunchedEffect(Unit) { delay(1200); close() }; return@ScreenFrame }
        Row(Modifier.fillMaxSize(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            // çanta
            Column(Modifier.weight(1f).fillMaxHeight().glass(20.dp).padding(10.dp)) {
                SectionTitle(if (st.myOk) "Teklifin kilitli" else "Çantan (eklemek için dokun)")
                @OptIn(ExperimentalLayoutApi::class)
                FlowRow(Modifier.verticalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    val slots = inv.optJSONArray("slots")
                    for (i in 0 until (slots?.length() ?: 0)) {
                        val s = slots!!.optJSONObject(i) ?: continue
                        val id = s.optString("id")
                        if (id.startsWith("ev_")) continue  // hesaba bağlı etkinlik ödülleri takas edilemez
                        val have = s.optInt("count")
                        val single = s.has("dur")
                        val used = if (single) offer.count { it.slot == i } else offer.filter { it.id == id && it.slot < 0 }.sumOf { it.n }
                        ItemSlot(id, have - used, s.optInt("rarity"), 54.dp, dur = if (single) s.optInt("dur") else -1) {
                            if (st.myOk || have - used <= 0) return@ItemSlot
                            if (single) offer += Online.TradeItem(id, 1, i, s.optInt("dur_raw", 1000))
                            else {
                                val ix = offer.indexOfFirst { it.id == id && it.slot < 0 }
                                if (ix >= 0) offer[ix] = offer[ix].copy(n = offer[ix].n + 1) else offer += Online.TradeItem(id, 1)
                            }
                            push()
                        }
                    }
                }
            }
            // teklifler
            Column(Modifier.weight(1.2f).fillMaxHeight().glass(20.dp, Pal.Blue).padding(12.dp)) {
                SectionTitle("Senin teklifin" + if (st.myOk) " ✔" else "")
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp), modifier = Modifier.horizontalScroll(rememberScrollState())) {
                    if (offer.isEmpty()) T("Çantandan eşya ekle", 12.sp, Pal.Sub)
                    for (it in offer) ItemSlot(it.id, it.n, 0, 54.dp, dur = if (it.slot >= 0) it.dur / 10 else -1) { if (!st.myOk) { offer.remove(it); push() } }
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon("coin", 22.dp, Pal.Gold); Spacer(Modifier.width(6.dp))
                    Field(gold, { v -> if (!st.myOk) { gold = v.filter { c -> c.isDigit() }.take(7); push() } }, "Altın", Modifier.width(140.dp))
                }
                Spacer(Modifier.height(10.dp))
                SectionTitle("${st.otherName} teklifi" + if (st.theirOk) " ✔" else "")
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp), modifier = Modifier.horizontalScroll(rememberScrollState())) {
                    if (st.theirs.isEmpty()) T("Henüz bir şey eklemedi", 12.sp, Pal.Sub)
                    for (it in st.theirs) ItemSlot(it.id, it.n, 0, 54.dp, dur = if (it.dur < 1000 && it.id != "coin") it.dur / 10 else -1)
                }
                if (st.changedAfterReady) {
                    Spacer(Modifier.height(6.dp))
                    T("Sen onayladıktan sonra karşı taraf teklifini değiştirdi. Bu takas tamamlanamaz: iptal edip yeniden başlat.", 12.sp, Pal.Red, bold = true)
                }
                Spacer(Modifier.weight(1f))
                // karşı teklif yeni değiştiyse onay 3 sn bekler (son anda değiştirilen teklifi fark etmeden onaylama)
                val wait = ((st.theirsAt + 3000 - now) / 1000 + 1).toInt().coerceAtLeast(0).let { if (st.theirsAt + 3000 <= now) 0 else it }
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    GButton("İptal", Modifier.weight(1f), Tone.Red, height = 44.dp) { Online.cancelTrade(); close() }
                    GButton(when { st.myOk -> "Hazırım ✔"; wait > 0 -> "Onayla ($wait)"; else -> "Onayla" }, Modifier.weight(1.4f),
                        if (st.myOk || wait > 0) Tone.Dark else Tone.Green, height = 44.dp) {
                        if (wait == 0 && !st.changedAfterReady) Online.setTradeReady(!st.myOk)
                    }
                }
                T("İki taraf da onaylayınca eşyalar takas edilir. Ekipman dayanıklılığıyla gider. Onayından sonra karşı teklif değişirse takas tamamlanmaz.", 11.sp, Pal.Sub, maxLines = 3)
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/ui/SettingsScreen.kt
// ====================================================================================================

/** Ayarlar: sekmeler üstte, içerik tek alanda çok sütunlu; hiçbir sekmede kaydırma yok (en küçük yatay ekran 800×360 dp'ye göre). */
@Composable
fun SettingsScreen(back: () -> Unit, inGame: Boolean = false, onReset: () -> Unit = {}, initialTab: Int = 0) {
    val ctx = LocalContext.current
    var s by remember { mutableStateOf(Settings.current) }
    var tab by remember { mutableIntStateOf(initialTab) }
    fun set(n: Settings) { s = n; Settings.save(ctx, n) }
    fun custom(n: Settings) = set(n.copy(preset = 4))
    val tabs = listOf("Grafik", "Kontroller", "Ses", "Bildirimler", "Hesap", "Destek", "Dil · Language", "Yasal")
    val tabIcons = listOf("eye", "fist", "volume", "mail", "user", "info", "globe", "scroll")

    PxFrame("Ayarlar", "gear", back) {
        // sekmeler: kabartma plaka; etkin olan yeşil, üstten ışıklı ve altında altın çizgi
        Row(Modifier.fillMaxWidth().height(34.dp), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            tabs.forEachIndexed { i, n ->
                val on = tab == i
                Row(Modifier.weight(n.length + 7f).fillMaxHeight().clip(RoundedCornerShape(3.dp)).background(if (on) Px.Green else Px.PanelDark)
                    .pxBevel(light = if (on) 0.16f else 0.05f)
                    .drawBehind { if (on) drawRect(Px.Clan, Offset(0f, size.height - 3.dp.toPx()), Size(size.width, 3.dp.toPx())) }
                    .border(2.dp, Px.Edge, RoundedCornerShape(3.dp)).clickable { com.zenvex.online.Audio.play("click", bus = com.zenvex.online.Audio.Bus.Ui); tab = i },
                    horizontalArrangement = Arrangement.Center, verticalAlignment = Alignment.CenterVertically) {
                    Icon(tabIcons[i], 14.dp, if (on) Px.Clan else Px.Sub.copy(alpha = 0.8f))
                    Spacer(Modifier.width(5.dp))
                    PT(n, 12.sp, if (on) Color.White else Px.Sub)
                }
            }
        }
        Spacer(Modifier.height(6.dp))
        PxPanel(Modifier.fillMaxWidth().weight(1f).padding(bottom = 4.dp), pad = 8.dp) {
            when (tab) {
                0 -> Cols {
                    Col {
                        Choice("Grafik Kalitesi", listOf("Düşük", "Orta", "Yüksek", "Ultra", "Özel"), s.preset) { set(s.withPreset(it)) }
                        Choice("FPS Sınırı", listOf("30", "45", "60", "90", "120"), listOf(30, 45, 60, 90, 120).indexOf(s.fpsLimit).coerceAtLeast(0)) {
                            custom(s.copy(fpsLimit = listOf(30, 45, 60, 90, 120)[it]))
                        }
                        Choice("Çözünürlük", listOf("%67", "%80", "%100"), s.resolution) { custom(s.copy(resolution = it)) }
                        Choice("Kamera Uzaklığı", listOf("Yakın", "Normal", "Uzak"), s.zoom) { set(s.copy(zoom = it)) }
                        Choice("Bitki Yoğunluğu", listOf("Düşük", "Orta", "Yüksek"), s.vegetation) { custom(s.copy(vegetation = it)) }
                    }
                    Col {
                        Choice("3B Karakter Kalitesi", listOf("Düşük", "Orta", "Yüksek"), s.model3d) { custom(s.copy(model3d = it)) }
                        Choice("Efekt Kalitesi", listOf("Düşük", "Orta", "Yüksek", "Ultra"), s.fx) { custom(s.copy(fx = it)) }
                        Toggle("Rüzgâr Animasyonu", s.wind) { custom(s.copy(wind = it)) }
                        Toggle("Gölgeler", s.shadows) { custom(s.copy(shadows = it)) }
                        Toggle("Parçacık Efektleri", s.particles) { custom(s.copy(particles = it)) }
                        Toggle("Arkasındayken Ağacı Saydamlaştır", s.treeFade) { set(s.copy(treeFade = it)) }
                    }
                    Col {
                        Slider("Ekran Sarsıntısı", s.screenShake, 0f, 1f, pct = true) { set(s.copy(screenShake = it)) }
                        Toggle("Hasar Sayıları", s.damageNumbers) { set(s.copy(damageNumbers = it)) }
                        Toggle("Pil Tasarrufu (30 FPS)", s.batterySaver) { set(s.copy(batterySaver = it)) }
                        Toggle("FPS Göstergesi", s.showFps) { set(s.copy(showFps = it)) }
                        Toggle("Ping Göstergesi", s.showPing) { set(s.copy(showPing = it)) }
                        Toggle("Oyuncu Unvanlarını Gizle (Kendininki Dahil)", s.hideTitles) { set(s.copy(hideTitles = it)) }
                        Toggle("Ekran Arka Planlarını Şeffaflaştır", s.uiTransparent) { set(s.copy(uiTransparent = it)) }
                    }
                }
                1 -> Cols {
                    Col {
                        Head("Hareket Joysticki")
                        Toggle("Dinamik Joystick (Dokunduğun Yerde Açılır)", s.moveDynamic) { set(s.copy(moveDynamic = it)) }
                        Slider("Hareket Hassasiyeti", s.moveSensitivity, 0.5f, 2f) { set(s.copy(moveSensitivity = it)) }
                        Slider("Hareket Ölü Bölgesi", s.moveDeadZone, 0f, 0.3f, pct = true) { set(s.copy(moveDeadZone = it)) }
                        Slider("Koşma Eşiği", s.runThreshold, 0.4f, 0.9f, pct = true) { set(s.copy(runThreshold = it)) }
                    }
                    Col {
                        Head("Saldırı Joysticki")
                        PT("Çevirdiğin yöne saldırır, basılı tuttukça devam eder.", 11.sp, Px.Sub, maxLines = 3)
                        Slider("Saldırı Hassasiyeti", s.attackSensitivity, 0.5f, 2f) { set(s.copy(attackSensitivity = it)) }
                        Slider("Saldırı Ölü Bölgesi", s.attackDeadZone, 0f, 0.3f, pct = true) { set(s.copy(attackDeadZone = it)) }
                    }
                    Col {
                        Head("Genel")
                        Slider("Joystick Boyutu", s.joystickSize, 0.7f, 1.5f, pct = true) { set(s.copy(joystickSize = it)) }
                        Slider("Joystick Saydamlığı", s.joystickOpacity, 0.2f, 1f, pct = true) { set(s.copy(joystickOpacity = it)) }
                        Choice("Titreşim", listOf("Kapalı", "Hafif", "Güçlü"), s.haptics) { set(s.copy(haptics = it)) }
                        Toggle("Sol El Modu (Joystickleri Değiştir)", s.leftHanded) { set(s.copy(leftHanded = it)) }
                        Spacer(Modifier.weight(1f))
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            PxButton("Rehber", Modifier.weight(1f), color = Px.Blue, icon = "info", height = 34.dp, size = 12.sp) {
                                com.zenvex.online.HudLayout.guideReplay = true
                                Toaster.show("Oyuna dönünce gösterilir")
                            }
                            PxButton("Sıfırla", Modifier.weight(1f), color = Px.Dark, icon = "refresh", height = 34.dp, size = 12.sp) {
                                val d = Settings()
                                set(s.copy(moveDynamic = d.moveDynamic, moveSensitivity = d.moveSensitivity, moveDeadZone = d.moveDeadZone,
                                    runThreshold = d.runThreshold, attackSensitivity = d.attackSensitivity, attackDeadZone = d.attackDeadZone,
                                    joystickSize = d.joystickSize, joystickOpacity = d.joystickOpacity, haptics = d.haptics, leftHanded = d.leftHanded))
                            }
                        }
                    }
                }
                2 -> Cols {
                    Col {
                        PT("Müzik lobide ve oyunda çalar; efektler oyun içindir.", 12.sp, Px.Sub, maxLines = 3)
                        Spacer(Modifier.height(6.dp))
                        Slider("Ana Ses", s.master, 0f, 1f, pct = true) { set(s.copy(master = it)) }
                        Slider("Müzik", s.music, 0f, 1f, pct = true) { set(s.copy(music = it)) }
                    }
                    Col {
                        Slider("Efektler", s.sfx, 0f, 1f, pct = true) { set(s.copy(sfx = it)) }
                        Slider("Ortam Sesleri", s.ambient, 0f, 1f, pct = true) { set(s.copy(ambient = it)) }
                        Slider("Arayüz Sesleri", s.uiSound, 0f, 1f, pct = true) { set(s.copy(uiSound = it)) }
                    }
                }
                3 -> NotificationSettings()
                4 -> AccountSettings(inGame, onReset)
                5 -> SupportSection()
                6 -> LanguageSection(s.language) { Settings.markLanguageChosen(ctx); set(s.copy(language = it)) }
                else -> LegalPanel()
            }
        }
    }
}

/** Panelin içinde yan yana sütunlar: kalan yüksekliği doldurur, taşmaz. */
@Composable
private fun ColumnScope.Cols(content: @Composable RowScope.() -> Unit) =
    Row(Modifier.fillMaxWidth().weight(1f), horizontalArrangement = Arrangement.spacedBy(14.dp), content = content)

@Composable
private fun RowScope.Col(weight: Float = 1f, content: @Composable ColumnScope.() -> Unit) =
    Column(Modifier.weight(weight).fillMaxHeight(), content = content)

private fun notifEnabled(ctx: android.content.Context) = runCatching { androidx.core.app.NotificationManagerCompat.from(ctx).areNotificationsEnabled() }.getOrDefault(true)

@Composable
private fun ColumnScope.NotificationSettings() {
    val ctx = LocalContext.current
    // izin durumu: sistem ayarlarından dönünce de güncellenir
    var allowed by remember { mutableStateOf(notifEnabled(ctx)) }
    androidx.compose.runtime.LaunchedEffect(Unit) {
        while (true) {
            allowed = notifEnabled(ctx)
            kotlinx.coroutines.delay(1000)
        }
    }
    val N = com.zenvex.online.Notifier
    var mail by remember { mutableStateOf(N.enabled(ctx, N.K_MAIL)) }
    var dm by remember { mutableStateOf(N.enabled(ctx, N.K_DM)) }
    var social by remember { mutableStateOf(N.enabled(ctx, N.K_SOCIAL)) }
    val promo = com.zenvex.online.Legal.promo.value
    Cols {
        Col {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(if (allowed) "check" else "mail", 26.dp, if (allowed) Px.Name else Px.Sub)
                Spacer(Modifier.width(8.dp))
                PT(if (allowed) "Bildirimler Açık" else "Bildirimler Kapalı", 16.sp, if (allowed) Px.Name else Color(0xFFFF7A6A))
            }
            Spacer(Modifier.height(6.dp))
            PxButton(if (allowed) "Bildirim Ayarlarını Düzenle" else "Bildirim İzinlerini Aç",
                color = if (allowed) Px.Dark else Px.Blue, icon = "mail", height = 40.dp, size = 14.sp) {
                val i = if (Build.VERSION.SDK_INT >= 26) Intent(SysSettings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(SysSettings.EXTRA_APP_PACKAGE, ctx.packageName)
                else Intent(SysSettings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:" + ctx.packageName))
                runCatching { ctx.startActivity(i) }
            }
            Spacer(Modifier.height(6.dp))
            Head("Hizmet Bildirimleri")
            Toggle("Posta ve hediyeler", mail) { mail = it; N.setEnabled(ctx, N.K_MAIL, it) }
            Toggle("Özel mesajlar", dm) { dm = it; N.setEnabled(ctx, N.K_DM, it) }
            Toggle("Arkadaşlık istekleri ve klan davetleri", social) { social = it; N.setEnabled(ctx, N.K_SOCIAL, it) }
        }
        Col {
            Head("Etkinlik Ve Kampanya Duyuruları")
            Toggle("Yeni etkinlik, sezon ve kampanyalardan haberdar olmak istiyorum", promo) { com.zenvex.online.Legal.setPromo(it) }
            PT("İsteğe bağlıdır (ticari elektronik ileti, 6563 sayılı Kanun). Onayını istediğin an buradan ya da bildirimdeki \"Bu Duyuruları Kapat\" ile ücretsiz geri alabilirsin. SMS veya e-posta gönderilmez.",
                11.sp, Px.Sub, maxLines = 6)
            LegalLink("promo")
        }
    }
}

/** Dil seçimi: her dil kendi adıyla yazılır (seçen kişi okuyabilsin); seçince tüm arayüz hemen değişir. */
@Composable
private fun ColumnScope.LanguageSection(current: String, pick: (String) -> Unit) {
    PT("Oyunun dili. Oyuncuların sohbet mesajları çevrilmez.", 12.sp, Px.Sub, maxLines = 2)
    Spacer(Modifier.height(6.dp))
    Cols {
        for (chunk in com.zenvex.online.I18n.LANGS.entries.toList().chunked(4)) Col {
            for ((code, name) in chunk) {
                val on = code == current
                Row(Modifier.fillMaxWidth().padding(vertical = 3.dp).background(if (on) Px.Green else Px.PanelDark).border(2.dp, Px.Edge)
                    .clickable { pick(code) }.padding(horizontal = 10.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                    // ad çevrilmesin: düz Text
                    androidx.compose.material3.Text(name, color = if (on) Color.White else Px.Text,
                        style = androidx.compose.ui.text.TextStyle(fontFamily = PixelFont, fontSize = 15.sp), maxLines = 1)
                    Spacer(Modifier.weight(1f))
                    if (on) Icon("check", 18.dp, Color.White)
                }
            }
        }
    }
}

@Composable
private fun Head(t: String) {
    // bölüm başlığı: sol altın çubuk, yazı ve sağa uzayan ince çizgi
    Row(Modifier.fillMaxWidth().padding(top = 2.dp, bottom = 4.dp), verticalAlignment = Alignment.CenterVertically) {
        Box(Modifier.size(3.dp, 14.dp).background(Px.Clan))
        Spacer(Modifier.width(6.dp))
        PT(t, 14.sp, Px.Clan)
        Spacer(Modifier.width(8.dp))
        Box(Modifier.weight(1f).height(1.dp).background(Brush.horizontalGradient(listOf(Px.Clan.copy(alpha = 0.4f), Color.Transparent))))
    }
}

@Composable
fun Toggle(label: String, value: Boolean, onChange: (Boolean) -> Unit) {
    Row(Modifier.fillMaxWidth().heightIn(min = 28.dp).clickable { onChange(!value) }.padding(vertical = 2.dp), verticalAlignment = Alignment.CenterVertically) {
        PT(label, 12.sp, modifier = Modifier.weight(1f), maxLines = 2)
        Spacer(Modifier.width(8.dp))
        // piksel anahtar: gömük yuva (açıkken yeşil ve ışıklı), kabartma kare düğme
        val k by androidx.compose.animation.core.animateFloatAsState(if (value) 1f else 0f, androidx.compose.animation.core.tween(140), label = "tg")
        Box(Modifier.width(44.dp).height(22.dp).clip(RoundedCornerShape(3.dp)).background(Px.Edge).padding(2.dp)
            .background(androidx.compose.ui.graphics.lerp(Color(0xFF26251F), Px.Green, k)).pxBevel(false).padding(2.dp)) {
            Box(Modifier.offset(x = (22 * k).dp).size(14.dp).background(androidx.compose.ui.graphics.lerp(Px.Sub, Color(0xFFF0F6DC), k))
                .pxBevel(light = 0.3f).border(1.dp, Px.Edge))
        }
    }
}

@Composable
fun Choice(label: String, options: List<String>, selected: Int, onSelect: (Int) -> Unit) {
    Column(Modifier.fillMaxWidth().padding(vertical = 2.dp)) {
        PT(label, 12.sp)
        Spacer(Modifier.height(1.dp))
        // gömük ray içinde seçenekler; seçili olan yeşil kabartma plaka
        Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(3.dp)).background(Color(0xFF17160F)).pxBevel(false)
            .border(1.dp, Px.Edge, RoundedCornerShape(3.dp)).padding(2.dp), horizontalArrangement = Arrangement.spacedBy(2.dp)) {
            options.forEachIndexed { i, o ->
                val on = i == selected
                Box(Modifier.weight(1f).clip(RoundedCornerShape(2.dp)).background(if (on) Px.Green else Color(0xFF2A2924))
                    .pxBevel(light = if (on) 0.18f else 0.04f)
                    .then(if (on) Modifier.border(1.dp, Px.GreenHi, RoundedCornerShape(2.dp)) else Modifier)
                    .clickable { onSelect(i) }
                    .padding(vertical = 3.dp), contentAlignment = Alignment.Center) { PT(o, 11.sp, if (on) Color.White else Px.Sub) }
            }
        }
    }
}

@Composable
fun Slider(label: String, value: Float, min: Float, max: Float, pct: Boolean = false, onChange: (Float) -> Unit) {
    var w by remember { mutableIntStateOf(1) }
    val frac = ((value - min) / (max - min)).coerceIn(0f, 1f)
    fun pick(x: Float) {
        val f = (x / w).coerceIn(0f, 1f)
        onChange(((min + f * (max - min)) * 100).roundToInt() / 100f)
    }
    Column(Modifier.fillMaxWidth().padding(vertical = 2.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            PT(label, 12.sp, modifier = Modifier.weight(1f))
            PT(if (pct) "%${(value * 100).roundToInt()}" else String.format("%.2f×", value), 12.sp, Px.Clan)
        }
        Box(
            Modifier.fillMaxWidth().height(22.dp).onSizeChanged { w = it.width }
                .pointerInput(min, max) { detectTapGestures { pick(it.x) } }
                .pointerInput(min, max) { detectDragGestures { ch, _ -> pick(ch.position.x) } },
            contentAlignment = Alignment.CenterStart,
        ) {
            PxBar(frac, Px.Clan, Modifier.fillMaxWidth(), 8.dp)
            // düğme ölçülmüş genişliğe bağlı değil (ilk karede 0'a atlıyordu): doluluk oranındaki kutunun ucunda durur
            Box(Modifier.fillMaxWidth(frac).height(20.dp)) {
                Box(Modifier.align(Alignment.CenterEnd).offset(x = 6.dp).size(12.dp, 20.dp).background(Color(0xFFE8E4D4)).pxBevel(light = 0.4f)
                    .border(2.dp, Px.Edge))
            }
        }
    }
}

/** Zenvex hesabı: ID, anahtar, isim, Google bağlantısı, başka hesaba giriş; iki sütun. */
@Composable
private fun ColumnScope.AccountSettings(inGame: Boolean, onReset: () -> Unit) {
    val ctx = LocalContext.current
    var showKey by remember { mutableStateOf(false) }
    var dialog by remember { mutableStateOf(false) }
    var nick by remember { mutableStateOf(Account.name.value) }
    var confirmKey by remember { mutableStateOf(false) }
    // oyundan atıldıysak (başka cihaz, bakım, yasak, bağlantı) nedeni göster
    val kicked = com.zenvex.online.Session.kicked.value
    androidx.compose.runtime.LaunchedEffect(kicked) { if (kicked != null) { Toaster.show(kicked, false); com.zenvex.online.Session.kicked.value = null } }
    var confirmReset by remember { mutableStateOf(false) }
    val resetBtn: @Composable () -> Unit = {
        if (!inGame) PxButton(if (confirmReset) "Emin Misin? Tekrar Bas" else "Bu Sunucudaki İlerlemeyi Sil", Modifier.fillMaxWidth(), color = Px.Red, height = 34.dp, size = 12.sp) {
            if (confirmReset) { onReset(); confirmReset = false } else confirmReset = true
        }
    }
    if (!Account.loggedIn) {
        Head("Zenvex Hesabı")
        PT("Hesabına girmedin. Zenvex çevrimiçi bir oyundur: oynamak için hesap aç ya da gir.", 13.sp, Px.Sub, maxLines = 3)
        Spacer(Modifier.height(8.dp))
        PxButton("Hesap Aç / Giriş Yap", icon = "user", height = 44.dp, size = 15.sp) { dialog = true }
        Spacer(Modifier.height(8.dp))
        resetBtn()
    } else Cols {
        Col {
            Head("Zenvex Hesabı")
            PT("ID: ${fmtId(Account.id.value)}", 18.sp, Px.Name)
            PT("Durum: " + Account.status.value, 13.sp, if (Account.status.value == "Çevrimiçi") Px.Name else Px.Sub)
            Spacer(Modifier.height(6.dp))
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                PT("Anahtar: " + if (showKey) Account.key else "••••••••••••", 13.sp, Px.Clan, Modifier.weight(1f))
                PxButton(if (showKey) "Gizle" else "Göster", color = Px.Dark, height = 30.dp, size = 12.sp) { showKey = !showKey }
                PxButton("Kopyala", color = Px.Dark, height = 30.dp, size = 12.sp) {
                    copy(ctx, "Zenvex ID: ${Account.id.value}  Anahtar: ${Account.key}"); Toaster.show("Kopyalandı")
                }
            }
            PT("ID ve anahtarı bir yere not et: telefon değişirse bunlarla girersin.", 11.sp, Px.Sub, maxLines = 3)
            if (Account.profile.value.optBoolean("google")) {
                Spacer(Modifier.height(4.dp))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon("check", 20.dp, Px.Name)
                    Spacer(Modifier.width(6.dp))
                    PT("Google Hesabına Bağlı: Bu Telefonda Ya Da Yenisinde Google İle Girebilirsin", 12.sp, Px.Name, maxLines = 3)
                }
            }
        }
        Col {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                Field(nick, { nick = it.take(16) }, "Oyuncu Adı", Modifier.weight(1f))
                PxButton("İsmi Değiştir", color = Px.Blue, height = 44.dp, size = 13.sp) {
                    Account.rename(nick) { e ->
                        if (e != null) Toaster.show(e, false) else { GameSession.cmd("set_name", "name" to Account.name.value); Toaster.show("İsim Değişti") }
                    }
                }
            }
            Spacer(Modifier.height(6.dp))
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                PxButton(if (confirmKey) "Emin Misin?" else "Anahtarı Değiştir", Modifier.weight(1f), color = Px.Red, height = 34.dp, size = 12.sp) {
                    if (!confirmKey) { confirmKey = true; return@PxButton }
                    confirmKey = false
                    Account.changeKey { e -> if (e != null) Toaster.show(e, false) else { showKey = true; Toaster.show("Yeni Anahtar Oluşturuldu, Not Et!") } }
                }
                if (!Account.profile.value.optBoolean("google")) PxButton("Google'a Bağla", Modifier.weight(1f), height = 34.dp, size = 12.sp) {
                    val act = ctx as? android.app.Activity ?: return@PxButton
                    com.zenvex.online.GoogleSignIn.start(act, link = true) { e ->
                        when { e == null -> { Toaster.show("Hesabın Google'a Bağlandı"); Account.refresh() }; e.isNotEmpty() -> Toaster.show(e, false) }
                    }
                }
            }
            Spacer(Modifier.height(6.dp))
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                PxButton("Başka Hesaba Gir", Modifier.weight(1f), color = Px.Dark, height = 34.dp, size = 12.sp) { dialog = true }
                PxButton("Çıkış", Modifier.weight(1f), color = Px.Dark, height = 34.dp, size = 12.sp) {
                    GameSession.save(cloud = true); com.zenvex.online.Session.end(); Account.logout(); GameSession.reload { Toaster.show("Hesaptan Çıkıldı") }
                }
            }
            Spacer(Modifier.height(6.dp))
            resetBtn()
        }
    }
    if (dialog) AccountDialog { dialog = false }
}

// ====================================================================================================
// com/zenvex/online/ui/Shop.kt
// ====================================================================================================

private val VIP = Color(0xFFE6B4FF)

@Composable
fun ShopScreen(close: () -> Unit, startTab: Int = 0) {
    var tick by remember { mutableIntStateOf(0) }
    LaunchedEffect(tick) { Store.refresh() }
    ShopView(Store.state.value, Account.loggedIn, Pass.now(), startTab, close) { tick++ }
}

@Composable
internal fun ShopView(s: JSONObject?, loggedIn: Boolean, now: Long, startTab: Int, close: () -> Unit, refresh: () -> Unit) {
    var tab by remember { mutableIntStateOf(startTab) }
    val t = rememberTime()
    ScreenFrame("MAĞAZA", "crate", close, bg = if (UiArt.has(LocalContext.current, "shop_bg")) "shop_bg" else null) {
        if (!loggedIn) { PT("Mağaza İçin Hesabına Gir", 18.sp, Px.Sub); return@ScreenFrame }
        Row(Modifier.fillMaxSize(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            // sol: sekmeler
            Column(Modifier.width(150.dp).fillMaxHeight(), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                val offers = s?.optJSONArray("offers")?.length() ?: 0
                listOf(Triple("Öne Çıkan", "star", offers), Triple("Elmas", "gem", 0), Triple("Paketler", "crate", offers),
                    Triple("Kartlar", "calendar", if (s?.optJSONArray("cards")?.objs()?.any { it.optBoolean("claimable") } == true) 1 else 0),
                    Triple("Sezon Bileti", "pass", 0)).forEachIndexed { i, (n, ic, badge) ->
                    val on = i == tab
                    Row(Modifier.fillMaxWidth().height(46.dp).clip(RoundedCornerShape(4.dp))
                        .background(if (on) Brush.horizontalGradient(listOf(Color(0xFF6A4A16), Color(0xFF2A2012))) else Brush.horizontalGradient(listOf(Px.PanelDark, Px.PanelDark)))
                        .border(1.dp, if (on) GOLD.copy(alpha = 0.7f) else Color(0x33FFFFFF), RoundedCornerShape(4.dp))
                        .clickable { tab = i }.padding(horizontal = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                        // sekme görselleri docs/25 numarasıyla; VIP sekmesi kalktığı için Sezon Bileti (4) görseli shoptab_5
                        val art = "shoptab_${if (i == 4) 5 else i}"
                        if (UiArt.has(LocalContext.current, art)) ArtImage(art, Modifier.size(26.dp)) else Icon(ic, 22.dp, if (on) GOLD else Px.Sub)
                        Spacer(Modifier.width(6.dp))
                        PT(n, 15.sp, if (on) Color.White else Px.Sub, Modifier.weight(1f))
                        if (badge > 0) Box(Modifier.size(10.dp).clip(RoundedCornerShape(5.dp)).background(Color(0xFFE04040)
                            .copy(alpha = 0.6f + 0.4f * sin(t * 5f))))
                    }
                }
            }
            // sağ: içerik
            Column(Modifier.weight(1f).fillMaxHeight().verticalScroll(rememberScrollState())) {
                if (s == null) { PT("Yükleniyor…", 16.sp, Px.Sub); return@Column }
                val products = s.optJSONArray("products").objs().associateBy { it.optString("id") }
                when (tab) {
                    0 -> Featured(s, products, now, t) { tab = it }
                    1 -> GemsTab(products, t)
                    2 -> PacksTab(s, products, now, t)
                    3 -> CardsTab(s, products, now, refresh)
                    else -> PassTab(s, products, t)
                }
            }
        }
    }
}

/** Ürün kartı: parlak kenar, kayan ışık, köşede "İlk alım 2×" kurdelesi, altta fiyat tuşu */
@Composable
private fun ProductCard(modifier: Modifier, accent: Color, t: Float, ribbon: String? = null, price: String, priceEnabled: Boolean = true,
                        onBuy: () -> Unit, content: @Composable BoxScope.() -> Unit) {
    Box(modifier.clip(RoundedCornerShape(6.dp)).background(Brush.verticalGradient(listOf(accent.copy(alpha = 0.22f), Color(0xF0121014))))
        .border(1.5.dp, accent.copy(alpha = 0.55f + 0.2f * sin(t * 2f)), RoundedCornerShape(6.dp))) {
        Canvas(Modifier.matchParentSize()) {
            val u = ((t * 0.35f) % 1.6f - 0.3f) * size.width
            drawRect(Brush.linearGradient(listOf(Color.Transparent, Color.White.copy(alpha = 0.10f), Color.Transparent),
                Offset(u - 60f, 0f), Offset(u + 60f, size.height)))
        }
        Column(Modifier.fillMaxSize().padding(8.dp), horizontalAlignment = Alignment.CenterHorizontally) {
            Box(Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center, content = content)
            PxButton(price, Modifier.fillMaxWidth(), if (priceEnabled) Px.Green else Px.Dark, size = 16.sp, height = 38.dp,
                enabled = priceEnabled && Store.busy.value == null) { onBuy() }
        }
        if (ribbon != null) Box(Modifier.align(Alignment.TopEnd).padding(4.dp).clip(RoundedCornerShape(3.dp))
            .background(Brush.horizontalGradient(listOf(Color(0xFFD02A20), Color(0xFFFF7A2A)))).padding(horizontal = 6.dp, vertical = 2.dp)) {
            PT(ribbon, 11.sp, Color.White)
        }
    }
}

private fun fmtLeftMs(ms: Long): String {
    val s = (ms / 1000).coerceAtLeast(0)
    val d = s / 86400; val h = s % 86400 / 3600; val m = s % 3600 / 60; val sec = s % 60
    return if (d > 0) "${d}g %02d:%02d:%02d".format(h, m, sec) else "%02d:%02d:%02d".format(h, m, sec)
}

@Composable
private fun Contents(p: JSONObject) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        if (p.optInt("gems") > 0) Row(verticalAlignment = Alignment.CenterVertically) { Icon("gem", 18.dp, GEM); PT(" ${fmtL(p.optLong("gems"))} Elmas", 14.sp, GEM) }
        if (p.optLong("gold") > 0) Row(verticalAlignment = Alignment.CenterVertically) { Icon("coin", 18.dp, GOLD); PT(" ${fmtL(p.optLong("gold"))} Altın", 14.sp, GOLD) }
        val items = p.optJSONArray("items").objs()
        if (items.isNotEmpty()) Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
            for (it in items.take(5)) Box {
                ItemSlot(it.optString("id"), it.optInt("n"), size = 40.dp)
            }
        }
    }
}

@Composable
private fun Featured(s: JSONObject, products: Map<String, JSONObject>, now: Long, t: Float, goTab: (Int) -> Unit) {
    val offers = s.optJSONArray("offers").objs()
    if (offers.isEmpty()) {
        PxPanel(Modifier.fillMaxWidth()) {
            PT("Sınırlı Süreli Paketler", 18.sp, GOLD)
            PT("5., 10. ve 25. seviyeye ulaşınca sana özel, süreli bir paket açılır. Şimdilik elmas paketlerine göz at: her paketin ilk alımında elmaslar 2 katı!",
                14.sp, Px.Text, maxLines = 3)
            Spacer(Modifier.height(6.dp))
            PxButton("Elmas Paketleri", icon = "gem", color = Px.Blue) { goTab(1) }
        }
    }
    for (o in offers) {
        val p = products[o.optString("id")] ?: continue
        val left = o.optLong("ends") - now
        ProductCard(Modifier.fillMaxWidth().height(220.dp), GOLD, t, ribbon = "SÜRELİ", price = Store.price(p.optString("id"), p.optDouble("price")),
            onBuy = { Store.buy(p.optString("id")) }) {
            Row(Modifier.fillMaxSize(), verticalAlignment = Alignment.CenterVertically) {
                Box(Modifier.size(130.dp), contentAlignment = Alignment.Center) {
                    val art = p.optString("id")
                    if (UiArt.has(LocalContext.current, art)) ArtImage(art, Modifier.size(126.dp).graphicsLayer { rotationZ = sin(t * 1.5f) * 2f })
                    else Icon("crate", 90.dp, GOLD)
                }
                Column(Modifier.weight(1f)) {
                    PT(p.optString("title"), 24.sp, GOLD, outline = true)
                    Row(verticalAlignment = Alignment.CenterVertically) { Icon("clock", 16.dp, Color(0xFFFF7A6A)); PT(" Kalan: ${fmtLeftMs(left)}", 15.sp, Color(0xFFFF7A6A)) }
                    PT("5 Katı Değerinde. Bir Daha Gelmez!", 13.sp, Px.Sub)
                    Spacer(Modifier.height(4.dp))
                    Contents(p)
                }
            }
        }
        Spacer(Modifier.height(8.dp))
    }
}

@Composable
private fun GemsTab(products: Map<String, JSONObject>, t: Float) {
    val gems = products.values.filter { it.optString("kind") == "gems" }
    for (row in gems.chunked(3)) {
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            for ((i, p) in row.withIndex()) {
                val id = p.optString("id")
                val bonus = p.optJSONObject("meta")?.optInt("bonus") ?: 0
                ProductCard(Modifier.weight(1f).height(200.dp), GEM, t + i, ribbon = if (p.optBoolean("first")) "İLK ALIM 2×" else if (bonus > 0) "+%$bonus" else null,
                    price = Store.price(id, p.optDouble("price")), onBuy = { Store.buy(id) }) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        val tier = gems.indexOf(p)
                        if (UiArt.has(LocalContext.current, "gems_${tier + 1}")) ArtImage("gems_${tier + 1}", Modifier.size(84.dp))
                        else Icon("gem", (40 + tier * 8).dp, GEM)
                        PT(fmtL(p.optLong("gems")), 22.sp, GEM, outline = true)
                        PT(p.optString("title"), 12.sp, Px.Sub)
                    }
                }
            }
            repeat(3 - row.size) { Spacer(Modifier.weight(1f)) }
        }
        Spacer(Modifier.height(8.dp))
    }
    PT("Ödeme Google Play ile yapılır; fiyatlara vergiler dahildir, içerik postana gelir. Tüm ürünler tek seferliktir, otomatik yenilenmez.", 12.sp, Px.Sub, maxLines = 2)
}

@Composable
private fun PacksTab(s: JSONObject, products: Map<String, JSONObject>, now: Long, t: Float) {
    val offers = s.optJSONArray("offers").objs().associateBy { it.optString("id") }
    val lv = com.zenvex.online.GameSession.hud()[com.zenvex.online.Native.LEVEL].toInt()
    for (p in products.values.filter { it.optString("kind") == "pack" }) {
        val id = p.optString("id")
        val m = p.optJSONObject("meta") ?: JSONObject()
        val o = offers[id]
        val need = m.optInt("level")
        val state = when { o != null -> "Kalan: ${fmtLeftMs(o.optLong("ends") - now)}"; lv < need -> "Seviye $need'de açılır (${m.optInt("hours")} saat)"; else -> "Süresi doldu ya da alındı" }
        ProductCard(Modifier.fillMaxWidth().height(170.dp), if (o != null) GOLD else Color(0xFF6A6A70), t, price = Store.price(id, p.optDouble("price")),
            priceEnabled = o != null, onBuy = { Store.buy(id) }) {
            Row(Modifier.fillMaxSize(), verticalAlignment = Alignment.CenterVertically) {
                Column(Modifier.weight(1f)) {
                    PT(p.optString("title"), 20.sp, if (o != null) GOLD else Px.Sub)
                    PT(state, 13.sp, if (o != null) Color(0xFFFF7A6A) else Px.Sub)
                }
                Contents(p)
            }
        }
        Spacer(Modifier.height(8.dp))
    }
}

@Composable
private fun CardsTab(s: JSONObject, products: Map<String, JSONObject>, now: Long, changed: () -> Unit) {
    val cards = s.optJSONArray("cards").objs().associateBy { it.optString("id") }
    val t = rememberTime()
    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        for (p in products.values.filter { it.optString("kind") == "card" }) {
            val id = p.optString("id")
            val m = p.optJSONObject("meta") ?: JSONObject()
            val c = cards[id]
            val days = m.optInt("days")
            val total = p.optInt("gems") + m.optInt("daily_gems") * days
            ProductCard(Modifier.weight(1f).height(300.dp), if (id == "card_month") GOLD else Color(0xFFDCE4EE), t,
                ribbon = "TOPLAM ${fmtL(total.toLong())} ELMAS", price = Store.price(id, p.optDouble("price")), onBuy = { Store.buy(id) }) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    if (UiArt.has(LocalContext.current, id)) ArtImage(id, Modifier.size(90.dp)) else Icon("calendar", 60.dp, GOLD)
                    PT(p.optString("title"), 20.sp, Color.White)
                    PT("Anında ${p.optInt("gems")} elmas", 13.sp, GEM)
                    PT("$days gün boyunca her gün ${m.optInt("daily_gems")} elmas + ${fmtL(m.optLong("daily_gold"))} altın" +
                        (if (m.has("daily_items")) " + karakter kartı" else ""), 12.sp, Px.Text, maxLines = 2, align = androidx.compose.ui.text.style.TextAlign.Center)
                    if (c != null) {
                        PT("Aktif · ${fmtLeftMs(c.optLong("ends") - now)}", 12.sp, Px.Name)
                        if (c.optBoolean("claimable")) PxButton("Bugünkü Ödülü Al", color = Px.Orange, size = 14.sp, height = 34.dp) { Store.claimCards(changed) }
                    }
                }
            }
        }
    }
    PT("Kartlar tek seferlik satın almadır: abonelik değildir, otomatik yenilenmez. Alınmayan günlük ödüller 3 güne kadar birikir; kart bitmeden yeniden alırsan süresi uzar.", 12.sp, Px.Sub, maxLines = 2)
}

@Composable
private fun PassTab(s: JSONObject, products: Map<String, JSONObject>, t: Float) {
    val pass = s.optJSONObject("pass") ?: JSONObject()
    val normal = pass.optBoolean("normal"); val elite = pass.optBoolean("elite")
    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
        products["pass_vip"]?.let { p ->
            ProductCard(Modifier.weight(1f).height(280.dp), VIP, t, price = if (normal || elite) "Sende" else Store.price("pass_vip", p.optDouble("price")),
                priceEnabled = !normal && !elite, onBuy = { Store.buy("pass_vip") }) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    if (UiArt.has(LocalContext.current, "ticket_vip")) ArtImage("ticket_vip", Modifier.size(90.dp)) else Icon("pass", 60.dp, VIP)
                    PT("VIP Bilet", 22.sp, VIP)
                    PT("Bu sezonun bütün premium ödüllerini açar.", 13.sp, Px.Text, maxLines = 2, align = androidx.compose.ui.text.style.TextAlign.Center)
                }
            }
        }
        val upgrade = normal && !elite
        val pid = if (upgrade) "pass_upgrade" else "pass_premium"
        products[pid]?.let { p ->
            ProductCard(Modifier.weight(1f).height(280.dp), GOLD, t + 1, ribbon = "EN İYİ", price = if (elite) "Sende" else Store.price(pid, p.optDouble("price")),
                priceEnabled = !elite, onBuy = { Store.buy(pid) }) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    if (UiArt.has(LocalContext.current, "ticket_premium")) ArtImage("ticket_premium", Modifier.size(90.dp)) else Icon("crown", 60.dp, GOLD)
                    PT(if (upgrade) "Premium'a Yükselt" else "Premium Bilet", 22.sp, GOLD)
                    PT("Premium ödüller + S1 Çerçevesi + \"Sezon 1 Öncüsü\" unvanı + anında 10.000 kademe XP'si", 13.sp, Px.Text, maxLines = 3,
                        align = androidx.compose.ui.text.style.TextAlign.Center)
                }
            }
        }
    }
    PT("Bilet, şu an oynadığın sunucudaki karakterinde açılır.", 12.sp, Px.Sub)
}

// ====================================================================================================
// com/zenvex/online/ui/SkillGlyphs.kt
// ====================================================================================================

/**
 * Skill ağacı simgeleri: her istatistik türü için kodla çizilen vektör glif (görsel dosyası yok, her boyutta keskin).
 * Aile renkleri: hasar kırmızı, kritik sarı, silah turuncu, can yeşil, savunma çelik mavi, çeviklik camgöbeği.
 */
object SkillGlyphs {
    val Damage = Color(0xFFE85A3C)
    val Crit = Color(0xFFF4C542)
    val Weapon = Color(0xFFF09040)
    val Life = Color(0xFF5CCB6E)
    val Defense = Color(0xFF8FB4D8)
    val Agility = Color(0xFF5FD0F0)
    val Core = Color(0xFFE8E0C8)

    fun family(stat: String): Color = when (stat) {
        "MeleeFlat", "FistPct", "DmgPct", "Stun" -> Damage
        "Crit", "CritDmg" -> Crit
        "BladePct", "Reach", "AtkSpeed" -> Weapon
        "HpFlat", "Regen", "Lifesteal", "LastBreath" -> Life
        "DmgTaken", "Reflect", "BlastRes" -> Defense
        "Dodge", "Speed", "RollCd", "Stamina", "IFrame" -> Agility
        else -> Core
    }

    fun familyName(stat: String): String = when (family(stat)) {
        Damage -> "Hasar"; Crit -> "Kritik"; Weapon -> "Silah"; Life -> "Can"; Defense -> "Savunma"; Agility -> "Çeviklik"; else -> "Merkez"
    }

    /** c merkezli, r yarıçaplı kutuya glif çizer. */
    fun DrawScope.glyph(stat: String, c: Offset, r: Float, col: Color) {
        val w = r * 0.16f
        fun p(x: Float, y: Float) = Offset(c.x + x * r, c.y + y * r)
        fun path(vararg pts: Pair<Float, Float>, close: Boolean = true) = Path().apply {
            moveTo(c.x + pts[0].first * r, c.y + pts[0].second * r)
            for (i in 1 until pts.size) lineTo(c.x + pts[i].first * r, c.y + pts[i].second * r)
            if (close) close()
        }
        val dark = Color(0xCC0A0908)
        when (stat) {
            "MeleeFlat", "FistPct" -> { // yumruk: dört parmak boğumu + avuç + başparmak
                for (i in 0..3) drawRoundRect(col, Offset(c.x + (-0.62f + i * 0.31f) * r, c.y - 0.62f * r), Size(0.28f * r, 0.5f * r),
                    androidx.compose.ui.geometry.CornerRadius(0.1f * r))
                drawRoundRect(col, Offset(c.x - 0.62f * r, c.y - 0.25f * r), Size(1.22f * r, 0.75f * r), androidx.compose.ui.geometry.CornerRadius(0.18f * r))
                drawRoundRect(col, Offset(c.x - 0.78f * r, c.y - 0.15f * r), Size(0.36f * r, 0.5f * r), androidx.compose.ui.geometry.CornerRadius(0.15f * r))
                for (i in 0..2) drawLine(dark, p(-0.33f + i * 0.31f, -0.55f), p(-0.33f + i * 0.31f, -0.2f), w * 0.6f)
            }
            "DmgPct" -> { // çapraz iki kılıç
                for (s in listOf(1f, -1f)) {
                    drawLine(col, p(-0.7f * s, 0.7f), p(0.65f * s, -0.65f), w * 1.3f, StrokeCap.Round)
                    drawLine(col, p(-0.55f * s, 0.25f), p(-0.2f * s, 0.6f), w * 1.2f, StrokeCap.Round)
                }
            }
            "BladePct" -> { // katana: ince kavisli bıçak + tsuba + kabza
                drawLine(col, p(-0.55f, 0.55f), p(0.72f, -0.72f), w * 1.4f, StrokeCap.Round)
                drawCircle(col, 0.16f * r, p(-0.38f, 0.38f))
                drawLine(col, p(-0.42f, 0.42f), p(-0.82f, 0.82f), w * 1.8f, StrokeCap.Round)
                drawLine(Color.White.copy(alpha = 0.6f), p(-0.1f, 0.05f), p(0.55f, -0.58f), w * 0.5f)
            }
            "Reach" -> { // iki uçlu ok
                drawLine(col, p(-0.75f, 0f), p(0.75f, 0f), w * 1.3f)
                drawPath(path(-0.85f to 0f, -0.45f to -0.32f, -0.45f to 0.32f), col)
                drawPath(path(0.85f to 0f, 0.45f to -0.32f, 0.45f to 0.32f), col)
            }
            "AtkSpeed" -> { // bıçak + hız çizgileri
                drawLine(col, p(-0.2f, 0.6f), p(0.7f, -0.6f), w * 1.4f, StrokeCap.Round)
                for (i in 0..2) drawLine(col.copy(alpha = 0.8f), p(-0.85f, -0.35f + i * 0.3f), p(-0.3f, -0.35f + i * 0.3f), w * 0.8f, StrokeCap.Round)
            }
            "Crit" -> drawPath(path(0.15f to -0.9f, -0.5f to 0.1f, -0.05f to 0.1f, -0.25f to 0.9f, 0.5f to -0.15f, 0.05f to -0.15f), col) // şimşek
            "CritDmg" -> { // 8 köşeli patlama yıldızı
                val pp = Path()
                for (i in 0 until 16) {
                    val a = i * PI.toFloat() / 8; val rr = if (i % 2 == 0) 0.9f else 0.4f
                    val x = c.x + cos(a) * rr * r; val y = c.y + sin(a) * rr * r
                    if (i == 0) pp.moveTo(x, y) else pp.lineTo(x, y)
                }
                pp.close(); drawPath(pp, col); drawCircle(dark, 0.18f * r, c)
            }
            "Stun" -> { // baş dönmesi: üç yıldız yayı
                for (i in 0..2) {
                    val a = -PI.toFloat() * (0.15f + i * 0.35f)
                    star(Offset(c.x + cos(a) * 0.55f * r, c.y + sin(a) * 0.35f * r + 0.15f * r), 0.28f * r, col)
                }
                drawArc(col.copy(alpha = 0.6f), 200f, 140f, false, Offset(c.x - 0.7f * r, c.y - 0.3f * r), Size(1.4f * r, 0.9f * r), style = Stroke(w * 0.7f))
            }
            "Lifesteal" -> { // kan damlası + diş
                val d = Path().apply {
                    moveTo(c.x, c.y - 0.85f * r)
                    cubicTo(c.x + 0.7f * r, c.y - 0.1f * r, c.x + 0.6f * r, c.y + 0.75f * r, c.x, c.y + 0.75f * r)
                    cubicTo(c.x - 0.6f * r, c.y + 0.75f * r, c.x - 0.7f * r, c.y - 0.1f * r, c.x, c.y - 0.85f * r)
                }
                drawPath(d, Color(0xFFE04848))
                drawPath(path(-0.25f to 0.05f, -0.1f to 0.05f, -0.17f to 0.4f), Color.White)
                drawPath(path(0.1f to 0.05f, 0.25f to 0.05f, 0.17f to 0.4f), Color.White)
            }
            "HpFlat" -> heart(c, r, col)
            "LastBreath" -> { // kalp + hale
                heart(Offset(c.x, c.y + 0.12f * r), r * 0.85f, col)
                drawOval(Color(0xFFFFE680), Offset(c.x - 0.5f * r, c.y - 0.95f * r), Size(1f * r, 0.32f * r), style = Stroke(w * 0.8f))
            }
            "Regen" -> { // artı + yaprak
                drawLine(col, p(-0.2f, -0.65f), p(-0.2f, 0.45f), w * 2f); drawLine(col, p(-0.75f, -0.1f), p(0.35f, -0.1f), w * 2f)
                drawOval(col, Offset(c.x + 0.25f * r, c.y + 0.2f * r), Size(0.55f * r, 0.35f * r))
            }
            "DmgTaken" -> shield(c, r, col, dark)
            "Reflect" -> { // kalkan + seken ok
                shield(c, r * 0.9f, col, dark)
                drawLine(Color.White, p(-0.95f, -0.8f), p(-0.05f, -0.1f), w)
                drawLine(Color.White, p(-0.05f, -0.1f), p(0.85f, -0.75f), w)
                drawPath(path(0.95f to -0.85f, 0.6f to -0.8f, 0.82f to -0.55f), Color.White)
            }
            "BlastRes" -> { // bomba + kalkan çizgisi
                drawCircle(col, 0.55f * r, Offset(c.x - 0.1f * r, c.y + 0.15f * r))
                drawLine(col, p(0.2f, -0.25f), p(0.5f, -0.6f), w * 1.2f)
                star(p(0.6f, -0.72f), 0.25f * r, Color(0xFFFFB040))
                drawArc(Color.White.copy(alpha = 0.7f), 200f, 70f, false, Offset(c.x - 0.5f * r, c.y - 0.25f * r), Size(0.6f * r, 0.6f * r), style = Stroke(w * 0.6f))
            }
            "Dodge" -> { // hayalet
                val g = Path().apply {
                    moveTo(c.x - 0.6f * r, c.y + 0.8f * r)
                    lineTo(c.x - 0.6f * r, c.y - 0.1f * r)
                    cubicTo(c.x - 0.6f * r, c.y - 0.95f * r, c.x + 0.6f * r, c.y - 0.95f * r, c.x + 0.6f * r, c.y - 0.1f * r)
                    lineTo(c.x + 0.6f * r, c.y + 0.8f * r)
                    lineTo(c.x + 0.3f * r, c.y + 0.55f * r); lineTo(c.x, c.y + 0.8f * r); lineTo(c.x - 0.3f * r, c.y + 0.55f * r); close()
                }
                drawPath(g, col)
                drawCircle(dark, 0.12f * r, p(-0.22f, -0.15f)); drawCircle(dark, 0.12f * r, p(0.22f, -0.15f))
            }
            "Speed" -> { // kanatlı bot
                drawPath(path(-0.45f to -0.7f, 0.05f to -0.7f, 0.05f to 0.25f, 0.75f to 0.4f, 0.75f to 0.75f, -0.45f to 0.75f), col)
                for (i in 0..2) drawLine(col.copy(alpha = 0.85f), p(-0.5f, -0.5f + i * 0.22f), p(-0.95f, -0.65f + i * 0.2f), w * 0.9f, StrokeCap.Round)
            }
            "RollCd" -> { // dönen oklar
                drawArc(col, -60f, 260f, false, Offset(c.x - 0.65f * r, c.y - 0.65f * r), Size(1.3f * r, 1.3f * r), style = Stroke(w * 1.4f))
                val a = (200f * PI / 180f).toFloat()
                val tip = Offset(c.x + cos(a) * 0.65f * r, c.y + sin(a) * 0.65f * r)
                drawPath(Path().apply { moveTo(tip.x - 0.35f * r, tip.y - 0.05f * r); lineTo(tip.x + 0.1f * r, tip.y - 0.35f * r); lineTo(tip.x + 0.15f * r, tip.y + 0.2f * r); close() }, col)
            }
            "Stamina" -> { // rüzgâr çizgileri
                for (i in 0..2) drawArc(col, 180f, 200f, false, Offset(c.x - (0.75f - i * 0.12f) * r, c.y + (-0.7f + i * 0.45f) * r),
                    Size((1.3f - i * 0.25f) * r, 0.5f * r), style = Stroke(w * 1.1f, cap = StrokeCap.Round))
            }
            "IFrame" -> { // kum saati
                drawPath(path(-0.55f to -0.8f, 0.55f to -0.8f, 0f to 0f), col)
                drawPath(path(-0.55f to 0.8f, 0.55f to 0.8f, 0f to 0f), col)
                drawLine(col, p(-0.65f, -0.85f), p(0.65f, -0.85f), w * 1.2f); drawLine(col, p(-0.65f, 0.85f), p(0.65f, 0.85f), w * 1.2f)
            }
            else -> { // merkez: kafatası
                drawCircle(col, 0.6f * r, Offset(c.x, c.y - 0.12f * r))
                drawRoundRect(col, Offset(c.x - 0.35f * r, c.y + 0.2f * r), Size(0.7f * r, 0.45f * r), androidx.compose.ui.geometry.CornerRadius(0.1f * r))
                drawCircle(dark, 0.17f * r, p(-0.22f, -0.15f)); drawCircle(dark, 0.17f * r, p(0.22f, -0.15f))
                drawPath(path(0f to 0.05f, -0.08f to 0.22f, 0.08f to 0.22f), dark)
            }
        }
    }

    private fun DrawScope.star(c: Offset, r: Float, col: Color) {
        val pp = Path()
        for (i in 0 until 10) {
            val a = -PI.toFloat() / 2 + i * PI.toFloat() / 5; val rr = if (i % 2 == 0) r else r * 0.45f
            val x = c.x + cos(a) * rr; val y = c.y + sin(a) * rr
            if (i == 0) pp.moveTo(x, y) else pp.lineTo(x, y)
        }
        pp.close(); drawPath(pp, col)
    }

    private fun DrawScope.heart(c: Offset, r: Float, col: Color) {
        val h = Path().apply {
            moveTo(c.x, c.y + 0.8f * r)
            cubicTo(c.x - 1.1f * r, c.y, c.x - 0.6f * r, c.y - 0.95f * r, c.x, c.y - 0.35f * r)
            cubicTo(c.x + 0.6f * r, c.y - 0.95f * r, c.x + 1.1f * r, c.y, c.x, c.y + 0.8f * r)
            close()
        }
        drawPath(h, col)
        drawCircle(Color.White.copy(alpha = 0.55f), 0.13f * r, Offset(c.x - 0.38f * r, c.y - 0.3f * r))
    }

    private fun DrawScope.shield(c: Offset, r: Float, col: Color, dark: Color) {
        val s = Path().apply {
            moveTo(c.x, c.y - 0.85f * r)
            lineTo(c.x + 0.7f * r, c.y - 0.55f * r)
            cubicTo(c.x + 0.7f * r, c.y + 0.25f * r, c.x + 0.35f * r, c.y + 0.65f * r, c.x, c.y + 0.9f * r)
            cubicTo(c.x - 0.35f * r, c.y + 0.65f * r, c.x - 0.7f * r, c.y + 0.25f * r, c.x - 0.7f * r, c.y - 0.55f * r)
            close()
        }
        drawPath(s, col)
        drawLine(dark, Offset(c.x, c.y - 0.7f * r), Offset(c.x, c.y + 0.7f * r), r * 0.1f)
    }

    /** Anahtar düğüm çerçevesi: dikenli sekizgen. */
    fun DrawScope.keystoneFrame(c: Offset, r: Float, fill: Color, edge: Color, width: Float, spin: Float) {
        rotate(spin, c) {
            val pp = Path()
            for (i in 0 until 16) {
                val a = i * PI.toFloat() / 8 + PI.toFloat() / 16
                val rr = if (i % 2 == 0) r * 1.18f else r * 0.98f
                val x = c.x + cos(a) * rr; val y = c.y + sin(a) * rr
                if (i == 0) pp.moveTo(x, y) else pp.lineTo(x, y)
            }
            pp.close()
            drawPath(pp, fill)
            drawPath(pp, edge, style = Stroke(width))
        }
    }

    private fun Color.lighten(f: Float) = Color(red + (1f - red) * f, green + (1f - green) * f, blue + (1f - blue) * f, alpha)
    private fun Color.darken(f: Float) = Color(red * (1f - f), green * (1f - f), blue * (1f - f), alpha)

    /**
     * V18 düğüm gövdesi: gölge, metal çerçeve (açık: altın, alınabilir: aile renginde, kilitli: çelik), mücevher yuva, parlak yansıma.
     * k: 0 küçük, 1 belirgin (çentikli halka), 2 anahtar (kıvılcımlı yıldız çerçeve, dönen ışık).
     */
    fun DrawScope.treeNode(p: Offset, r: Float, k: Int, own: Boolean, av: Boolean, fam: Color, pulse: Float, time: Float) {
        val metal = when {
            own -> listOf(Color(0xFFFFF4B8), Color(0xFFD9A22E), Color(0xFF7A5410), Color(0xFFF2CE5C), Color(0xFFFFF4B8))
            av -> listOf(fam.lighten(0.6f), fam, fam.darken(0.55f), fam.lighten(0.2f), fam.lighten(0.6f))
            else -> listOf(Color(0xFF7C7C84), Color(0xFF45454C), Color(0xFF26262B), Color(0xFF5E5E66), Color(0xFF7C7C84))
        }
        // gölge
        drawCircle(Color(0xA0000000), r * 1.16f, Offset(p.x, p.y + r * 0.14f))
        if (own) drawCircle(Brush.radialGradient(listOf(fam.copy(alpha = 0.6f), Color.Transparent), p, r * 2.6f), r * 2.6f, p)
        if (av) drawCircle(fam.copy(alpha = 0.2f + 0.4f * pulse), r * (1.42f + 0.14f * pulse), p, style = Stroke(r * 0.12f))
        when (k) {
            2 -> {
                // yıldız çerçeve: 8 sivri uç, çift katman; sahipse ışık dönerek uçlarda parlar
                rotate(if (own) time * 10f else 0f, p) {
                    val star = Path()
                    for (i in 0 until 16) {
                        val a = i * PI.toFloat() / 8 + PI.toFloat() / 16
                        val rr = if (i % 2 == 0) r * 1.32f else r * 1.02f
                        val x = p.x + cos(a) * rr; val y = p.y + sin(a) * rr
                        if (i == 0) star.moveTo(x, y) else star.lineTo(x, y)
                    }
                    star.close()
                    drawPath(star, Brush.sweepGradient(metal, p))
                    drawPath(star, Color(0xFF0A0908), style = Stroke(r * 0.07f))
                    for (i in 0 until 8) {
                        val a = i * PI.toFloat() / 4 + PI.toFloat() / 8
                        val q = Offset(p.x + cos(a) * r * 1.2f, p.y + sin(a) * r * 1.2f)
                        drawCircle(if (own) Color(0xFFFFFFFF) else metal[0], r * 0.07f, q)
                    }
                }
                drawCircle(Brush.sweepGradient(metal.reversed(), p), r * 0.96f, p)
            }
            1 -> {
                drawCircle(Brush.sweepGradient(metal, p), r * 1.08f, p)
                // çentikler: halkada 6 küçük kabartı
                for (i in 0 until 6) {
                    val a = i * PI.toFloat() / 3
                    drawCircle(metal[1], r * 0.1f, Offset(p.x + cos(a) * r * 1.08f, p.y + sin(a) * r * 1.08f))
                }
            }
            else -> drawCircle(Brush.sweepGradient(metal, p), r * 1.04f, p)
        }
        drawCircle(Color(0xFF0A0908), r * 0.84f, p)
        // mücevher yuva
        val inner = when {
            own -> listOf(fam.lighten(0.45f), fam, fam.darken(0.6f))
            av -> listOf(Color(0xFF2A261E), Color(0xFF16140F), Color(0xFF0C0B09))
            else -> listOf(Color(0xFF1B1A17), Color(0xFF111010), Color(0xFF090908))
        }
        drawCircle(Brush.radialGradient(inner, Offset(p.x - r * 0.2f, p.y - r * 0.25f), r * 0.95f), r * 0.78f, p)
        if (av) drawCircle(fam.copy(alpha = 0.35f), r * 0.78f, p, style = Stroke(r * 0.08f))
        // üst-sol yansıma
        drawArc(Color.White.copy(alpha = if (own) 0.45f else 0.18f), 200f, 70f, false, Offset(p.x - r * 0.62f, p.y - r * 0.62f), Size(r * 1.24f, r * 1.24f),
            style = Stroke(r * 0.1f, cap = StrokeCap.Round))
    }
}

