@Composable
private fun SupportTicket(o: JSONObject, open: Boolean, openPlayer: (Long) -> Unit, report: (String, Boolean) -> Unit, changed: () -> Unit) {
    var reply by remember { mutableStateOf("") }
    var images by remember { mutableStateOf<List<ImageBitmap>?>(null) }
    var loading by remember { mutableStateOf(false) }
    val paths = o.optJSONArray("paths")?.length() ?: 0
    var big by remember { mutableStateOf<ImageBitmap?>(null) }
    big?.let { b ->
        Dim({ big = null }) {
            androidx.compose.foundation.Image(b, null, Modifier.fillMaxSize().padding(16.dp), contentScale = ContentScale.Fit)
        }
    }
    Column(Modifier.fillMaxWidth().pxPanel(Px.PanelDark).padding(8.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            PT("#${o.optLong("id")} · ${o.optString("topic")}", 14.sp, Px.Clan, Modifier.weight(1f))
            PT(ts(o.optLong("at")), 11.sp, Px.Sub)
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            AccountCard(o.optJSONObject("from"), "Gönderen", openPlayer, Modifier.width(220.dp))
            Column(Modifier.weight(1f)) {
                PT(o.optString("body"), 12.sp, Px.Text, maxLines = 12)
                if (paths > 0) {
                    Spacer(Modifier.height(4.dp))
                    val imgs = images
                    if (imgs == null) PxButton(if (loading) "Yükleniyor…" else "$paths Fotoğrafı Göster", color = Px.Blue, height = 30.dp, size = 11.sp, enabled = !loading) {
                        loading = true
                        Support.adminPhotos(o.optLong("id")) { r ->
                            r.onSuccess { urls ->
                                com.zenvex.online.Supa.bg {
                                    val out = urls.mapNotNull { u ->
                                        runCatching { java.net.URL(u).openStream().use { android.graphics.BitmapFactory.decodeStream(it) }?.asImageBitmap() }.getOrNull()
                                    }
                                    android.os.Handler(android.os.Looper.getMainLooper()).post { images = out; loading = false }
                                }
                            }.onFailure { loading = false; report(it.message ?: "", false) }
                        }
                    } else Row(Modifier.horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        if (imgs.isEmpty()) PT("Fotoğraflar Açılamadı", 11.sp, Px.Hard)
                        // dokununca tam ekran
                        for (b in imgs) androidx.compose.foundation.Image(b, null, Modifier.height(140.dp).width(100.dp).clickable { big = b }, contentScale = ContentScale.Fit)
                    }
                } else if (o.optInt("photos") > 0) {
                    Spacer(Modifier.height(4.dp))
                    PT("${o.optInt("photos")} Fotoğraf Eklenmişti Ama Yüklenemedi", 11.sp, Px.Hard)
                }
            }
        }
        if (open) {
            Spacer(Modifier.height(4.dp))
            Field(reply, { if (it.length <= 2000) reply = it }, "Yanıt (posta olarak gider)", Modifier.fillMaxWidth())
            Spacer(Modifier.height(4.dp))
            PxButton("Yanıtla ve Kapat", color = Px.Green, height = 34.dp, size = 12.sp, enabled = reply.isNotBlank()) {
                Support.adminReply(o.optLong("id"), reply) { r -> r.onSuccess { report(it, true); changed() }.onFailure { report(it.message ?: "", false) } }
            }
        } else PT("Yanıt: ${o.optString("reply")}", 11.sp, Px.Sub, maxLines = 4)
    }
}

/** Yönetici Ekonomi sekmesi (R45): satışlar, sunucunun verdiği altın/elmas, ürün dağılımı, son satın almalar, en zenginler */
@Composable
internal fun AdminEconomyTab(open: (Long) -> Unit, report: (String, Boolean) -> Unit) {
    var d by remember { mutableStateOf<JSONObject?>(null) }
    LaunchedEffect(Unit) {
        com.zenvex.online.Supa.rpc("zx_admin_economy", Account.authJson()) { r ->
            r.onSuccess { d = JSONObject(it) }.onFailure { report(it.message ?: "", false) }
        }
    }
    val o = d ?: run { PT("Yükleniyor…", 13.sp, Px.Sub); return }
    fun money(j: JSONObject?) = "${j?.optInt("n") ?: 0} satış · ₺${"%.2f".format(j?.optDouble("try") ?: 0.0).replace('.', ',')}"
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        for ((label, k) in listOf("Son 24 Saat" to "sales_24h", "Son 7 Gün" to "sales_7d", "Tümü" to "sales_all")) {
            Column(Modifier.weight(1f).pxPanel(Px.PanelDark).padding(8.dp)) { PT(label, 11.sp, Px.Sub); PT(money(o.optJSONObject(k)), 14.sp, Px.Clan) }
        }
        val g = o.optJSONObject("grants_24h")
        Column(Modifier.weight(1f).pxPanel(Px.PanelDark).padding(8.dp)) {
            PT("Sunucu Verdi (24 Saat)", 11.sp, Px.Sub)
            PT("${fmtMoney(g?.optLong("gold") ?: 0)} Altın · ${g?.optLong("gems") ?: 0} Elmas", 13.sp, Px.Text)
        }
    }
    Spacer(Modifier.height(8.dp))
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        Column(Modifier.weight(1f)) {
            PT("En Zengin 20", 14.sp, Px.Clan)
            for ((i, r) in o.optJSONArray("richest").objs().withIndex()) {
                Row(Modifier.fillMaxWidth().clickable { open(r.optLong("id")) }.padding(vertical = 2.dp)) {
                    PT("${i + 1}. ${r.optString("name")} (${r.optString("server")}, Sv ${r.optInt("level")})", 12.sp, Px.Text, Modifier.weight(1f), maxLines = 1)
                    PT("${fmtMoney(r.optLong("gold"))} · ${r.optLong("gems")}◆", 12.sp, Px.Clan)
                }
            }
        }
        Column(Modifier.weight(1f)) {
            PT("Ürünler", 14.sp, Px.Clan)
            val ps = o.optJSONArray("products").objs()
            if (ps.isEmpty()) PT("Henüz satış yok", 12.sp, Px.Sub)
            for (p in ps) PT("${p.optString("id")}: ${p.optInt("n")} · ₺${"%.2f".format(p.optDouble("try")).replace('.', ',')}", 12.sp, Px.Text)
            Spacer(Modifier.height(6.dp))
            PT("Son Satın Almalar", 14.sp, Px.Clan)
            for (p in o.optJSONArray("recent").objs()) {
                PT("${ts(p.optLong("at"))} · ${p.optString("name")} · ${p.optString("product")}" + if (p.optBoolean("test")) " (test)" else "", 11.sp,
                    if (p.optBoolean("test")) Px.Sub else Px.Text, maxLines = 1)
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/ui/TreeScreen.kt
// ====================================================================================================

/**
 * Gelişim ekranı: "Skill Ağacı" (düğümler elmasla açılır, bağlı düğümden ilerlenir) ve "Savaşçı" (karakter seviyesi 1–10).
 */
@Composable
fun TreeScreen(close: () -> Unit) {
    var tick by remember { mutableIntStateOf(0) }
    val data = remember(tick) { GameSession.ui("tree") }
    Box(Modifier.fillMaxSize().background(Color(0xF2141310))) {
        Column(Modifier.fillMaxSize().padding(10.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                PxIcon("close", size = 40.dp) { close() }
                Spacer(Modifier.width(10.dp))
                PT("YETENEK AĞACI", 24.sp, Px.Clan, outline = true)
                Spacer(Modifier.weight(1f))
                run {
                    Icon("gem", 22.dp, Color(0xFF7FE0FF))
                    Spacer(Modifier.width(4.dp))
                    PT(fmt(data.optInt("gems")), 20.sp, Color(0xFF7FE0FF))
                    if (data.optInt("credit") > 0) { Spacer(Modifier.width(8.dp)); PT("+ ${fmt(data.optInt("credit"))} Kredi", 14.sp, Px.Clan) }
                    Spacer(Modifier.width(10.dp))
                    var confirm by remember { mutableStateOf(false) }
                    PxButton(if (confirm) "Emin Misin? Elmaslar Kredi Olur" else "Sıfırla (${fmt(data.optInt("reset_cost"))} Altın)", color = Px.Red, size = 13.sp, height = 36.dp) {
                        if (!confirm) { confirm = true; return@PxButton }
                        confirm = false
                        val r = GameSession.cmd("tree_reset"); Toaster.show(r.msg, r.ok); tick++
                    }
                }
            }
            Spacer(Modifier.height(8.dp))
            TreeView(data) { tick++ }
        }
    }
}

@Composable
internal fun TreeView(data: JSONObject, changed: () -> Unit) {
    val nodes = remember(data) { data.optJSONArray("nodes").objs() }
    val byId = remember(nodes) { nodes.associateBy { it.optInt("id") } }
    val ctx = androidx.compose.ui.platform.LocalContext.current
    val skillArt = remember(nodes) { nodes.mapNotNull { it.optString("s").takeIf { s -> s.isNotEmpty() } }.distinct()
        .mapNotNull { s -> UiArt.image(ctx, "skill_" + s.lowercase())?.let { s to it } }.toMap() }
    var zoom by remember { mutableFloatStateOf(0.85f) }
    var pan by remember { mutableStateOf(Offset.Zero) }
    var sel by remember { mutableIntStateOf(-1) }
    // açılış patlaması: (düğüm, başlangıç zamanı)
    var burst by remember { mutableStateOf(-1 to 0f) }
    val haptic = LocalHapticFeedback.current
    // yıldız tozu: (x, y, parlaklık) üçlüleri, birim cinsinden
    val stars = remember { val r = java.util.Random(31); FloatArray(150 * 3) { i -> if (i % 3 == 2) r.nextFloat() else (r.nextFloat() - 0.5f) * 34f } }
    val time by produceState(0f) {
        val start = withFrameNanos { it }
        while (true) withFrameNanos { value = (it - start) / 1e9f }
    }
    Row(Modifier.fillMaxSize()) {
        Box(
            Modifier.weight(1f).fillMaxHeight().clip(androidx.compose.foundation.shape.RoundedCornerShape(4.dp)).background(Color(0xFF0E0D0B))
                .pointerInput(Unit) {
                    detectTransformGestures { _, p, z, _ -> zoom = (zoom * z).coerceIn(0.35f, 2.5f); pan += p }
                },
        ) {
            Canvas(
                Modifier.fillMaxSize().pointerInput(nodes) {
                    detectTapGestures { o ->
                        val unit = 46.dp.toPx() * zoom
                        val c = Offset(size.width / 2f, size.height / 2f) + pan
                        val hit = nodes.minByOrNull { n ->
                            hypot(c.x + n.optDouble("x").toFloat() * unit - o.x, c.y + n.optDouble("y").toFloat() * unit - o.y)
                        }
                        if (hit != null && hypot(c.x + hit.optDouble("x").toFloat() * unit - o.x, c.y + hit.optDouble("y").toFloat() * unit - o.y) < 26.dp.toPx() * zoom.coerceAtLeast(0.7f))
                            sel = hit.optInt("id")
                    }
                },
            ) {
                val unit = 46.dp.toPx() * zoom
                val c = Offset(size.width / 2f, size.height / 2f) + pan
                fun pos(n: JSONObject) = Offset(c.x + n.optDouble("x").toFloat() * unit, c.y + n.optDouble("y").toFloat() * unit)
                // arka plan: merkez ışığı + 5/10/15 derinlik halkaları (anahtar düğüm kademeleri)
                drawCircle(Brush.radialGradient(listOf(Color(0x332A2418), Color.Transparent), c, unit * 17f), unit * 17f, c)
                // dal bulutsuları: her dal kendi renginde uzaktan parlar (yukarı hasar, sağ silah, aşağı can, sol çeviklik)
                for ((bx, by, fc) in listOf(Triple(0f, -9f, SkillGlyphs.Damage), Triple(9f, 0f, SkillGlyphs.Weapon), Triple(0f, 9f, SkillGlyphs.Life), Triple(-9f, 0f, SkillGlyphs.Agility))) {
                    val bc = Offset(c.x + bx * unit, c.y + by * unit)
                    drawCircle(Brush.radialGradient(listOf(fc.copy(alpha = 0.16f), Color.Transparent), bc, unit * 9f), unit * 9f, bc)
                }
                // yıldız tozu: sabit dağılım, yavaş titrer (kaydırınca hafif paralaks)
                for (sIdx in stars.indices step 3) {
                    val sx = c.x * 0.85f + stars[sIdx] * unit * 1.15f; val sy = c.y * 0.85f + stars[sIdx + 1] * unit * 1.15f
                    val tw = 0.35f + 0.65f * (0.5f + 0.5f * sin(time * (0.8f + stars[sIdx + 2] * 1.4f) + sIdx))
                    drawCircle(Color.White.copy(alpha = 0.10f + 0.28f * tw * stars[sIdx + 2]), (0.5f + 1.1f * stars[sIdx + 2]).dp.toPx(), Offset(sx, sy))
                }
                for (d in listOf(5f, 10f, 15f)) drawCircle(Color(0x14F6E05A), unit * d, c, style = Stroke(1.dp.toPx(),
                    pathEffect = PathEffect.dashPathEffect(floatArrayOf(6.dp.toPx(), 8.dp.toPx()), time * 12f)))
                // bağlantılar
                for (n in nodes) {
                    val a = pos(n)
                    val links = n.optJSONArray("links") ?: continue
                    for (i in 0 until links.length()) {
                        val o = byId[links.getInt(i)] ?: continue
                        if (o.optInt("id") < n.optInt("id")) continue
                        val b = pos(o)
                        val oa = n.optBoolean("own"); val ob = o.optBoolean("own")
                        when {
                            oa && ob -> {
                                // enerji ışını: geniş yumuşak hale, altın gövde, beyaz öz; üstünde akan parlak zerreler
                                val zk = zoom.coerceIn(0.6f, 1.2f)
                                drawLine(Color(0x26F6E05A), a, b, 16.dp.toPx() * zk, StrokeCap.Round)
                                drawLine(Color(0x70F6C42A), a, b, 7.dp.toPx() * zk, StrokeCap.Round)
                                drawLine(Color(0xFFFFF2B0), a, b, 2.6.dp.toPx(), StrokeCap.Round)
                                val ph = ((n.optInt("id") * 37 + o.optInt("id") * 11) % 100) / 100f
                                for (k in 0..2) {
                                    val f = (time * 0.55f + ph + k / 3f) % 1f
                                    val q = Offset(a.x + (b.x - a.x) * f, a.y + (b.y - a.y) * f)
                                    drawCircle(Color(0x55FFF6C0), 6.dp.toPx() * zk, q)
                                    drawCircle(Color.White, 2.4.dp.toPx(), q)
                                }
                            }
                            oa || ob -> {
                                val fc = SkillGlyphs.family((if (oa) o else n).optString("s"))
                                drawLine(fc.copy(alpha = 0.85f), a, b, 2.5.dp.toPx(),
                                    pathEffect = PathEffect.dashPathEffect(floatArrayOf(5.dp.toPx(), 5.dp.toPx()), -time * 20f))
                            }
                            else -> drawLine(Color(0xFF34322B), a, b, 2.dp.toPx())
                        }
                    }
                }
                // düğümler
                val pulse = 0.5f + 0.5f * sin(time * 4.5f)
                for (n in nodes) {
                    val p = pos(n)
                    val k = n.optInt("k")
                    val zs = zoom.coerceIn(0.6f, 1.5f)
                    val r = (if (k == 2) 23.dp else if (k == 1) 18.dp else 14.dp).toPx() * zs
                    val stat = if (n.optInt("id") == 0) "core" else n.optString("s")
                    val fam = SkillGlyphs.family(stat)
                    val own = n.optBoolean("own"); val av = n.optBoolean("av")
                    with(SkillGlyphs) { treeNode(p, r, k, own, av, fam, pulse, time) }
                    // simge: koyu gölge + renkli çizim (açıkken beyaza yakın parlak, alınabilirken aile renginde, kilitliyken soluk)
                    val gc = when { own -> Color(0xFFFFFFFF); av -> fam.copy(alpha = 0.95f); else -> Color(0xFF6A675C) }
                    // V20: assets/ui/skill_<istatistik>.png varsa o görsel (kilitliyken soluk), yoksa kodla çizilen simge
                    val art = skillArt[stat]
                    if (art != null) {
                        val d = (r * 1.25f).toInt()
                        drawImage(art, IntOffset.Zero, IntSize(art.width, art.height), IntOffset((p.x - d / 2f).toInt(), (p.y - d / 2f).toInt()), IntSize(d, d),
                            alpha = if (own) 1f else if (av) 0.85f else 0.35f, filterQuality = androidx.compose.ui.graphics.FilterQuality.Medium)
                    } else with(SkillGlyphs) {
                        if (own || av) glyph(stat, Offset(p.x + r * 0.03f, p.y + r * 0.05f), r * 0.6f, Color(0xAA000000))
                        glyph(stat, p, r * 0.6f, gc)
                    }
                    if (n.optInt("id") == sel) drawCircle(Color.White, r + 6.dp.toPx(), p, style = Stroke(2.dp.toPx(),
                        pathEffect = PathEffect.dashPathEffect(floatArrayOf(4.dp.toPx(), 4.dp.toPx()), time * 30f)))
                }
                // açılış patlaması: genişleyen halka + saçılan kıvılcımlar
                val (bid, bt) = burst
                val bn = byId[bid]
                if (bn != null && time - bt < 0.7f) {
                    val e = (time - bt) / 0.7f
                    val p = pos(bn); val fam = SkillGlyphs.family(bn.optString("s"))
                    drawCircle(Color.White.copy(alpha = 1f - e), 18.dp.toPx() * (1f + 2f * e), p, style = Stroke(3.dp.toPx() * (1f - e) + 1f))
                    for (i in 0 until 16) {
                        val ang = i * 6.2832f / 16 + bid
                        val d = 60.dp.toPx() * e
                        drawCircle(fam.copy(alpha = 1f - e), 3.dp.toPx() * (1f - e * 0.5f), Offset(p.x + cos(ang) * d, p.y + sin(ang) * d + 30.dp.toPx() * e * e))
                    }
                }
            }
            // dal adları
            Column(Modifier.align(Alignment.BottomStart).padding(8.dp)) {
                val br = data.optJSONArray("branches")
                val fams = listOf(SkillGlyphs.Damage, SkillGlyphs.Weapon, SkillGlyphs.Life, SkillGlyphs.Agility)
                for (i in 0 until (br?.length() ?: 0)) Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(Modifier.size(10.dp).clip(CircleShape).background(fams[i]))
                    Spacer(Modifier.width(6.dp))
                    PT(br!!.getString(i) + listOf(" ↑", " →", " ↓", " ←")[i], 12.sp)
                }
            }
            PT("İki parmakla yakınlaştır / kaydır", 11.sp, Px.Sub, Modifier.align(Alignment.TopCenter).padding(6.dp))
        }
        Spacer(Modifier.width(8.dp))
        // seçili düğüm
        PxPanel(Modifier.width(230.dp).fillMaxHeight(), pad = 10.dp) {
            val n = byId[sel]
            if (n == null) {
                PT("Bir düğüme dokun", 16.sp, Px.Sub)
                Spacer(Modifier.height(8.dp))
                PT("Düğümler elmasla açılır. Ortadan başla, açık bir düğüme bağlı olanları alabilirsin. Her seviye ayrıca +5 Can ve +1 Yumruk Hasarı verir. Sıfırlayınca harcadığın elmas kredi olarak kalır.",
                    13.sp, Px.Text, maxLines = 8)
                Spacer(Modifier.height(10.dp))
                for (st in listOf("FistPct" to "Hasar", "Crit" to "Kritik", "BladePct" to "Silah", "HpFlat" to "Can", "DmgTaken" to "Savunma", "Dodge" to "Çeviklik"))
                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(vertical = 2.dp)) {
                        Canvas(Modifier.size(22.dp)) { with(SkillGlyphs) { glyph(st.first, center, size.minDimension * 0.42f, family(st.first)) } }
                        Spacer(Modifier.width(8.dp)); PT(st.second, 13.sp, SkillGlyphs.family(st.first))
                    }
            } else {
                val k = n.optInt("k")
                val stat = if (n.optInt("id") == 0) "core" else n.optString("s")
                val fam = SkillGlyphs.family(stat)
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Canvas(Modifier.size(64.dp)) {
                        val r = size.minDimension * 0.32f
                        val own = n.optBoolean("own"); val av = n.optBoolean("av")
                        with(SkillGlyphs) {
                            treeNode(center, r, k, own, av, fam, 0.5f, time)
                            glyph(stat, Offset(center.x + r * 0.03f, center.y + r * 0.05f), r * 0.6f, Color(0xAA000000))
                            glyph(stat, center, r * 0.6f, if (own) Color.White else fam)
                        }
                    }
                    Spacer(Modifier.width(8.dp))
                    Column {
                        PT(listOf("Küçük", "Belirgin", "ANAHTAR")[k.coerceIn(0, 2)], 12.sp, if (k == 2) Px.Clan else Px.Sub)
                        PT(SkillGlyphs.familyName(stat), 12.sp, fam)
                    }
                }
                Spacer(Modifier.height(4.dp))
                PT(n.optString("name"), 18.sp, maxLines = 3)
                Spacer(Modifier.height(4.dp))
                PT(n.optString("desc"), 14.sp, Px.Name, maxLines = 4)
                Spacer(Modifier.weight(1f))
                when {
                    n.optBoolean("own") -> PT("✔ Açık", 16.sp, Px.Name)
                    n.optBoolean("av") && data.optInt("level") < n.optInt("req") -> PT("Seviye ${n.optInt("req")} Gerekli", 14.sp, Px.Orange)
                    n.optBoolean("av") -> PxButton("Aç · ${fmt(n.optInt("cost"))} Elmas", Modifier.fillMaxWidth(), Px.Green, icon = "gem", size = 16.sp,
                        enabled = data.optInt("gems") + data.optInt("credit") >= n.optInt("cost")) {
                        val r = GameSession.cmd("tree_unlock", "id" to n.optInt("id")); Toaster.show(r.msg, r.ok)
                        if (r.ok) { burst = n.optInt("id") to time; haptic.performHapticFeedback(HapticFeedbackType.LongPress) }
                        changed()
                    }
                    else -> PT("Önce bağlı bir düğümü aç", 13.sp, Px.Sub, maxLines = 2)
                }
            }
        }
    }
}

// ====================================================================================================
// com/zenvex/online/ui/Tutorial.kt
// ====================================================================================================

/** Öğretici katmanı: adım okuma, ekran rect'i kaydı ve parlak çerçeve + zıplayan ok + açıklama kartı çizimi */
object Tut {
    /** Şu an etkin (kabul edilmiş, bitmemiş) rehber adımının kimliği; yoksa boş */
    fun step(): String {
        val a = GameSession.ui("quests").optJSONArray("story") ?: return ""
        for (i in 0 until a.length()) {
            val q = a.optJSONObject(i) ?: continue
            if (q.optBoolean("guide") && q.optBoolean("on") && !q.optBoolean("ready")) return q.optString("id")
        }
        return ""
    }

    /** Etkin üretim görevinin istediği eşya ve tezgâh tarifi mi (rehber önce; yoksa null) */
    fun craftWant(): Pair<String, Boolean>? {
        val a = GameSession.ui("quests").optJSONArray("story") ?: return null
        val qs = (0 until a.length()).mapNotNull { a.optJSONObject(it) }.filter { it.optBoolean("on") && !it.optBoolean("ready") && it.has("craft") }
        val q = qs.firstOrNull { it.optBoolean("guide") } ?: qs.firstOrNull() ?: return null
        return q.optString("craft") to q.optBoolean("bench")
    }

    /** Olayı oyuna bildirir (görev hedefi "Ping"); bilinmeyen ad Rust'ta yok sayılır */
    fun ping(name: String) { GameSession.cmdNoSave("story_ping", "name" to name) }
}

/**
 * Parlatılacak bir ekran bölgesi: [rect] kök koordinatında (boundsInRoot), [label] kısa yazı. [tap]: dokunulacak yer
 * (parmak ucu ortasına inen el); değilse eşyanın varacağı yer (ok).
 */
class TutTarget(val rect: Rect?, val label: String, val below: Boolean = false, val tap: Boolean = true)

/**
 * Bir bileşenin kök koordinatındaki dikdörtgenini [map] içine yazar. [map] durum haritası olmalı (mutableStateMapOf):
 * yeni sekme/tarif ilk kez yerleşince işaret hemen çizilsin (düz HashMap'te başka bir yere dokunana dek görünmüyordu).
 */
fun Modifier.tutRect(map: MutableMap<String, Rect>, key: String): Modifier = onGloballyPositioned {
    val b = it.boundsInRoot()
    if (map[key] != b) map[key] = b
}

/**
 * Hedeflerin çevresine nabız gibi atan altın çerçeve ve ok çizer; [text] varsa sol üstte açıklama kartı gösterir.
 * Ekranı kaplayan bir Box içinde, her şeyin üstünde çağrılır (dokunuşları yutmaz).
 */
@Composable
fun TutLayer(targets: List<TutTarget>, text: String?, cardStart: Int = 230, cardEnd: Int = 340) {
    if (targets.isEmpty() && text == null) return
    val t = rememberTime()
    var root by remember { mutableStateOf(Offset.Zero) }
    val dn = LocalDensity.current
    Box(Modifier.fillMaxSize().onGloballyPositioned { root = it.positionInRoot() }) {
        for (g in targets) {
            val r = g.rect ?: continue
            TutMark(r, root, g.label, g.below, g.tap, t, dn)
        }
        if (text != null) {
            Box(Modifier.align(Alignment.TopStart).padding(start = cardStart.dp, end = cardEnd.dp, top = 4.dp)
                .clip(RoundedCornerShape(6.dp)).background(Color(0xE8241E10))
                .border(1.5.dp, Color(0xFFFFD34A).copy(alpha = 0.7f + 0.3f * sin(t * 4f)), RoundedCornerShape(6.dp))
                .padding(horizontal = 8.dp, vertical = 3.dp)) {
                PT(text, 10.5.sp, Color(0xFFFFF0C0), maxLines = 3)
            }
        }
    }
}

@Composable
private fun TutMark(r: Rect, root: Offset, label: String, below: Boolean, tap: Boolean, t: Float, dn: androidx.compose.ui.unit.Density) {
    val pad = with(dn) { 3.dp.toPx() }
    val x = r.left - root.x - pad; val y = r.top - root.y - pad
    val w = r.width + pad * 2; val h = r.height + pad * 2
    val pulse = 0.5f + 0.5f * sin(t * 5f)
    val gold = Color(0xFFFFD34A)
    Box(Modifier.offset { androidx.compose.ui.unit.IntOffset(x.roundToInt(), y.roundToInt()) }
        .size(with(dn) { w.toDp() }, with(dn) { h.toDp() })) {
        Canvas(Modifier.fillMaxSize()) {
            val rr = CornerRadius(6.dp.toPx())
            // dış parıltı: üç halka, nabızla genişleyip sönen
            for (k in 3 downTo 1) {
                val g = k * 3.dp.toPx() * (0.7f + 0.6f * pulse)
                drawRoundRect(gold.copy(alpha = (0.16f - k * 0.035f) * (0.6f + 0.8f * pulse)), Offset(-g, -g), Size(size.width + g * 2, size.height + g * 2),
                    rr, Stroke(3.dp.toPx()))
            }
            drawRoundRect(Color(0xFFFFE08A).copy(alpha = 0.65f + 0.35f * pulse), Offset.Zero, size, rr, Stroke(2.5.dp.toPx()))
            drawRoundRect(gold.copy(alpha = 0.10f + 0.10f * pulse), Offset.Zero, size, rr)
        }
        if (tap) {
            // dokun eli: parmak ucu hedefin ortasına iner (tut_hand), etiket hedefin üstünde/altında
            TutTap(label, above = !below)
        } else {
            val bounce = ((1f + sin(t * 5f)) * 3).dp
            Column(Modifier.align(if (below) Alignment.BottomCenter else Alignment.TopCenter)
                .offset(y = if (below) 4.dp + bounce else (-4).dp - bounce).tutAnchor(0.5f, if (below) 0f else 1f),
                horizontalAlignment = Alignment.CenterHorizontally) {
                if (below) Arrow(true, pulse)
                if (label.isNotEmpty()) Box(Modifier.clip(RoundedCornerShape(10.dp)).background(Color(0xE0101010)).border(1.dp, gold.copy(alpha = 0.6f), RoundedCornerShape(10.dp))
                    .padding(horizontal = 9.dp, vertical = 2.dp)) { PT(label, 12.sp, Color(0xFFFFF0C0)) }
                if (!below) Arrow(false, pulse)
            }
        }
    }
}

@Composable
private fun Arrow(up: Boolean, pulse: Float) {
    Canvas(Modifier.size(18.dp, 14.dp)) {
        val p = Path().apply {
            if (up) { moveTo(size.width / 2, 0f); lineTo(0f, size.height); lineTo(size.width / 2, size.height * 0.6f); lineTo(size.width, size.height) }
            else { moveTo(size.width / 2, size.height); lineTo(0f, 0f); lineTo(size.width / 2, size.height * 0.4f); lineTo(size.width, 0f) }
            close()
        }
        drawPath(p, Color(0xFFFFD34A).copy(alpha = 0.75f + 0.25f * pulse))
        drawPath(p, Color(0xB015140F), style = Stroke(1.5f))
    }
}

/**
 * Öğretici konuşma balonu (V19): eskiden oyun tuvalinde çiziliyordu ve üstteki arayüz katmanlarının (kontrol rehberi,
 * pencereler) arkasında kalıyordu. Şimdi HUD'ın en üst katmanında: GameView metni ve konumu HudLayout'a yazar.
 */
@Composable
fun GuideBubble() {
    rememberTime() // her karede yeniden okunur (HudLayout değerleri Compose durumu değil)
    val msg = com.zenvex.online.HudLayout.tutMsg
    val a = com.zenvex.online.HudLayout.tutAlpha
    if (msg.isEmpty() || a <= 0.01f) return
    val diana = com.zenvex.online.HudLayout.tutDiana
    androidx.compose.foundation.layout.BoxWithConstraints(Modifier.fillMaxSize()) {
        // sol üst kısayol satırının (y ≈ 84-130 dp, işaret etiketi dahil) ve sağ üst para kapsülünün altında: tuşları örtmez
        val top = maxOf(maxHeight * com.zenvex.online.HudLayout.tutTop, 158.dp)
        androidx.compose.foundation.layout.Row(Modifier.align(Alignment.TopStart).padding(start = 16.dp, top = top + ((1f - a) * -10f).dp)
            .alpha(a), verticalAlignment = Alignment.Top) {
            Column(Modifier.widthIn(max = 300.dp).clip(RoundedCornerShape(8.dp)).background(Color(0xE6141310))
                .border(1.5.dp, Color(0xFF6A5A3A), RoundedCornerShape(8.dp)).padding(horizontal = 12.dp, vertical = 7.dp)) {
                PT(if (diana) "Komutan Diana" else "İlk Adımlar", 12.sp, Color(0xFFFFD34A))
                PT(msg, 13.sp, Color(0xFFF2EEE4), maxLines = 5)
            }
        }
    }
}

